# ===================== DB ==============
def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        conn.execute("PRAGMA foreign_keys=ON")
    except Exception:
        pass
    return conn

def now_utc_iso():
    """Return ISO timestamp in Africa/Johannesburg timezone (UTC+02:00)."""
    try:
        if ZoneInfo is not None:
            tz = ZoneInfo('Africa/Johannesburg')
            return datetime.datetime.now(tz).isoformat()
    except Exception:
        pass
    # Fallback: fixed UTC+02 offset if zoneinfo unavailable
    tz = datetime.timezone(datetime.timedelta(hours=2))
    return (datetime.datetime.utcnow() + datetime.timedelta(hours=2)).replace(tzinfo=tz).isoformat()


def format_chat_datetime(value):
    """
    Formats message timestamps nicely for chat screens.
    Example: 2026-03-21T08:25:00+02:00 -> 21 Mar 2026, 08:25
    """
    if not value:
        return ""

    try:
        dt = datetime.datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        return dt.strftime("%d %b %Y, %H:%M")
    except Exception:
        return str(value)[:16].replace("T", " ")
        
        
def grade_label(g):
    return str(g or "").replace("G", "Grade ")
    
    

def ensure_column(conn, table, column, ddl_tail):
    cur = conn.cursor()
    # -------- SAFE SUBJECTS GUARD --------
    try:
        cur.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='subjects'")
        if not cur.fetchone():
            init_db()
    except Exception:
        init_db()
    # -----------------------------------

    cur.execute(f"PRAGMA table_info({table})")
    cols = [r[1] for r in cur.fetchall()]
    if column not in cols:
        cur.execute(f"ALTER TABLE {table} ADD COLUMN {column} {ddl_tail}")

