def generate_short_code(prefix="EBTA", size=6):
    """
    Generates a short readable code.
    Example: D50-K7P9QW
    """
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    return prefix + "-" + "".join(secrets.choice(alphabet) for _ in range(size))


def ensure_student_referral_code(conn, student_id):
    """
    Every student must have one permanent referral code.
    """
    cur = conn.cursor()

    cur.execute("""
        SELECT referral_code
        FROM students
        WHERE id=?
        LIMIT 1
    """, (student_id,))

    row = cur.fetchone()

    if row and row["referral_code"]:
        return row["referral_code"]

    while True:
        code = generate_short_code("REF", 6)

        cur.execute("""
            SELECT id
            FROM students
            WHERE referral_code=?
            LIMIT 1
        """, (code,))

        if not cur.fetchone():
            break

    cur.execute("""
        UPDATE students
        SET referral_code=?
        WHERE id=?
    """, (code, student_id))

    return code


def ensure_tutor_referral_code(conn, tutor_id):
    """
    Every tutor gets one permanent referral code.
    Example: TUT-7K9Q2M
    """
    cur = conn.cursor()

    cur.execute("""
        SELECT referral_code
        FROM tutors
        WHERE id=?
        LIMIT 1
    """, (tutor_id,))

    row = cur.fetchone()

    if row and row["referral_code"]:
        return row["referral_code"]

    while True:
        code = generate_short_code("TUT", 6)

        cur.execute("""
            SELECT id
            FROM tutors
            WHERE referral_code=?
            LIMIT 1
        """, (code,))

        if not cur.fetchone():
            break

    cur.execute("""
        UPDATE tutors
        SET referral_code=?
        WHERE id=?
    """, (code, tutor_id))

    return code


def ensure_all_tutor_referral_codes(conn):
    """
    Creates referral codes for older tutors who existed before this feature.
    """
    cur = conn.cursor()

    cur.execute("""
        SELECT id
        FROM tutors
        WHERE referral_code IS NULL
           OR TRIM(referral_code) = ''
    """)

    rows = cur.fetchall()

    for r in rows:
        ensure_tutor_referral_code(conn, r["id"])


def award_tutor_referral_reward(conn, tutor_id, referred_student_id, referral_code, month):
    """
    Tutor referral reward rules:
    - Only new students should be awarded before this function is called.
    - Same referred student can only count once for the same tutor.
    - 3 referrals = R100
    - 5 referrals = R200
    - At 5, cycle points reset to 0.
    - Total referrals and total earnings stay cumulative.
    """

    if not tutor_id or not referred_student_id:
        return

    cur = conn.cursor()

    try:
        cur.execute("""
            INSERT INTO tutor_referral_uses(
                tutor_id,
                referred_student_id,
                referral_code,
                enrollment_month,
                reward_amount,
                reward_stage,
                created_at
            )
            VALUES(?,?,?,?,?,?,?)
        """, (
            tutor_id,
            referred_student_id,
            referral_code,
            month,
            0,
            "COUNTED",
            now_utc_iso()
        ))

    except sqlite3.IntegrityError:
        # This learner was already counted for this tutor.
        return

    cur.execute("""
        UPDATE tutors
        SET referral_points = COALESCE(referral_points, 0) + 1,
            referral_total_count = COALESCE(referral_total_count, 0) + 1
        WHERE id=?
    """, (tutor_id,))

    cur.execute("""
        SELECT referral_points
        FROM tutors
        WHERE id=?
        LIMIT 1
    """, (tutor_id,))

    row = cur.fetchone()
    points = int(row["referral_points"] or 0) if row else 0

    reward_amount = 0
    reward_stage = "COUNTED"

    if points == 3:
        reward_amount = 100
        reward_stage = "3_REFERRALS_R100"

    elif points >= 5:
        reward_amount = 200
        reward_stage = "5_REFERRALS_R200"

    if reward_amount > 0:
        cur.execute("""
            UPDATE tutor_referral_uses
            SET reward_amount=?,
                reward_stage=?
            WHERE tutor_id=?
              AND referred_student_id=?
        """, (
            reward_amount,
            reward_stage,
            tutor_id,
            referred_student_id
        ))

        cur.execute("""
            UPDATE tutors
            SET referral_earnings_total = COALESCE(referral_earnings_total, 0) + ?
            WHERE id=?
        """, (
            reward_amount,
            tutor_id
        ))

    if points >= 5:
        cur.execute("""
            UPDATE tutors
            SET referral_points = 0
            WHERE id=?
        """, (tutor_id,))


def recalculate_tutor_referral_totals(conn, tutor_id):
    """
    Recalculates tutor referral points and earnings after admin deletes a referral record.

    Rules:
    - 3 referrals in a cycle = R100
    - 5 referrals in a cycle = R200
    - After 5 referrals, current cycle points reset to 0
    - Total referrals and total earnings are recalculated from existing referral records
    """

    cur = conn.cursor()

    cur.execute("""
        SELECT id
        FROM tutor_referral_uses
        WHERE tutor_id=?
        ORDER BY created_at ASC, id ASC
    """, (tutor_id,))

    rows = cur.fetchall()

    total_referrals = 0
    current_cycle_points = 0
    total_earnings = 0

    for row in rows:
        total_referrals += 1
        current_cycle_points += 1

        reward_amount = 0
        reward_stage = "COUNTED"

        if current_cycle_points == 3:
            reward_amount = 100
            reward_stage = "3_REFERRALS_R100"

        elif current_cycle_points >= 5:
            reward_amount = 200
            reward_stage = "5_REFERRALS_R200"

        total_earnings += reward_amount

        cur.execute("""
            UPDATE tutor_referral_uses
            SET reward_amount=?,
                reward_stage=?
            WHERE id=?
        """, (
            reward_amount,
            reward_stage,
            row["id"]
        ))

        if current_cycle_points >= 5:
            current_cycle_points = 0

    cur.execute("""
        UPDATE tutors
        SET referral_points=?,
            referral_total_count=?,
            referral_earnings_total=?
        WHERE id=?
    """, (
        current_cycle_points,
        total_referrals,
        total_earnings,
        tutor_id
    ))


def ensure_all_student_referral_codes(conn):
    """
    Creates referral codes for older students who existed before this feature.
    """
    cur = conn.cursor()

    cur.execute("""
        SELECT id
        FROM students
        WHERE referral_code IS NULL
           OR TRIM(referral_code) = ''
    """)

    rows = cur.fetchall()

    for r in rows:
        ensure_student_referral_code(conn, r["id"])


def get_subject_fee_map(conn, subject_ids):
    """
    Returns fee per selected subject.
    Example: {'1': 200, '2': 250}
    """
    cur = conn.cursor()

    if not subject_ids:
        return {}

    placeholders = ",".join("?" * len(subject_ids))

    cur.execute(f"""
        SELECT id, grade
        FROM subjects
        WHERE id IN ({placeholders})
    """, subject_ids)

    fee_map = {}

    for row in cur.fetchall():
        fee_map[str(row["id"])] = fee_for_grade(row["grade"])

    return fee_map


def calculate_enrollment_fee_breakdown(conn, subject_ids, coupon_code="", student_id=None):
    """
    Calculates enrollment fees using the selected subjects.

    Rules:
    - Each selected subject uses its own grade fee.
    - Bulk discount still applies when 3+ subjects are selected.
    - A valid 50% or 100% discount coupon applies to ONE selected subject only.
    - Referral-only codes do not reduce the total.
    """

    subject_ids = [str(x) for x in subject_ids if str(x).strip()]

    result = {
        "valid": True,
        "message": "",
        "subtotal": 0,
        "bulk_discount": 0,
        "coupon_discount": 0,
        "total_discount": 0,
        "total_due": 0,
        "discounted_subject_fee": 0,
        "discount_percent": 0,
        "coupon_result": {
            "valid": True,
            "message": "",
            "code_type": "NONE",
            "discount_amount": 0,
            "coupon_id": None,
            "referral_owner_id": None,
            "tutor_referrer_id": None
        }
    }

    if not subject_ids:
        result["valid"] = False
        result["message"] = "No subjects selected."
        return result

    cur = conn.cursor()
    placeholders = ",".join("?" * len(subject_ids))

    cur.execute(f"""
        SELECT id, grade, name
        FROM subjects
        WHERE id IN ({placeholders})
    """, subject_ids)

    subjects = cur.fetchall()

    if not subjects:
        result["valid"] = False
        result["message"] = "Invalid subject selection."
        return result

    fee_map = {}

    for row in subjects:
        fee_map[str(row["id"])] = fee_for_grade(row["grade"])

    subtotal = sum(fee_map.values())
    count = len(subject_ids)

    result["subtotal"] = subtotal

    # Existing EBTA bulk discount rule
    if count >= 3:
        grades = [row["grade"] for row in subjects]

        if all(g == "G13" for g in grades):
            result["bulk_discount"] = int(round(subtotal * 0.10))
        else:
            result["bulk_discount"] = int(round(subtotal * 0.05))

    coupon_code = (coupon_code or "").strip().upper()

    if coupon_code:
        if student_id:
            coupon_result = validate_discount_or_referral_code(
                conn,
                coupon_code,
                student_id,
                subject_ids,
                subtotal
            )
        else:
            coupon_result = preview_discount_code_for_subjects(
                conn,
                coupon_code,
                subject_ids,
                subtotal
            )

        result["coupon_result"] = coupon_result

        if not coupon_result.get("valid"):
            result["valid"] = False
            result["message"] = coupon_result.get("message", "Invalid discount code.")
            return result

        result["coupon_discount"] = int(coupon_result.get("discount_amount", 0) or 0)

        # Work out visible discount percent for the front page
        cur.execute("""
            SELECT discount_percent
            FROM discount_coupons
            WHERE UPPER(code)=?
            LIMIT 1
        """, (coupon_code,))

        c = cur.fetchone()

        if c:
            result["discount_percent"] = int(c["discount_percent"] or 0)

    total_discount = result["bulk_discount"] + result["coupon_discount"]

    if total_discount > subtotal:
        total_discount = subtotal

    result["total_discount"] = total_discount
    result["total_due"] = subtotal - total_discount

    return result
    
    
def preview_discount_code_for_subjects(conn, code, subject_ids, subtotal):
    """
    Used only by the front page to preview discount totals before the student record exists.

    It does not award points and does not mark coupons as used.
    Backend validation still happens again during final registration.
    """

    code = (code or "").strip().upper()
    subject_ids_str = [str(x) for x in subject_ids]

    if not code:
        return {
            "valid": True,
            "message": "",
            "code_type": "NONE",
            "discount_amount": 0,
            "coupon_id": None,
            "referral_owner_id": None,
            "tutor_referrer_id": None
        }

    cur = conn.cursor()

    cur.execute("""
        SELECT *
        FROM discount_coupons
        WHERE UPPER(code)=?
          AND status='ACTIVE'
          AND used_count < max_uses
        LIMIT 1
    """, (code,))

    coupon = cur.fetchone()

    if not coupon:
        return {
            "valid": False,
            "message": "Invalid or already used discount code.",
            "code_type": "INVALID",
            "discount_amount": 0,
            "coupon_id": None,
            "referral_owner_id": None,
            "tutor_referrer_id": None
        }

    discount_percent = int(coupon["discount_percent"] or 0)

    if discount_percent not in [50, 100]:
        return {
            "valid": False,
            "message": "Only 50% and 100% discount codes are supported.",
            "code_type": "INVALID",
            "discount_amount": 0,
            "coupon_id": None,
            "referral_owner_id": None,
            "tutor_referrer_id": None
        }

    fee_map = get_subject_fee_map(conn, subject_ids_str)

    if not fee_map:
        return {
            "valid": False,
            "message": "No valid subject selected for this discount code.",
            "code_type": "INVALID",
            "discount_amount": 0,
            "coupon_id": None,
            "referral_owner_id": None,
            "tutor_referrer_id": None
        }

    discount_base = 0

    if coupon["applies_to"] == "SUBJECT":
        subject_id = str(coupon["subject_id"] or "")

        if subject_id not in subject_ids_str:
            return {
                "valid": False,
                "message": "This code applies to a subject that was not selected.",
                "code_type": "INVALID",
                "discount_amount": 0,
                "coupon_id": None,
                "referral_owner_id": None,
                "tutor_referrer_id": None
            }

        discount_base = fee_map.get(subject_id, 0)

    else:
        # ALL or ANY_SUBJECT discount codes must only discount ONE selected subject.
        # We use the highest selected subject fee.
        discount_base = max(fee_map.values())

    discount_amount = int(round(discount_base * (discount_percent / 100)))

    return {
        "valid": True,
        "message": f"{discount_percent}% discount applied to one selected subject.",
        "code_type": coupon["source"] or "MANUAL",
        "discount_amount": discount_amount,
        "coupon_id": coupon["id"],
        "referral_owner_id": None,
        "tutor_referrer_id": None
    }


def validate_discount_or_referral_code(conn, code, student_id, subject_ids, subtotal):
    """
    Validates coupon/referral code during registration.

    Returns:
    {
        valid: True/False,
        message: "...",
        code_type: MANUAL | REFERRAL_REWARD | REFERRAL_ONLY | NONE | INVALID,
        discount_amount: number,
        coupon_id: id or None,
        referral_owner_id: student_id or None
    }
    """

    code = (code or "").strip().upper()

    if not code:
        return {
            "valid": True,
            "message": "",
            "code_type": "NONE",
            "discount_amount": 0,
            "coupon_id": None,
            "referral_owner_id": None,
            "tutor_referrer_id": None
        }

    cur = conn.cursor()

    # 1. Check discount coupon first
    cur.execute("""
        SELECT *
        FROM discount_coupons
        WHERE UPPER(code)=?
          AND status='ACTIVE'
          AND used_count < max_uses
        LIMIT 1
    """, (code,))

    coupon = cur.fetchone()

    if coupon:
        target_student_id = coupon["target_student_id"]

        if target_student_id and int(target_student_id) != int(student_id):
            return {
                "valid": False,
                "message": "This discount code belongs to another learner.",
                "code_type": "INVALID",
                "discount_amount": 0,
                "coupon_id": None,
                "referral_owner_id": None,
                "tutor_referrer_id": None
            }

        discount_percent = int(coupon["discount_percent"] or 0)

        if discount_percent not in [50, 100]:
            return {
                "valid": False,
                "message": "Invalid discount percentage on this code.",
                "code_type": "INVALID",
                "discount_amount": 0,
                "coupon_id": None,
                "referral_owner_id": None,
                "tutor_referrer_id": None
            }

        subject_ids_str = [str(x) for x in subject_ids]
        fee_map = get_subject_fee_map(conn, subject_ids_str)

        if not fee_map:
            return {
                "valid": False,
                "message": "No valid subject was selected for this discount code.",
                "code_type": "INVALID",
                "discount_amount": 0,
                "coupon_id": None,
                "referral_owner_id": None,
                "tutor_referrer_id": None
            }

        discount_base = 0

        if coupon["applies_to"] == "SUBJECT":
            subject_id = str(coupon["subject_id"] or "")

            if subject_id not in subject_ids_str:
                return {
                    "valid": False,
                    "message": "This discount code applies to a subject that was not selected.",
                    "code_type": "INVALID",
                    "discount_amount": 0,
                    "coupon_id": None,
                    "referral_owner_id": None,
                    "tutor_referrer_id": None
                }

            discount_base = fee_map.get(subject_id, 0)

        else:
            # ALL or ANY_SUBJECT must discount ONE selected subject only.
            # This matches the front-page preview logic.
            discount_base = max(fee_map.values())

        discount_amount = int(round(discount_base * (discount_percent / 100)))

        return {
            "valid": True,
            "message": f"{discount_percent}% discount applied.",
            "code_type": coupon["source"] or "MANUAL",
            "discount_amount": discount_amount,
            "coupon_id": coupon["id"],
            "referral_owner_id": None,
            "tutor_referrer_id": None
        }

    # 2. Check student referral code
    cur.execute("""
        SELECT id, full_name
        FROM students
        WHERE UPPER(referral_code)=?
        LIMIT 1
    """, (code,))

    referrer = cur.fetchone()

    if referrer:
        if int(referrer["id"]) == int(student_id):
            return {
                "valid": False,
                "message": "You cannot use your own referral code.",
                "code_type": "INVALID",
                "discount_amount": 0,
                "coupon_id": None,
                "referral_owner_id": None,
                "tutor_referrer_id": None
            }

        return {
            "valid": True,
            "message": "Student referral code accepted. It does not discount this enrollment.",
            "code_type": "REFERRAL_ONLY",
            "discount_amount": 0,
            "coupon_id": None,
            "referral_owner_id": referrer["id"],
            "tutor_referrer_id": None
        }

    # 3. Check tutor referral code
    cur.execute("""
        SELECT id, full_name
        FROM tutors
        WHERE UPPER(referral_code)=?
        LIMIT 1
    """, (code,))

    tutor_referrer = cur.fetchone()

    if tutor_referrer:
        return {
            "valid": True,
            "message": "Tutor referral code accepted. It does not discount this enrollment.",
            "code_type": "TUTOR_REFERRAL",
            "discount_amount": 0,
            "coupon_id": None,
            "referral_owner_id": None,
            "tutor_referrer_id": tutor_referrer["id"]
        }

    return {
        "valid": False,
        "message": "Invalid coupon or referral code.",
        "code_type": "INVALID",
        "discount_amount": 0,
        "coupon_id": None,
        "referral_owner_id": None,
        "tutor_referrer_id": None
    }

def award_referral_point_and_rewards(conn, referrer_student_id, referred_student_id, referral_code, month):
    """
    Adds one referral point to the owner of the referral code.

    Rules:
    - Same referred learner can only count once for the same referrer.
    - At 3 points, generate 50% reward code.
    - At 5 points, generate 100% reward code and reset current points to 0.
    - Lifetime total continues increasing.
    """

    if not referrer_student_id or not referred_student_id:
        return

    cur = conn.cursor()

    try:
        cur.execute("""
            INSERT INTO referral_uses(
                referrer_student_id,
                referred_student_id,
                referral_code,
                enrollment_month,
                created_at
            )
            VALUES(?,?,?,?,?)
        """, (
            referrer_student_id,
            referred_student_id,
            referral_code,
            month,
            now_utc_iso()
        ))
    except sqlite3.IntegrityError:
        # Already counted before
        return

    cur.execute("""
        UPDATE students
        SET referral_points = COALESCE(referral_points, 0) + 1,
            referral_total_count = COALESCE(referral_total_count, 0) + 1
        WHERE id=?
    """, (referrer_student_id,))

    cur.execute("""
        SELECT referral_points
        FROM students
        WHERE id=?
    """, (referrer_student_id,))

    row = cur.fetchone()
    points = int(row["referral_points"] or 0) if row else 0

    # 3 points reward = 50% discount
    if points == 3:
        cur.execute("""
            SELECT id
            FROM discount_coupons
            WHERE owner_student_id=?
              AND source='REFERRAL_REWARD'
              AND discount_percent=50
              AND status='ACTIVE'
            LIMIT 1
        """, (referrer_student_id,))

        if not cur.fetchone():
            while True:
                code = generate_short_code("R50", 6)

                cur.execute("SELECT id FROM discount_coupons WHERE code=?", (code,))

                if not cur.fetchone():
                    break

            cur.execute("""
                INSERT INTO discount_coupons(
                    code,
                    target_student_id,
                    owner_student_id,
                    discount_percent,
                    applies_to,
                    subject_id,
                    source,
                    status,
                    max_uses,
                    used_count,
                    created_by_role,
                    created_by_id,
                    created_at,
                    notes
                )
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """, (
                code,
                referrer_student_id,
                referrer_student_id,
                50,
                "ANY_SUBJECT",
                None,
                "REFERRAL_REWARD",
                "ACTIVE",
                1,
                0,
                "system",
                None,
                now_utc_iso(),
                "Auto-generated referral reward at 3 points."
            ))

    # 5 points reward = 100% discount, then reset cycle points
    if points >= 5:
        while True:
            code = generate_short_code("R100", 6)

            cur.execute("SELECT id FROM discount_coupons WHERE code=?", (code,))

            if not cur.fetchone():
                break

        cur.execute("""
            INSERT INTO discount_coupons(
                code,
                target_student_id,
                owner_student_id,
                discount_percent,
                applies_to,
                subject_id,
                source,
                status,
                max_uses,
                used_count,
                created_by_role,
                created_by_id,
                created_at,
                notes
            )
            VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """, (
            code,
            referrer_student_id,
            referrer_student_id,
            100,
            "ANY_SUBJECT",
            None,
            "REFERRAL_REWARD",
            "ACTIVE",
            1,
            0,
            "system",
            None,
            now_utc_iso(),
            "Auto-generated referral reward at 5 points."
        ))

        cur.execute("""
            UPDATE students
            SET referral_points=0
            WHERE id=?
        """, (referrer_student_id,))


def mark_coupon_used(conn, coupon_id):
    """
    Marks a discount coupon as used after successful enrollment.
    """
    if not coupon_id:
        return

    cur = conn.cursor()

    cur.execute("""
        UPDATE discount_coupons
        SET used_count = used_count + 1,
            status = CASE
                WHEN used_count + 1 >= max_uses THEN 'USED'
                ELSE status
            END,
            used_at = ?
        WHERE id=?
    """, (now_utc_iso(), coupon_id))


def pagination_controls(base_path, page_num, total_pages, query_params=None):
    """
    Builds First / Prev / Page X / Next / Last pagination links.
    query_params keeps search filters when changing pages.
    """
    query_params = query_params or {}

    clean_params = {}

    for key, value in query_params.items():
        if value not in [None, ""]:
            clean_params[key] = value

    def page_link(label, target_page, css="secondary"):
        params = dict(clean_params)
        params["page"] = target_page
        return f"<a class='btn mini {css}' href='{base_path}?{urlencode(params)}'>{label}</a>"

    if total_pages <= 1:
        return ""

    links = []

    if page_num > 1:
        links.append(page_link("First", 1))
        links.append(page_link("Prev", page_num - 1))

    links.append(f"<span class='chip'>Page {page_num} / {total_pages}</span>")

    if page_num < total_pages:
        links.append(page_link("Next", page_num + 1))
        links.append(page_link("Last", total_pages))

    return f"""
    <div class="toolbar" style="justify-content:center;margin:12px 0;gap:6px;flex-wrap:wrap">
        {''.join(links)}
    </div>
    """


