def secure_name(name):
    keep="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-"
    return ''.join(ch if ch in keep else '_' for ch in name)
    
    
def save_uploaded_files_as_single_file(files, target_dir, prefix, public_url_prefix=None):
    """
    Saves one or multiple uploaded files.

    If one file is uploaded:
    - Saves the file normally.

    If multiple files are uploaded:
    - Bundles them into one ZIP file.

    Returns:
    - saved_path
    - file_count

    If public_url_prefix is provided, it returns a URL path.
    If public_url_prefix is not provided, it returns the real server file path.
    """

    clean_files = []

    for f in files:
        if f and f.filename and f.filename.strip():
            clean_files.append(f)

    if not clean_files:
        return None, 0

    target_dir.mkdir(parents=True, exist_ok=True)

    timestamp = int(time.time())
    unique_token = secrets.token_hex(4)
    prefix = secure_name(str(prefix))

    # One file only
    if len(clean_files) == 1:
        original_name = secure_name(clean_files[0].filename)
        saved_name = f"{timestamp}_{unique_token}_{prefix}_{original_name}"
        destination = target_dir / saved_name

        clean_files[0].save(destination)

        if public_url_prefix:
            return f"{public_url_prefix}/{saved_name}", 1

        return str(destination), 1

    # Multiple files, bundle into ZIP
    zip_name = f"{timestamp}_{unique_token}_{prefix}_multiple_files.zip"
    zip_path = target_dir / zip_name

    with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as zf:
        for index, f in enumerate(clean_files, start=1):
            original_name = secure_name(f.filename)
            inside_zip_name = f"{index}_{original_name}"

            file_bytes = f.read()
            zf.writestr(inside_zip_name, file_bytes)

    if public_url_prefix:
        return f"{public_url_prefix}/{zip_name}", len(clean_files)

    return str(zip_path), len(clean_files)
    
    
def resolve_submission_file_path(saved_path):
    """
    Converts a saved submission/marked-script path into a real server file path.
    Handles both:
    - /var/data/submissions/file.pdf
    - /submission-files/file.pdf
    - file.pdf
    """

    if not saved_path:
        return None

    saved_path = str(saved_path).strip()

    if saved_path.startswith("/submission-files/"):
        return str(SUBMISSIONS_DIR / os.path.basename(saved_path))

    p = Path(saved_path)

    if p.is_absolute():
        return str(p)

    return str(SUBMISSIONS_DIR / os.path.basename(saved_path)) 
 
    
def clean_multiline_text(text):
    if not text:
        return ""

    lines = str(text).replace("\r\n", "\n").replace("\r", "\n").split("\n")

    cleaned_lines = []

    for line in lines:
        cleaned_lines.append(line.strip())

    # Remove empty lines at the start
    while cleaned_lines and cleaned_lines[0] == "":
        cleaned_lines.pop(0)

    # Remove empty lines at the end
    while cleaned_lines and cleaned_lines[-1] == "":
        cleaned_lines.pop()

    return "\n".join(cleaned_lines)
    
    
def normalise_name_for_match(name):
    """
    Clean a name so that matching is easier.
    This removes symbols, extra spaces, and ignores capital letters.
    """
    if not name:
        return ""

    import re

    cleaned = str(name).lower().strip()

    # Remove punctuation and symbols, but keep letters, numbers, and spaces
    cleaned = re.sub(r"[^a-z0-9\s]", " ", cleaned)

    # Convert multiple spaces into one space
    cleaned = " ".join(cleaned.split())

    return cleaned


def name_tokens_for_match(name):
    """
    Turns a full name into separate clean words.

    Example:
    'Radebe   Fumane Mthandeni'
    becomes:
    ['radebe', 'fumane', 'mthandeni']
    """
    cleaned = normalise_name_for_match(name)

    if not cleaned:
        return []

    return [x for x in cleaned.split() if x]


def name_match_score(award_name, portal_name):
    """
    Gives a match score between the name from the awards list
    and the name stored in the portal.

    Handles:
    - name then surname
    - surname then name
    - middle names
    - extra spaces
    - different capital letters
    """

    award_tokens = name_tokens_for_match(award_name)
    portal_tokens = name_tokens_for_match(portal_name)

    if not award_tokens or not portal_tokens:
        return 0

    award_set = set(award_tokens)
    portal_set = set(portal_tokens)

    common = award_set.intersection(portal_set)

    # Exact cleaned name match
    if normalise_name_for_match(award_name) == normalise_name_for_match(portal_name):
        return 100

    # Same words, but different order
    # Example: "Radebe Fumane" and "Fumane Radebe"
    if award_set == portal_set:
        return 95

    # All awards name words exist inside portal name
    # Example: award = "Fumane Radebe", portal = "Fumane Mthandeni Radebe"
    if award_set.issubset(portal_set):
        return 90

    # All portal name words exist inside award name
    if portal_set.issubset(award_set):
        return 88

    # First and last words match in the same order
    if len(award_tokens) >= 2 and len(portal_tokens) >= 2:
        award_first = award_tokens[0]
        award_last = award_tokens[-1]
        portal_first = portal_tokens[0]
        portal_last = portal_tokens[-1]

        if award_first == portal_first and award_last == portal_last:
            return 85

        # First and last words match in reverse order
        # Example: award = "Radebe Fumane", portal = "Fumane Radebe"
        if award_first == portal_last and award_last == portal_first:
            return 82

    # At least two name words match
    if len(common) >= 2:
        return 75

    # Single-name cases like "Luyanda"
    if len(award_tokens) == 1 and award_tokens[0] in portal_set:
        return 55

    return 0    


def parse_awards_student_list(raw_text):
    """
    Parses pasted award list data.

    Supports lines like:
    1   Fumane Mthandeni Radebe   8   Overall Top 1 + EMS 1st
    2   Letlotlo Modise           8   EMS 2nd + Most Active

    Returns a list of dictionaries:
    {
        "list_no": "1",
        "learner_name": "...",
        "grade": "8",
        "award_category": "..."
    }
    """

    if not raw_text:
        return []

    rows = []

    text = str(raw_text).replace("\r\n", "\n").replace("\r", "\n")

    for line in text.split("\n"):
        line = line.strip()

        if not line:
            continue

        # Skip headings or title lines
        lower = line.lower()
        if (
            "ebta term" in lower
            or "complete student list" in lower
            or lower.startswith("#")
            or "learner name" in lower
            or "award category" in lower
        ):
            continue

        # Prefer tab-separated data
        parts = [p.strip() for p in line.split("\t") if p.strip()]

        # If pasted spaces instead of tabs, try a softer split
        if len(parts) < 4:
            import re
            parts = re.split(r"\s{2,}", line)
            parts = [p.strip() for p in parts if p.strip()]

        # Expected:
        # number | learner name | grade | award category
        if len(parts) >= 4 and parts[0].isdigit():
            rows.append({
                "list_no": parts[0],
                "learner_name": parts[1],
                "grade": parts[2],
                "award_category": " ".join(parts[3:])
            })
            continue

        # Fallback for lines like:
        # 1 Fumane Mthandeni Radebe 8 Overall Top 1 + EMS 1st
        import re
        m = re.match(r"^(\d+)\s+(.+?)\s+(8|9|10|11|12|13)\s+(.+)$", line)

        if m:
            rows.append({
                "list_no": m.group(1).strip(),
                "learner_name": m.group(2).strip(),
                "grade": m.group(3).strip(),
                "award_category": m.group(4).strip()
            })

    return rows
    
    

