@app.post('/api/returning-student-lookup')
def returning_student_lookup():

    full_name = request.form.get("full_name", "").strip()
    phone_raw = request.form.get("phone", "").strip()
    phone_type = request.form.get("phone_type", "SA").strip()
    pin = request.form.get("pin", "").strip()

    # Silent fail: new students must not be scared by lookup messages.
    if not full_name or not phone_raw or not pin:
        return {
            "ok": False,
            "silent": True
        }

    if not is_valid_pin(pin):
        return {
            "ok": False,
            "silent": True
        }

    try:
        phone = normalize_phone(phone_raw, phone_type, strict=True)
    except ValueError:
        return {
            "ok": False,
            "silent": True
        }

    variants = phone_variants(phone)

    conn = get_db()
    cur = conn.cursor()

    placeholders = ",".join("?" * len(variants))

    cur.execute(f"""
        SELECT
            id,
            full_name,
            phone_whatsapp,
            phone_type,
            guardian_name,
            guardian_phone,
            guardian_phone_type,
            email,
            province,
            school,
            grade
        FROM students
        WHERE phone_whatsapp IN ({placeholders})
          AND pin=?
        LIMIT 1
    """, variants + [pin])

    student = cur.fetchone()
    conn.close()

    # Silent fail: this is likely a new student, so let them continue normally.
    if not student:
        return {
            "ok": False,
            "silent": True
        }

    return {
        "ok": True,
        "message": "Returning student found. Your saved details have been loaded, but you can still edit them.",
        "student": {
            "full_name": student["full_name"] or "",
            "phone_whatsapp": student["phone_whatsapp"] or "",
            "phone_type": student["phone_type"] or "SA",
            "guardian_name": student["guardian_name"] or "",
            "guardian_phone": student["guardian_phone"] or "",
            "guardian_phone_type": student["guardian_phone_type"] or "SA",
            "email": student["email"] or "",
            "province": student["province"] or "",
            "school": student["school"] or "",
            "grade": student["grade"] or ""
        }
    }


@app.post('/register/discount-preview')
def register_discount_preview():

    data = request.get_json(silent=True) or {}

    subject_ids = data.get("subject_ids", [])
    coupon_code = data.get("coupon_code", "")

    if not isinstance(subject_ids, list):
        subject_ids = []

    conn = get_db()

    breakdown = calculate_enrollment_fee_breakdown(
        conn,
        subject_ids,
        coupon_code=coupon_code,
        student_id=None
    )

    conn.close()

    return {
        "valid": breakdown["valid"],
        "message": breakdown["message"] or breakdown["coupon_result"].get("message", ""),
        "subtotal": breakdown["subtotal"],
        "bulk_discount": breakdown["bulk_discount"],
        "coupon_discount": breakdown["coupon_discount"],
        "total_discount": breakdown["total_discount"],
        "total_due": breakdown["total_due"],
        "discount_percent": breakdown["discount_percent"]
    }


@app.post('/register')
def register():
    if get_setting('enrollment_open', '1') != '1':
        return page(
            "Enrollments Closed",
            card_msg(
                get_setting(
                    'enrollment_message',
                    'Enrollments are currently closed.'
                )
            )
        )
    full_name = request.form.get('full_name','').strip()
    phone_type = request.form.get("phone_type", "SA")
    guardian_phone_type = request.form.get("guardian_phone_type", "SA")

    try:
        phone = normalize_phone(request.form.get("phone",""), phone_type, strict=True)

        guardian = normalize_phone(request.form.get("guardian",""),guardian_phone_type, strict=True)
        
    except ValueError as e:
        return page("Error", card_msg(str(e)))
    
    guardian_name = request.form.get('guardian_name','').strip()
    email = request.form.get('email','').strip() or None
    subject_ids = request.form.getlist('subject_ids')
    pin = request.form.get('pin','').strip()
    pops = request.files.getlist('pop')
    province = request.form.get('province')
    school = request.form.get('school')
    
    coupon_code = request.form.get("coupon_code", "").strip().upper()

    amount_paid = request.form.get('amount_paid', '').strip()

    try:
        amount_paid = int(amount_paid)
    except ValueError:
        return page("Error", card_msg("Invalid amount paid."))


    amount_paid = int(amount_paid)

    
    # Validation
    if not (full_name and phone and guardian and guardian_name and subject_ids and pin):
        return page("Error", card_msg("All fields are required."))

    if not is_valid_pin(pin):
        return page("Error", card_msg("PIN must be exactly 5 digits."))

    conn = get_db()
    ensure_registration_table(conn)
    cur = conn.cursor()

    # Check existing student
    variants = phone_variants(phone)

    placeholders = ",".join("?" * len(variants))

    cur.execute(f"""
        SELECT id, pin
        FROM students
        WHERE phone_whatsapp IN ({placeholders})
        LIMIT 1
    """, variants)
    srow = cur.fetchone()

    # Derive grade from first selected subject.
    cur.execute("SELECT grade FROM subjects WHERE id=?", (subject_ids[0],))
    r0 = cur.fetchone()

    if not r0:
        conn.close()
        return page("Error", card_msg("Invalid subject selection."))

    derived_grade = r0["grade"]

    if srow:
        if srow['pin'] != pin:
            conn.close()
            return page("Error", card_msg("Incorrect PIN for this phone number."))

        sid = srow['id']

        # Update editable details for returning students.
        cur.execute("""
            UPDATE students
            SET full_name=?,
                guardian_phone=?,
                guardian_name=?,
                email=?,
                grade=?,
                province=?,
                school=?,
                phone_type=?,
                guardian_phone_type=?
            WHERE id=?
        """, (
            full_name,
            guardian,
            guardian_name,
            email,
            derived_grade,
            province,
            school,
            phone_type,
            guardian_phone_type,
            sid
        ))

    else:
        cur.execute("""
            INSERT INTO students(
                full_name,
                phone_whatsapp,
                guardian_phone,
                guardian_name,
                email,
                grade,
                pin,
                created_at,
                province,
                school,
                phone_type,
                guardian_phone_type
            )
            VALUES(?,?,?,?,?,?,?,?,?,?,?,?)
        """, (
            full_name,
            phone,
            guardian,
            guardian_name,
            email,
            derived_grade,
            pin,
            now_utc_iso(),
            province,
            school,
            phone_type,
            guardian_phone_type
        ))

        sid = cur.lastrowid

        ensure_student_referral_code(conn, sid)

    # Annual registration (optional)
    try:
        year = datetime.date.today().strftime('%Y')
        if not student_registered_for_year(conn, sid, year):
            if request.form.get('paid_check'):
                cur.execute(
                    "INSERT INTO registrations(student_id,year,amount,created_at) VALUES(?,?,?,?)",
                    (sid, year, 50, now_utc_iso())
                )
    except Exception:
        pass

    month = get_setting('current_month', datetime.date.today().strftime('%Y-%m'))

    cur.execute("SELECT subject_id FROM enrollments WHERE student_id=? AND month=?", (sid, month))
    existing = {str(x['subject_id']) for x in cur.fetchall()}
    
    
    # ================= SERVER-SIDE FEE CALCULATION =================

    fee_breakdown = calculate_enrollment_fee_breakdown(
        conn,
        subject_ids,
        coupon_code=coupon_code,
        student_id=sid
    )

    if not fee_breakdown["valid"]:
        conn.close()
        return page("Discount Code Error", card_msg(fee_breakdown["message"]))

    subtotal = fee_breakdown["subtotal"]
    bulk_discount = fee_breakdown["bulk_discount"]
    coupon_discount = fee_breakdown["coupon_discount"]
    total_discount = fee_breakdown["total_discount"]
    total_due = fee_breakdown["total_due"]
    coupon_result = fee_breakdown["coupon_result"]

    # The entered amount must match the final calculated total.
    # If a valid 50% or 100% code is used, total_due is already reduced.
    if amount_paid != total_due:
        conn.close()
        return page(
            "Payment error",
            card_msg(
                f"You need to pay R{total_due}. "
                f"Subtotal: R{subtotal}, Discount: R{total_discount}."
            )
        )

    # ================= PROOF OF PAYMENT VALIDATION =================

    pops = [f for f in pops if f and f.filename]

    # Require PoP whenever the parent says they paid something.
    # If they enter R0 because of a code, allow no PoP and let admin review.
    if amount_paid > 0:
        if len(pops) < 1 or len(pops) > 2:
            conn.close()
            return page("Error", card_msg("Upload 1 or 2 Proof of Payment files."))
    else:
        pops = []

    # Save PoP files only after the final amount has been validated.
    saved_paths = []
    ts = int(datetime.datetime.now().timestamp())

    for idx, pop in enumerate(pops, start=1):
        safe = f"{ts}_{secrets.token_hex(8)}_{idx}_{secure_name(pop.filename)}"
        dest = UPLOAD_DIR / safe
        pop.save(dest)
        saved_paths.append(f"/uploads/{safe}")
        

    is_new_referral_student = is_first_time_student(conn, sid)
    
    created = []
    
    coupon_saved_on_enrollment = False
    
    # Check if this learner is completely new before this enrollment is created.
    # Tutor referral rewards must only count new students.
    cur.execute("""
        SELECT COUNT(*) AS c
        FROM enrollments
        WHERE student_id=?
    """, (sid,))

    existing_enrollment_count = cur.fetchone()["c"] or 0
    is_new_student_for_referral = existing_enrollment_count == 0

    for subid in subject_ids:
        if subid in existing:
            continue

        token = secrets.token_urlsafe(16)
        
        first_pop = saved_paths[0] if saved_paths else None

        # 1️⃣ Insert enrollment FIRST
        coupon_code_for_row = None
        coupon_discount_for_row = 0
        coupon_type_for_row = None
        referral_code_for_row = None

        # Save coupon details on only ONE enrollment row.
        # This prevents the admin side from showing the same discount multiple times.
        if coupon_code and not coupon_saved_on_enrollment:
            coupon_code_for_row = coupon_code
            coupon_discount_for_row = coupon_discount
            coupon_type_for_row = coupon_result["code_type"]

            if coupon_result["code_type"] in ["REFERRAL_ONLY", "TUTOR_REFERRAL"]:
                referral_code_for_row = coupon_code

        cur.execute("""
        INSERT INTO enrollments(
            student_id,
            subject_id,
            month,
            status,
            payment_method,
            payment_ref,
            pop_url,
            amount_paid,
            coupon_code,
            coupon_discount_amount,
            coupon_type,
            referral_code_used,
            status_token,
            created_at
        )
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        """, (
            sid,
            subid,
            month,
            "PENDING",
            "EFT",
            None,
            first_pop,
            amount_paid,
            coupon_code_for_row,
            coupon_discount_for_row,
            coupon_type_for_row,
            referral_code_for_row,
            token,
            now_utc_iso()
        ))

        if coupon_code and not coupon_saved_on_enrollment:
            coupon_saved_on_enrollment = True

        # 2️⃣ Now eid is valid
        eid = cur.lastrowid

        # 3️⃣ Generate reference AFTER eid exists
        payment_ref = f"EFT-{eid}-{int(datetime.datetime.now().timestamp())}"

        # 4️⃣ Update enrollment with reference
        cur.execute(
            "UPDATE enrollments SET payment_ref=? WHERE id=?",
            (payment_ref, eid)
        )

        # 5️⃣ Insert payment record
        cur.execute("""
        INSERT INTO payments(
            enrollment_id,
            amount,
            gateway,
            reference,
            result,
            timestamp
        ) VALUES (?,?,?,?,?,?)
        """, (
            eid,
            amount_paid,
            'EFT',
            payment_ref,
            'PENDING',
            now_utc_iso()
        ))

        # 6️⃣ Save PoP files
        for pth in saved_paths:
            cur.execute(
                "INSERT INTO enrollment_files(enrollment_id,file_path) VALUES(?,?)",
                (eid, pth)
            )

        created.append((eid, token))
        
    if created:
        mark_coupon_used(conn, coupon_result.get("coupon_id"))

        if coupon_result.get("code_type") == "REFERRAL_ONLY":
            if not is_new_referral_student:
                conn.rollback()
                conn.close()
                return page(
                    "Referral Code Not Allowed",
                    card_msg("Referral codes can only be used by new EBTA learners.")
                )

            award_referral_point_and_rewards(
                conn,
                coupon_result.get("referral_owner_id"),
                sid,
                coupon_code,
                month
            )
        # Tutor referral reward
        # This only counts if the learner is new to EBTA.
        if is_new_student_for_referral and coupon_result.get("tutor_referrer_id"):
            award_tutor_referral_reward(
                conn,
                coupon_result.get("tutor_referrer_id"),
                sid,
                coupon_code.strip().upper() if coupon_code else "",
                month
            )

    conn.commit()
    conn.close()

    if not created:
        return page("No change", card_msg("Already enrolled for selected subjects this month."))

    if len(created) == 1:
        eid, tok = created[0]
        return redirect(url_for('status', id=eid) + '?' + urlencode({'token': tok}))

    links = "".join(
        f"<li><a class='links' target='_blank' href='{url_for('status', id=e)}?{urlencode({'token': t})}'>Enrollment #{e}</a></li>"
        for e, t in created
    )

    return page("Submitted", f"""
    <section class='wrap small'>
        <div class='card'>
            <h1>Enrollment submitted</h1>
            <ul>{links}</ul>
        </div>
    </section>
    """)



@app.get('/admin/registered')
def admin_registered():
    r = require_admin()
    if r: return r
    conn = get_db(); cur = conn.cursor()
    ensure_registration_table(conn)
    # get distinct years from registrations, fallback to current year
    cur.execute("SELECT DISTINCT year FROM registrations ORDER BY year DESC")
    years = [r['year'] for r in cur.fetchall()] or [datetime.date.today().strftime('%Y')]
    selected_year = request.args.get('year') or (years[0] if years else datetime.date.today().strftime('%Y'))
    # counts and listing
    cur.execute("SELECT COUNT(*) AS c FROM registrations WHERE year=?", (selected_year,))
    total = cur.fetchone()['c']
    cur.execute("SELECT r.id, r.student_id, r.amount, r.created_at, s.full_name, s.phone_whatsapp, s.grade FROM registrations r JOIN students s ON s.id=r.student_id WHERE r.year=? ORDER BY s.full_name", (selected_year,))
    rows = cur.fetchall()
    conn.close()
    year_options = ''.join([f"<option value='{y}' {'selected' if y==selected_year else ''}>{y}</option>" for y in years])
    rows_html = ''
    if not rows:
        rows_html = "<div class='empty'>No registrations for this year.</div>"
    else:
        rrows = []
        for rr in rows:
            when = rr['created_at'][:16].replace('T',' ')
            rrows.append(f"<tr><td>{rr['full_name']}</td><td>{rr['phone_whatsapp']}</td><td>{grade_label(rr['grade'])}</td><td>R{rr['amount']}</td><td>{when}</td></tr>")
        rows_html = (
            "<div class='scroll-x'>"
            "<table>"
            "<thead><tr>"
            "<th>Student</th><th>Phone</th><th>Grade</th><th>Amount</th><th>Registered at</th>"
            "</tr></thead>"
            f"<tbody>{''.join(rrows)}</tbody>"
            "</table></div>"
        )

    body = f"""
    <section class='grid'>
    <div class='card'>
        <h1>Registered students — {selected_year}</h1>
        <div class='toolbar'>
        <form method='get' action='{url_for('admin_registered')}' style='display:inline-block;margin-right:12px'>
            <label class='mini muted'>Filter by year</label>
            <select name='year' onchange='this.form.submit()'>
            {year_options}
            </select>
        </form>
        <div class='chip'>Total: {total}</div>
        </div>
        <div style='margin-top:12px'>{rows_html}</div>
    </div>
    </section>
    """
    return page('Registered students', body)

@app.get("/admin/normalize-phones")
def normalize_all_phones():
    r = require_admin()
    if r:
        return r

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT id, phone_whatsapp, phone_type FROM students")
    rows = cur.fetchall()

    for row in rows:
        phone_type = row["phone_type"] or "SA"
        normalized = normalize_phone(row["phone_whatsapp"], phone_type)

        if normalized:
            cur.execute(
                "UPDATE students SET phone_whatsapp=? WHERE id=?",
                (normalized, row["id"])
            )

    conn.commit()
    conn.close()

    return "All student numbers normalized safely."

# ===================== Status page ==============
@app.get('/status/<int:id>')
def status(id: int):
    token = request.args.get('token')
    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT e.*, s.full_name, s.phone_whatsapp, sub.name AS subject_name, sub.id AS subject_id
        FROM enrollments e
        JOIN students s ON s.id = e.student_id
        JOIN subjects sub ON sub.id = e.subject_id
        WHERE e.id = ?
    """, (id,))
    e = cur.fetchone()

    if not e:
        conn.close()
        return page("Not found", card_msg("Enrollment not found."))

    if token and token != e['status_token']:
        conn.close()
        return page("Forbidden", card_msg("Invalid token."))

    cur.execute("""
        SELECT invite_link 
        FROM groups 
        WHERE subject_id = ? AND month = ? 
        ORDER BY id DESC 
        LIMIT 1
    """, (e['subject_id'], e['month']))
    g = cur.fetchone()

    cur.execute("""
        SELECT file_path 
        FROM enrollment_files 
        WHERE enrollment_id = ?
    """, (id,))
    pops = [r['file_path'] for r in cur.fetchall()]

    conn.close()

    gl = g['invite_link'] if g else None

    join = (
        f"<a class='btn success' target='_blank' href='{gl}'>Join WhatsApp Group</a>"
        if (e['status'] == 'ACTIVE' and gl)
        else (
            "<div class='muted mini'>"
            "<strong>Next steps:</strong> Once your enrollment is approved (usually within 14 days), "
            "you’ll be able to log in on the Student Portal using the phone number you used to enroll "
            "and your 5-digit PIN to access all classes and learning materials."
            "</div>"
        )
    )

    pop_list = (
        " • ".join([f"<a class='links' href='{p}' target='_blank'>PoP</a>" for p in pops])
        if pops else "—"
    )

    body = fr"""
    <a class='links' href='/'>← Back</a>
    <section class='grid'>
        <div class='card'>
            <h1>Hello {e['full_name']}</h1>
            <p class='muted'>Subject: {e['subject_name']} • Month: {pretty_month_label(e['month'])}</p>
            <p>Status: <span class='chip {e['status'].lower()}'>{e['status']}</span></p>
            <p class='mini muted'>Proof of Payment: {pop_list}</p>
            {join}
        </div>
    </section>
    """

    return page("Status", body)


