# Tutor: manual attendance
@app.route('/tutor/session/<int:sid>/attendance', methods=['GET', 'POST'])
def tutor_session_attendance(sid: int):

    r = require_tutor()
    if r:
        return r

    tid = is_tutor()

    conn = get_db()
    cur = conn.cursor()

    # This is the EBTA academic month selected by the tutor.
    # Learners must be loaded from this month, even if the session date falls early in the next month.
    attendance_month = get_active_month('tutor')

    today_obj = datetime.datetime.now(ZoneInfo("Africa/Johannesburg")).date()
    today = today_obj.isoformat()

    # Build the allowed date window for the selected academic month.
    # Example:
    # May 2026 academic month allows attendance from 2026-05-01 to 2026-06-07.
    try:
        y, m = map(int, attendance_month.split("-")[:2])

        month_start = datetime.date(y, m, 1)
        month_end = datetime.date(y, m, calendar.monthrange(y, m)[1])

        # Grace period: allow sessions from the selected month to end in the first week of the next month.
        grace_end = month_end + datetime.timedelta(days=7)

    except Exception:
        conn.close()
        return page("Invalid Month", card_msg("Invalid selected attendance month."))

    # Default date:
    # If today falls within the academic month window, use today.
    # Otherwise, use the last day of the selected month.
    if month_start <= today_obj <= grace_end:
        default_date = today
    else:
        default_date = month_end.isoformat()

    date_str = (
        request.form.get("date", "").strip()
        if request.method == "POST"
        else request.args.get("date", default_date).strip()
    )

    if not date_str:
        date_str = default_date

    try:
        selected_date_obj = datetime.date.fromisoformat(date_str)
    except Exception:
        conn.close()
        return page("Invalid Date", card_msg("Please select a valid attendance date."))

    # Do not allow future attendance.
    if selected_date_obj > today_obj:
        conn.close()
        return page(
            "Invalid Date",
            card_msg("You cannot mark attendance for a future date.")
        )

    # Allow selected month + first 7 days of the next month.
    if selected_date_obj < month_start or selected_date_obj > grace_end:
        conn.close()
        return page(
            "Invalid Date",
            card_msg(
                f"Attendance for {pretty_month_label(attendance_month)} can be captured "
                f"from {month_start.strftime('%d %b %Y')} to {grace_end.strftime('%d %b %Y')}."
            )
        )

    cur.execute("""
        SELECT se.*, s.name AS subject_name, s.grade
        FROM sessions se
        JOIN subjects s ON s.id = se.subject_id
        WHERE se.id = ?
          AND se.tutor_id = ?
          AND se.active = 1
    """, (sid, tid))

    se = cur.fetchone()

    if not se:
        conn.close()
        return page("Not found", card_msg("Session not found."))

    # IMPORTANT:
    # Learners are loaded from the selected academic month, not the calendar month of the date.
    # Example: 1 June can still load May learners if the selected tutor month is May.
    cur.execute("""
        SELECT st.id, st.full_name, st.phone_whatsapp
        FROM enrollments e
        JOIN students st ON st.id = e.student_id
        WHERE e.subject_id = ?
          AND e.month = ?
          AND e.status = 'ACTIVE'
        ORDER BY st.full_name
    """, (se["subject_id"], attendance_month))

    studs = cur.fetchall()

    if request.method == "POST":

        if not studs:
            conn.close()
            return page(
                "No Learners Found",
                card_msg(
                    f"No active learners were found for {escape(se['subject_name'])} "
                    f"in {pretty_month_label(attendance_month)}. "
                    f"Please switch to the correct academic month first."
                )
            )

        present_ids = set()

        for value in request.form.getlist("present"):
            try:
                present_ids.add(int(value))
            except Exception:
                pass

        # Record that this class happened.
        # The actual date can be in the next month, but the academic month remains attendance_month.
        cur.execute("""
            INSERT INTO attendance_sessions(
                session_id,
                subject_id,
                tutor_id,
                date,
                month,
                created_at,
                updated_at
            )
            VALUES(?,?,?,?,?,?,?)
            ON CONFLICT(session_id, date)
            DO UPDATE SET
                updated_at = excluded.updated_at,
                month = excluded.month
        """, (
            sid,
            se["subject_id"],
            tid,
            date_str,
            attendance_month,
            now_utc_iso(),
            now_utc_iso()
        ))

        # Reset attendance for this class date before saving again.
        cur.execute("""
            DELETE FROM attendance
            WHERE session_id = ?
              AND date = ?
        """, (sid, date_str))

        now = now_utc_iso()

        for st in studs:
            if st["id"] in present_ids:
                cur.execute("""
                    INSERT INTO attendance(
                        session_id,
                        student_id,
                        date,
                        created_at
                    )
                    VALUES(?,?,?,?)
                """, (
                    sid,
                    st["id"],
                    date_str,
                    now
                ))

        conn.commit()
        conn.close()

        return redirect(url_for("tutor_home"))

    # GET: load existing present learners for this selected date
    cur.execute("""
        SELECT student_id
        FROM attendance
        WHERE session_id = ?
          AND date = ?
    """, (sid, date_str))

    already = {row["student_id"] for row in cur.fetchall()}

    # Load captured class dates for this session and selected academic month.
    cur.execute("""
        SELECT date
        FROM attendance_sessions
        WHERE session_id = ?
          AND month = ?
        ORDER BY date DESC
    """, (sid, attendance_month))

    captured_dates = cur.fetchall()

    conn.close()

    rows = []

    for st in studs:
        checked = "checked" if st["id"] in already else ""

        rows.append(f"""
        <tr>
            <td>
                {escape(st['full_name'])}
                <div class="mini muted">{escape(st['phone_whatsapp'] or '—')}</div>
            </td>

            <td style="text-align:center">
                <input type="checkbox"
                       name="present"
                       value="{st['id']}"
                       {checked}
                       style="width:20px;height:20px">
            </td>
        </tr>
        """)

    captured_html = ""

    if captured_dates:
        captured_html = """
        <div class="card soft" style="border-left:5px solid #2563eb;margin-bottom:12px">
            <h3>Captured Session Dates</h3>
            <div style="display:flex;gap:6px;flex-wrap:wrap">
        """

        for d in captured_dates:
            captured_html += f"""
                <a class="chip"
                   href="/tutor/session/{sid}/attendance?date={d['date']}">
                    {datetime.date.fromisoformat(d['date']).strftime('%d %b %Y')}
                </a>
            """

        captured_html += """
            </div>
        </div>
        """

    table = (
        f"""
        <div class='empty'>
            No active learners for {pretty_month_label(attendance_month)}.
            Please switch to the academic month where learners were enrolled.
        </div>
        """
        if not rows
        else f"""
        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Learner</th>
                        <th>Present</th>
                    </tr>
                </thead>
                <tbody>
                    {''.join(rows)}
                </tbody>
            </table>
        </div>
        """
    )

    body = f"""
    <a class="btn mini secondary" href="/tutor">
        ← Back to Tutor Dashboard
    </a>

    <section class="card" style="margin-top:12px">
        <h1>Capture Attendance</h1>

        <p class="muted">
            {grade_label(se['grade'])} — {escape(se['subject_name'])}
        </p>

        <div class="card soft" style="border-left:5px solid #1b5e20;margin-bottom:12px">
            <h3>Academic Month</h3>
            <p class="mini muted">
                You are capturing attendance for <strong>{pretty_month_label(attendance_month)}</strong>.
                The actual session date may fall within this month or within the first 7 days of the next month.
            </p>
            <p class="mini muted">
                Allowed date range:
                <strong>{month_start.strftime('%d %b %Y')}</strong>
                to
                <strong>{grace_end.strftime('%d %b %Y')}</strong>
            </p>
        </div>

        <div class="card soft" style="border-left:5px solid #f59e0b;margin-bottom:12px">
            <h3>Important</h3>
            <p class="mini muted">
                If this is a May session happening on 1 June, first switch your tutor dashboard month to May,
                then select 1 June as the session date here.
            </p>
        </div>

        {captured_html}

        <form method="get"
              action="{url_for('tutor_session_attendance', sid=sid)}"
              class="toolbar"
              style="margin-bottom:12px">
            <label class="mini muted">Session Date</label>

            <input type="date"
                   name="date"
                   value="{escape(date_str)}"
                   min="{month_start.isoformat()}"
                   max="{min(today_obj, grace_end).isoformat()}"
                   onchange="this.form.submit()">

            <noscript>
                <button class="btn mini">Load Date</button>
            </noscript>
        </form>

        <form method="post">
            <input type="hidden" name="date" value="{escape(date_str)}">

            {table}

            <button class="btn success"
                    style="margin-top:12px"
                    {'disabled' if not studs else ''}>
                Save Attendance
            </button>
        </form>
    </section>
    """

    return page("Capture Attendance", body)


@app.post('/tutor/activity/ping')
def tutor_activity_ping():

    r = require_tutor()
    if r:
        return ("", 204)

    tid = is_tutor()

    try:
        seconds = int(request.form.get("seconds", 0))
    except Exception:
        seconds = 0

    if seconds < 0:
        seconds = 0

    # Safety cap: one ping cannot add more than 5 minutes
    if seconds > 300:
        seconds = 300

    now = datetime.datetime.now(ZoneInfo("Africa/Johannesburg"))
    today = now.date().isoformat()
    month = now.strftime("%Y-%m")

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        INSERT INTO tutor_portal_activity(
            tutor_id,
            activity_date,
            month,
            total_seconds,
            last_seen_at,
            created_at,
            updated_at
        )
        VALUES(?,?,?,?,?,?,?)
        ON CONFLICT(tutor_id, activity_date)
        DO UPDATE SET
            total_seconds = total_seconds + excluded.total_seconds,
            last_seen_at = excluded.last_seen_at,
            updated_at = excluded.updated_at
    """, (
        tid,
        today,
        month,
        seconds,
        now_utc_iso(),
        now_utc_iso(),
        now_utc_iso()
    ))

    conn.commit()
    conn.close()

    return ("", 204)
    
    
def tutor_work_band(rate):
    rate = int(rate or 0)

    if rate >= 75:
        return "active", "On Track"

    if rate >= 50:
        return "pending", "Needs Attention"

    return "lapsed", "High Risk"


def tutor_work_progress_data(tutor_id, month):
    """
    Builds tutor work progress data for one month.
    Uses existing EBTA tables and does not modify tutor data.
    """

    conn = get_db()
    cur = conn.cursor()

    # Assigned subjects
    cur.execute("""
        SELECT
            s.id AS subject_id,
            s.name AS subject_name,
            s.grade
        FROM tutor_subjects ts
        JOIN subjects s ON s.id=ts.subject_id
        WHERE ts.tutor_id=?
        ORDER BY CAST(REPLACE(s.grade,'G','') AS INTEGER), s.name
    """, (tutor_id,))

    assigned_subjects = cur.fetchall()
    assigned_subject_ids = [r["subject_id"] for r in assigned_subjects]

    # Expected monthly attendance logs
    # EBTA rule:
    # Grade 8 to Grade 12 = 4 logs per month
    # Grade 13 = 6 logs per month
    assigned_sessions = ebta_expected_monthly_sessions_for_subjects(assigned_subjects)

    # Uploads
    cur.execute("""
        SELECT COUNT(*) AS c
        FROM materials
        WHERE tutor_id=?
          AND month LIKE ?
    """, (tutor_id, month + "%"))

    total_uploads = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM materials
        WHERE tutor_id=?
          AND month LIKE ?
          AND youtube_url IS NOT NULL
          AND TRIM(youtube_url) != ''
    """, (tutor_id, month + "%"))

    recordings_uploaded = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM materials
        WHERE tutor_id=?
          AND month LIKE ?
          AND (is_assignment=1 OR kind='assignment')
    """, (tutor_id, month + "%"))

    assignments_uploaded = cur.fetchone()["c"] or 0

    documents_uploaded = max(0, total_uploads - recordings_uploaded - assignments_uploaded)

    # Material views by students
    cur.execute("""
        SELECT COUNT(DISTINCT mv.id) AS c
        FROM material_views mv
        JOIN materials m ON m.id=mv.material_id
        WHERE m.tutor_id=?
          AND m.month LIKE ?
    """, (tutor_id, month + "%"))

    material_views = cur.fetchone()["c"] or 0

    # Submissions and marking
    cur.execute("""
        SELECT COUNT(sub.id) AS c
        FROM submissions sub
        JOIN materials m ON m.id=sub.material_id
        WHERE m.tutor_id=?
          AND m.month LIKE ?
          AND (m.is_assignment=1 OR m.kind='assignment')
    """, (tutor_id, month + "%"))

    submissions_received = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(sub.id) AS c
        FROM submissions sub
        JOIN materials m ON m.id=sub.material_id
        WHERE m.tutor_id=?
          AND m.month LIKE ?
          AND (m.is_assignment=1 OR m.kind='assignment')
          AND (
                sub.mark IS NOT NULL
                OR sub.feedback IS NOT NULL
                OR sub.evaluated_at IS NOT NULL
          )
    """, (tutor_id, month + "%"))

    marked_submissions = cur.fetchone()["c"] or 0
    unmarked_submissions = max(0, submissions_received - marked_submissions)
    marking_rate = percent_value(marked_submissions, submissions_received)

    # Attendance logging
    cur.execute("""
        SELECT COUNT(*) AS c
        FROM attendance_sessions
        WHERE tutor_id=?
          AND month=?
    """, (tutor_id, month))

    attendance_logs = cur.fetchone()["c"] or 0
    attendance_log_rate = percent_value(attendance_logs, assigned_sessions)

    cur.execute("""
        SELECT COALESCE(COUNT(a.id),0) AS c
        FROM attendance_sessions ats
        LEFT JOIN attendance a
          ON a.session_id=ats.session_id
         AND a.date=ats.date
        WHERE ats.tutor_id=?
          AND ats.month=?
    """, (tutor_id, month))

    total_attendance_marks = cur.fetchone()["c"] or 0

    avg_students_attended = 0

    if attendance_logs > 0:
        avg_students_attended = round(total_attendance_marks / attendance_logs, 1)

    # Tutor manager weekly tracker
    cur.execute("""
        SELECT COUNT(*) AS c
        FROM tutor_weekly_tracker
        WHERE tutor_id=?
          AND substr(session_date,1,7)=?
    """, (tutor_id, month))

    tracker_logs = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT
            COALESCE(SUM(CASE WHEN session_held=1 THEN 1 ELSE 0 END),0) AS held,
            COALESCE(SUM(CASE WHEN recording_posted=1 THEN 1 ELSE 0 END),0) AS recordings_posted,
            COALESCE(SUM(CASE WHEN posted_within_24h=1 THEN 1 ELSE 0 END),0) AS within_24h,
            COALESCE(SUM(CASE WHEN extra_resources=1 THEN 1 ELSE 0 END),0) AS extra_resources,
            ROUND(AVG(manager_rating),1) AS avg_rating
        FROM tutor_weekly_tracker
        WHERE tutor_id=?
          AND substr(session_date,1,7)=?
    """, (tutor_id, month))

    tracker = cur.fetchone()

    tracker_sessions_held = tracker["held"] or 0
    tracker_recordings_posted = tracker["recordings_posted"] or 0
    tracker_within_24h = tracker["within_24h"] or 0
    tracker_extra_resources = tracker["extra_resources"] or 0
    avg_manager_rating = tracker["avg_rating"] or None

    tracker_completion_rate = percent_value(tracker_logs, assigned_sessions)

    # Messages sent to students and admin
    cur.execute("""
        SELECT COUNT(*) AS c
        FROM direct_messages
        WHERE from_role='tutor'
          AND from_id=?
          AND substr(created_at,1,7)=?
    """, (tutor_id, month))

    messages_sent = cur.fetchone()["c"] or 0

    # Tutor portal time
    cur.execute("""
        SELECT COALESCE(SUM(total_seconds),0) AS total_seconds
        FROM tutor_portal_activity
        WHERE tutor_id=?
          AND month=?
    """, (tutor_id, month))

    portal_seconds = int(cur.fetchone()["total_seconds"] or 0)
    portal_minutes = portal_seconds // 60

    if portal_minutes >= 60:
        portal_hours_label = f"{portal_minutes // 60}h {portal_minutes % 60}min"
    else:
        portal_hours_label = f"{portal_minutes} min"

    # Per-subject breakdown
    subject_rows = []

    for subject in assigned_subjects:
        subject_id = subject["subject_id"]

        cur.execute("""
            SELECT COUNT(*) AS c
            FROM materials
            WHERE tutor_id=?
              AND subject_id=?
              AND month LIKE ?
        """, (tutor_id, subject_id, month + "%"))

        sub_uploads = cur.fetchone()["c"] or 0

        cur.execute("""
            SELECT COUNT(*) AS c
            FROM materials
            WHERE tutor_id=?
              AND subject_id=?
              AND month LIKE ?
              AND youtube_url IS NOT NULL
              AND TRIM(youtube_url) != ''
        """, (tutor_id, subject_id, month + "%"))

        sub_recordings = cur.fetchone()["c"] or 0

        cur.execute("""
            SELECT COUNT(*) AS c
            FROM materials
            WHERE tutor_id=?
              AND subject_id=?
              AND month LIKE ?
              AND (is_assignment=1 OR kind='assignment')
        """, (tutor_id, subject_id, month + "%"))

        sub_assignments = cur.fetchone()["c"] or 0

        cur.execute("""
            SELECT COUNT(sub.id) AS c
            FROM submissions sub
            JOIN materials m ON m.id=sub.material_id
            WHERE m.tutor_id=?
              AND m.subject_id=?
              AND m.month LIKE ?
              AND (m.is_assignment=1 OR m.kind='assignment')
        """, (tutor_id, subject_id, month + "%"))

        sub_submissions = cur.fetchone()["c"] or 0

        cur.execute("""
            SELECT COUNT(sub.id) AS c
            FROM submissions sub
            JOIN materials m ON m.id=sub.material_id
            WHERE m.tutor_id=?
              AND m.subject_id=?
              AND m.month LIKE ?
              AND (m.is_assignment=1 OR m.kind='assignment')
              AND (
                    sub.mark IS NOT NULL
                    OR sub.feedback IS NOT NULL
                    OR sub.evaluated_at IS NOT NULL
              )
        """, (tutor_id, subject_id, month + "%"))

        sub_marked = cur.fetchone()["c"] or 0
        sub_marking_rate = percent_value(sub_marked, sub_submissions)

        cur.execute("""
            SELECT COUNT(*) AS c
            FROM attendance_sessions
            WHERE tutor_id=?
              AND subject_id=?
              AND month=?
        """, (tutor_id, subject_id, month))

        sub_attendance_logs = cur.fetchone()["c"] or 0

        sub_assigned_sessions = ebta_expected_monthly_sessions_for_grade(subject["grade"])
        sub_attendance_rate = percent_value(sub_attendance_logs, sub_assigned_sessions)

        risk_points = 0
        focus = []

        if sub_uploads == 0:
            risk_points += 1
            focus.append("upload resources")

        if sub_recordings == 0:
            risk_points += 1
            focus.append("post recordings")

        if sub_assignments == 0:
            risk_points += 1
            focus.append("upload assignments")

        if sub_submissions > 0 and sub_marking_rate < 70:
            risk_points += 1
            focus.append("mark submissions")

        if sub_assigned_sessions > 0 and sub_attendance_rate < 60:
            risk_points += 1
            focus.append("log attendance")

        if risk_points >= 2:
            risk_level = "HIGH"
        elif risk_points == 1:
            risk_level = "MEDIUM"
        else:
            risk_level = "LOW"

        subject_rows.append({
            "subject_id": subject_id,
            "subject_name": subject["subject_name"],
            "grade": subject["grade"],
            "uploads": sub_uploads,
            "recordings": sub_recordings,
            "assignments": sub_assignments,
            "submissions": sub_submissions,
            "marked": sub_marked,
            "marking_rate": sub_marking_rate,
            "attendance_logs": sub_attendance_logs,
            "attendance_target": sub_assigned_sessions,
            "attendance_rate": sub_attendance_rate,
            "risk_level": risk_level,
            "focus": ", ".join(focus) if focus else "keep going"
        })

    # Recommendations
    recommendations = []

    if total_uploads == 0:
        recommendations.append("Upload academic resources for your assigned subjects.")

    if recordings_uploaded == 0:
        recommendations.append("Upload or share class recordings for learners to revise.")

    if assignments_uploaded == 0:
        recommendations.append("Upload at least one assignment or activity for learners.")

    if submissions_received > 0 and unmarked_submissions > 0:
        recommendations.append(f"Mark {unmarked_submissions} pending submission(s).")

    if assigned_sessions > 0 and attendance_log_rate < 75:
        recommendations.append("Improve attendance logging for your active sessions.")

    if tracker_logs == 0:
        recommendations.append("Ensure your tutor manager tracker logs are being completed.")

    high_risk_subjects = [x for x in subject_rows if x["risk_level"] == "HIGH"]

    if high_risk_subjects:
        names = ", ".join([x["subject_name"] for x in high_risk_subjects[:3]])
        recommendations.append(f"Prioritise these subjects: {names}.")

    if not recommendations:
        recommendations.append("Your work progress looks healthy. Keep uploading, tracking and supporting learners.")

    # Overall work progress
    components = []

    # Upload expectation: at least 4 uploads per month is treated as full progress
    components.append(min(100, percent_value(total_uploads, 4)))

    if assigned_sessions > 0:
        components.append(min(100, attendance_log_rate))

    if submissions_received > 0:
        components.append(marking_rate)

    if tracker_logs > 0 or assigned_sessions > 0:
        components.append(min(100, tracker_completion_rate))

    if recordings_uploaded > 0:
        components.append(100)
    else:
        components.append(0)

    overall_rate = round(sum(components) / len(components)) if components else 0
    overall_class, overall_status = tutor_work_band(overall_rate)

    conn.close()

    return {
        "month": month,
        "assigned_subjects": assigned_subjects,
        "assigned_sessions": assigned_sessions,
        "total_uploads": total_uploads,
        "recordings_uploaded": recordings_uploaded,
        "assignments_uploaded": assignments_uploaded,
        "documents_uploaded": documents_uploaded,
        "material_views": material_views,
        "submissions_received": submissions_received,
        "marked_submissions": marked_submissions,
        "unmarked_submissions": unmarked_submissions,
        "marking_rate": marking_rate,
        "attendance_logs": attendance_logs,
        "attendance_log_rate": attendance_log_rate,
        "avg_students_attended": avg_students_attended,
        "tracker_logs": tracker_logs,
        "tracker_sessions_held": tracker_sessions_held,
        "tracker_recordings_posted": tracker_recordings_posted,
        "tracker_within_24h": tracker_within_24h,
        "tracker_extra_resources": tracker_extra_resources,
        "tracker_completion_rate": tracker_completion_rate,
        "avg_manager_rating": avg_manager_rating,
        "messages_sent": messages_sent,
        "portal_seconds": portal_seconds,
        "portal_minutes": portal_minutes,
        "portal_hours_label": portal_hours_label,
        "subject_rows": subject_rows,
        "recommendations": recommendations,
        "overall_rate": overall_rate,
        "overall_status": overall_status,
        "overall_class": overall_class
    }


def tutor_manager_work_progress_data(manager_id, month):
    """
    Builds work progress data for one tutor manager based on:
    - tutors assigned to the manager
    - progress of those tutors
    - tracker logs captured by the manager
    - ratings/comments/follow-ups captured in tutor_weekly_tracker
    """

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            tm.id,
            tm.full_name,
            tm.phone,
            tm.created_at
        FROM tutor_managers tm
        WHERE tm.id=?
        LIMIT 1
    """, (manager_id,))

    manager = cur.fetchone()

    if not manager:
        conn.close()
        return None

    cur.execute("""
        SELECT
            t.id,
            t.full_name,
            t.phone
        FROM manager_tutors mt
        JOIN tutors t ON t.id = mt.tutor_id
        WHERE mt.manager_id=?
        ORDER BY t.full_name
    """, (manager_id,))

    assigned_tutors = cur.fetchall()

    cur.execute("""
        SELECT
            COUNT(*) AS tracker_logs,
            SUM(CASE WHEN session_held=1 THEN 1 ELSE 0 END) AS sessions_held,
            SUM(CASE WHEN session_held=0 THEN 1 ELSE 0 END) AS sessions_missed,
            SUM(CASE WHEN recording_posted=1 THEN 1 ELSE 0 END) AS recordings_posted,
            SUM(CASE WHEN posted_within_24h=1 THEN 1 ELSE 0 END) AS posted_within_24h,
            SUM(CASE WHEN TRIM(IFNULL(manager_comments,'')) != '' THEN 1 ELSE 0 END) AS comments_count,
            AVG(manager_rating) AS avg_manager_rating,
            COUNT(DISTINCT tutor_id) AS tutors_followed_up
        FROM tutor_weekly_tracker
        WHERE manager_id=?
          AND substr(IFNULL(session_date,''),1,7)=?
    """, (manager_id, month))

    tracker = cur.fetchone()

    conn.close()

    tutor_rows = []

    total_progress = 0
    total_uploads = 0
    total_recordings = 0
    total_assignments = 0
    total_views = 0
    total_submissions = 0
    total_marked = 0
    total_unmarked = 0
    total_attendance_logs = 0
    total_assigned_sessions = 0
    total_tracker_completion = 0

    on_track = 0
    needs_attention = 0
    high_risk = 0

    for tutor in assigned_tutors:
        progress = tutor_work_progress_data(tutor["id"], month)

        status = progress["overall_status"]

        if status == "On Track":
            on_track += 1
        elif status == "Needs Attention":
            needs_attention += 1
        elif status == "High Risk":
            high_risk += 1

        total_progress += progress["overall_rate"]
        total_uploads += progress["total_uploads"]
        total_recordings += progress["recordings_uploaded"]
        total_assignments += progress["assignments_uploaded"]
        total_views += progress["material_views"]
        total_submissions += progress["submissions_received"]
        total_marked += progress["marked_submissions"]
        total_unmarked += progress["unmarked_submissions"]
        total_attendance_logs += progress["attendance_logs"]
        total_assigned_sessions += progress["assigned_sessions"]
        total_tracker_completion += progress["tracker_completion_rate"]

        tutor_rows.append({
            "id": tutor["id"],
            "full_name": tutor["full_name"],
            "phone": tutor["phone"],
            "overall_rate": progress["overall_rate"],
            "overall_status": progress["overall_status"],
            "total_uploads": progress["total_uploads"],
            "recordings_uploaded": progress["recordings_uploaded"],
            "assignments_uploaded": progress["assignments_uploaded"],
            "material_views": progress["material_views"],
            "submissions_received": progress["submissions_received"],
            "marked_submissions": progress["marked_submissions"],
            "unmarked_submissions": progress["unmarked_submissions"],
            "attendance_logs": progress["attendance_logs"],
            "assigned_sessions": progress["assigned_sessions"],
            "tracker_logs": progress["tracker_logs"],
            "recommendations": progress["recommendations"]
        })

    assigned_count = len(assigned_tutors)

    avg_managed_progress = round(total_progress / assigned_count) if assigned_count else 0
    avg_tracker_completion = round(total_tracker_completion / assigned_count) if assigned_count else 0

    tracker_logs = int(tracker["tracker_logs"] or 0) if tracker else 0
    tutors_followed_up = int(tracker["tutors_followed_up"] or 0) if tracker else 0
    comments_count = int(tracker["comments_count"] or 0) if tracker else 0

    followup_coverage = round((tutors_followed_up / assigned_count) * 100) if assigned_count else 0

    avg_manager_rating = tracker["avg_manager_rating"] if tracker and tracker["avg_manager_rating"] is not None else None

    manager_score = round(
        (
            (avg_managed_progress * 0.45) +
            (followup_coverage * 0.30) +
            (min(100, avg_tracker_completion) * 0.15) +
            (min(100, tracker_logs * 10) * 0.10)
        )
    )

    if manager_score >= 75 and high_risk == 0:
        status = "On Track"
        status_class = "active"
    elif manager_score >= 50:
        status = "Needs Attention"
        status_class = "pending"
    else:
        status = "High Risk"
        status_class = "danger"

    recommendations = []

    if assigned_count == 0:
        recommendations.append("No tutors assigned to this manager yet.")

    if followup_coverage < 70 and assigned_count > 0:
        recommendations.append("Improve follow-up coverage with assigned tutors.")

    if tracker_logs == 0 and assigned_count > 0:
        recommendations.append("Manager must capture tutor tracker logs.")

    if high_risk > 0:
        recommendations.append("Follow up with high-risk tutors urgently.")

    if total_unmarked > 0:
        recommendations.append("Follow up on unmarked learner submissions.")

    if not recommendations:
        recommendations.append("Manager work progress is on track.")

    return {
        "manager_id": manager["id"],
        "full_name": manager["full_name"],
        "phone": manager["phone"],
        "created_at": manager["created_at"],

        "assigned_tutors": assigned_count,
        "tutors_followed_up": tutors_followed_up,
        "followup_coverage": followup_coverage,

        "manager_score": manager_score,
        "status": status,
        "status_class": status_class,

        "avg_managed_progress": avg_managed_progress,
        "avg_tracker_completion": avg_tracker_completion,

        "on_track": on_track,
        "needs_attention": needs_attention,
        "high_risk": high_risk,

        "tracker_logs": tracker_logs,
        "sessions_held": int(tracker["sessions_held"] or 0) if tracker else 0,
        "sessions_missed": int(tracker["sessions_missed"] or 0) if tracker else 0,
        "recordings_posted": int(tracker["recordings_posted"] or 0) if tracker else 0,
        "posted_within_24h": int(tracker["posted_within_24h"] or 0) if tracker else 0,
        "comments_count": comments_count,
        "avg_manager_rating": round(float(avg_manager_rating), 1) if avg_manager_rating is not None else None,

        "total_uploads": total_uploads,
        "total_recordings": total_recordings,
        "total_assignments": total_assignments,
        "total_views": total_views,
        "total_submissions": total_submissions,
        "total_marked": total_marked,
        "total_unmarked": total_unmarked,
        "total_attendance_logs": total_attendance_logs,
        "total_assigned_sessions": total_assigned_sessions,

        "tutor_rows": tutor_rows,
        "recommendations": recommendations
    }


