@app.get('/admin')
def admin_home():
    r=require_admin()
    if r: return r
    month=get_setting('current_month')
    conn=get_db(); cur=conn.cursor()
    cur.execute("SELECT COUNT(*) AS c FROM enrollments WHERE month=?", (month,))
    total = cur.fetchone()['c']

    cur.execute("""
        SELECT COUNT(DISTINCT student_id) AS c
        FROM enrollments
        WHERE month = ?
    """, (month,))
    total_students = cur.fetchone()['c']

    counts = {}
    for st in ["PENDING","ACTIVE","LAPSED"]:
        cur.execute("SELECT COUNT(*) AS c FROM enrollments WHERE month=? AND status=?", (month,st)); counts[st]=cur.fetchone()['c']
    cur.execute("SELECT COUNT(*) AS c FROM messages WHERE resolved=0"); msg_count=cur.fetchone()['c']
    # direct messages count to admin (unread)
    cur.execute("SELECT COUNT(*) AS c FROM direct_messages WHERE to_role='admin' AND is_read=0"); dm_unread = cur.fetchone()['c']
    conn.close()
    body=fr"""
    <section class='grid'><div class='stats'>
    {stat('Current month', month)}
    {stat('Total students', str(total_students))}
    {stat('Total enrollments', str(total))}
    {stat('Pending', str(counts.get('PENDING',0)))}
    {stat('Active', str(counts.get('ACTIVE',0)))}
    {stat('Admin inbox', str(msg_count))}{stat('Direct msgs (unread)', str(dm_unread))}
    </div>
    {admin_nav()}
    </section>"""
    return page("Admin", body)


# --- Admin: Enrollments (show all PoP files) ---

def format_datetime(dt_str):
    if not dt_str:
        return "—"
    try:
        dt = datetime.datetime.fromisoformat(dt_str)
        return dt.strftime("%d %b %Y, %H:%M")
    except Exception:
        return dt_str.replace("T", " ")[:16]


@app.get('/admin/enrollments')
def admin_enrollments():
    r = require_admin()
    if r:
        return r

    month = get_admin_active_month()
    year = month.split('-')[0]

    page_num = int(request.args.get("page", 1))
    q = request.args.get("q", "").strip()
    f_grade = request.args.get("grade", "")
    f_subject = request.args.get("subject", "")

    q_safe = escape(q)

    limit = 30
    offset = (page_num - 1) * limit

    conn = get_db()
    cur = conn.cursor()

    # Load subjects for dropdown
    cur.execute("SELECT DISTINCT name FROM subjects ORDER BY name")
    subjects = [r["name"] for r in cur.fetchall()]

    # -----------------------
    # Build filters
    # -----------------------
    params = [month]
    where_sql = "WHERE e.month = ?"

    if f_grade:
        where_sql += " AND st.grade = ?"
        params.append(f_grade)

    if f_subject:
        where_sql += " AND sub.name = ?"
        params.append(f_subject)

    if q:
        where_sql += """
        AND (
            st.full_name LIKE ?
            OR st.phone_whatsapp LIKE ?
            OR st.grade LIKE ?
            OR sub.name LIKE ?
            OR e.status LIKE ?
        )
        """
        search_term = f"%{q}%"
        params.extend([search_term] * 5)

    # -----------------------
    # COUNT query
    # -----------------------
    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM enrollments e
        JOIN students st ON st.id = e.student_id
        JOIN subjects sub ON sub.id = e.subject_id
        {where_sql}
    """, params)

    total = cur.fetchone()['c']
    total_pages = max(1, (total + limit - 1) // limit)

    # -----------------------
    # MAIN query
    # -----------------------
    data_params = list(params)
    data_params.extend([limit, offset])

    cur.execute(f"""
        SELECT 
            e.id,
            e.student_id,
            e.status,
            e.amount_paid,
            e.pop_url,
            e.status_token,

            e.coupon_code,
            e.coupon_discount_amount,
            e.coupon_type,
            e.referral_code_used,

            strftime('%Y-%m-%d %H:%M', datetime(e.created_at, '+2 hours')) AS created_at,

            st.full_name,
            st.phone_whatsapp,
            st.grade,

            sub.name AS subject_name
        FROM enrollments e
        JOIN students st ON st.id = e.student_id
        JOIN subjects sub ON sub.id = e.subject_id
        {where_sql}
        ORDER BY e.created_at DESC
        LIMIT ? OFFSET ?
    """, data_params)

    rows = cur.fetchall()

    # Returning students
    cur.execute("""
        SELECT DISTINCT student_id
        FROM enrollments
        WHERE status='ACTIVE'
        AND substr(month,1,4)=?
        AND month < ?
    """, (year, month))

    returning_ids = {r['student_id'] for r in cur.fetchall()}

    # PoP files
    cur.execute("SELECT enrollment_id, file_path FROM enrollment_files")

    pop_map = {}
    for r in cur.fetchall():
        pop_map.setdefault(r['enrollment_id'], []).append(r['file_path'])

    conn.close()

    trs = []

    for r in rows:

        history = "Returning student" if r['student_id'] in returning_ids else "First month"

        files = pop_map.get(r['id'], []) or ([r['pop_url']] if r['pop_url'] else [])

        pop_html = " ".join(
            f"<a class='links' target='_blank' href='{p}'>PoP</a>"
            for p in files
        ) or "—"
        
        coupon_html = "<span class='mini muted'>No code used</span>"

        if r["coupon_code"]:
            coupon_discount_amount = float(r["coupon_discount_amount"] or 0)

            coupon_type_label = r["coupon_type"] or "—"

            if coupon_type_label == "REFERRAL_ONLY":
                coupon_type_label = "Referral Code"
            elif coupon_type_label == "REFERRAL_REWARD":
                coupon_type_label = "Referral Reward"
            elif coupon_type_label == "MANUAL":
                coupon_type_label = "Manual Discount"

            coupon_html = f"""
            <div>
                <span class="chip" style="letter-spacing:1px">
                    {escape(r['coupon_code'])}
                </span>

                <div class="mini muted" style="margin-top:4px">
                    Type: {escape(coupon_type_label)}<br>
                    Discount: R{coupon_discount_amount:,.2f}
                </div>
            </div>
            """

        approval_locked = enrollment_status_actions_locked()

        if approval_locked and not is_high_admin():
            actions = f"""
            <div class="mini muted" style="max-width:220px">
                Approvals and rejections are locked by High Admin.
            </div>

            <form method='post'
                  action='{url_for('enrollment_action', id=r['id'], action='sms')}'
                  style='display:inline'
                  onsubmit="return confirm('Send approval/login SMS to this learner without changing status?');">
                <input type="hidden" name="page" value="{page_num}">
                <button class='btn secondary mini'>SMS Only</button>
            </form>
            """
        else:
            actions = f"""

            <form method='post'
                  action='{url_for('enrollment_action', id=r['id'], action='approve')}'
                  style='display:inline'>
                <input type="hidden" name="page" value="{page_num}">
                <button class='btn success mini'>Approve Only</button>
            </form>

            <form method='post'
                  action='{url_for('enrollment_action', id=r['id'], action='approve_sms')}'
                  style='display:inline'
                  onsubmit="return confirm('Approve this enrollment and send SMS to the learner?');">
                <input type="hidden" name="page" value="{page_num}">
                <button class='btn warn mini'>Approve + SMS</button>
            </form>

            <form method='post'
                  action='{url_for('enrollment_action', id=r['id'], action='sms')}'
                  style='display:inline'
                  onsubmit="return confirm('Send approval/login SMS to this learner without changing status?');">
                <input type="hidden" name="page" value="{page_num}">
                <button class='btn secondary mini'>SMS Only</button>
            </form>

            <form method='post'
                  action='{url_for('enrollment_action', id=r['id'], action='lapse')}'
                  style='display:inline'
                  onsubmit="return confirm('Mark this enrollment as lapsed?');">
                <input type="hidden" name="page" value="{page_num}">
                <button class='btn danger mini'>Lapse</button>
            </form>

            """
        
        
        if is_high_admin():
            actions += f"""
            <form method='post' action='{url_for('enrollment_action', id=r['id'], action='pending')}' style='display:inline'>
                <input type="hidden" name="page" value="{page_num}">
                <button class='btn warn'>Pending</button>
            </form>
            """
        
        trs.append(f"""
        <tr>
            <td>{r['full_name']}<div class='muted'>{r['phone_whatsapp']}</div></td>
            <td>{grade_label(r['grade'])}</td>
            <td>{r['subject_name']}</td>
            <td><span class='chip {r['status'].lower()}'>{r['status']}</span></td>
            <td><span class='mini muted'>{history}</span></td>
            <td><span class='mini'>{r['created_at']}</span></td>
            <td>{coupon_html}</td>
            <td>{pop_html}</td>
            <td><strong>R{r['amount_paid']}</strong></td>
            <td style="white-space:nowrap">
                {actions}
            </td>

            <td>
                <a class='links' target='_blank'
                href='{url_for('status', id=r['id'])}?{urlencode({'token': r['status_token']})}'>
                open
                </a>
            </td>
        </tr>
        """)

    # -----------------------
    # Pagination query string
    # -----------------------

    query_string = ""

    if q:
        query_string += f"&q={q_safe}"

    if f_grade:
        query_string += f"&grade={f_grade}"

    if f_subject:
        query_string += f"&subject={f_subject}"

    start = max(1, page_num - 3)
    end = min(total_pages, page_num + 3)

    page_links = []

    if page_num > 1:
        page_links.append(f"<a class='links' href='?page=1{query_string}'>« First</a>")
        page_links.append(f"<a class='links' href='?page={page_num-1}{query_string}'>‹ Prev</a>")

    for p in range(start, end + 1):

        if p == page_num:
            page_links.append(
                f"<span class='current' style='padding:4px 8px;background:#0f172a;color:white;border-radius:6px'>{p}</span>"
            )
        else:
            page_links.append(
                f"<a class='links' href='?page={p}{query_string}'>{p}</a>"
            )

    if page_num < total_pages:
        page_links.append(f"<a class='links' href='?page={page_num+1}{query_string}'>Next ›</a>")
        page_links.append(f"<a class='links' href='?page={total_pages}{query_string}'>Last »</a>")

    nav = f"""
    <div class='pager' style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:10px 0">

        <span class="mini muted">
            Page {page_num} of {total_pages}
        </span>

        {"".join(page_links)}

        <form method="get"
              style="display:inline-flex;align-items:center;gap:6px;margin-left:10px">

            <span class="mini muted">Go to page</span>

            <input type="number"
                   name="page"
                   min="1"
                   max="{total_pages}"
                   value="{page_num}"
                   style="width:70px;padding:4px;border-radius:6px;border:1px solid #ccc">

            <button class="btn mini">Go</button>

        </form>

    </div>
    """

    body = f"""
    {admin_nav()}

    <section class='card'>

        <h1>Enrollments — {pretty_month_label(month)}</h1>
        
        <form method="post" action="/admin/set-month" 
              style="margin-bottom:10px;display:flex;gap:10px;align-items:center;flex-wrap:wrap">

            <label class="mini muted">View month:</label>

            <input type="month" 
                   name="month" 
                   value="{month}" 
                   style="padding:6px;border-radius:8px;border:1px solid #ccc">

            <button class="btn mini">Switch</button>

        </form>

        <div class='toolbar'>

            <form method="get" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">

                <input type="text"
                       name="q"
                       value="{q_safe}"
                       placeholder="Search name, phone, grade, subject, status"
                       class="pill">

                <select name="grade">
                    <option value="">All Grades</option>
                    <option value="G8" {"selected" if f_grade=="G8" else ""}>Grade 8</option>
                    <option value="G9" {"selected" if f_grade=="G9" else ""}>Grade 9</option>
                    <option value="G10" {"selected" if f_grade=="G10" else ""}>Grade 10</option>
                    <option value="G11" {"selected" if f_grade=="G11" else ""}>Grade 11</option>
                    <option value="G12" {"selected" if f_grade=="G12" else ""}>Grade 12</option>
                    <option value="G13" {"selected" if f_grade=="G13" else ""}>Grade 13</option>
                </select>

                <select name="subject">
                    <option value="">All Subjects</option>
                    {''.join(
                        f"<option value='{escape(s)}' {'selected' if f_subject==s else ''}>{escape(s)}</option>"
                        for s in subjects
                    )}
                </select>

                <input type="hidden" name="page" value="1">

                <button class="btn mini">Filter</button>

            </form>

        </div>

        {nav}

        <div class="scroll-x">

            <table id='enr_tbl'>

                <thead>

                    <tr>
                        <th>Student</th>
                        <th>Grade</th>
                        <th>Subject</th>
                        <th>Status</th>
                        <th>History</th>
                        <th>Timestamp</th>
                        <th>Coupon / Referral</th>
                        <th>PoP</th>
                        <th>Amount paid</th>
                        <th>Actions</th>
                        <th>Status link</th>
                    </tr>

                </thead>

                <tbody>

                    {''.join(trs) or "<tr><td colspan='11'>No enrollments.</td></tr>"}

                </tbody>

            </table>

        </div>

        {nav}

    </section>
    """

    return page("Enrollments", body)
    

@app.post('/admin/enrollments/<int:id>/<action>')
def enrollment_action(id: int, action: str):
    r = require_admin()
    if r:
        return r

    page_num = int(request.form.get("page", 1))

    allowed_actions = ["approve", "approve_sms", "sms", "lapse", "pending"]

    if action not in allowed_actions:
        return page("Invalid Action", card_msg("Invalid enrollment action."))
        
    status_changing_actions = ["approve", "approve_sms", "lapse"]

    if action in status_changing_actions and enrollment_status_actions_locked() and not is_high_admin():
        return page(
            "Approvals Locked",
            card_msg(
                "Enrollment approvals and rejections are currently locked by High Admin. "
                "Only High Admin can approve or lapse enrollments at the moment."
            )
        )

    conn = get_db()
    cur = conn.cursor()

    notify_phone = None
    notify_name = None
    notify_pin = None
    notify_subject = None
    notify_grade = None
    notify_month = None

    # Actions that need student details for SMS
    needs_sms_details = action in ["approve_sms", "sms"]

    # Actions that should activate the enrollment
    should_approve = action in ["approve", "approve_sms"]

    if should_approve:
        cur.execute("""
            UPDATE enrollments
            SET status = 'ACTIVE'
            WHERE id = ?
        """, (id,))

    elif action == "lapse":
        cur.execute("""
            UPDATE enrollments
            SET status = 'LAPSED'
            WHERE id = ?
        """, (id,))

    elif action == "pending":

        if not is_high_admin():
            conn.close()
            return page("Access Denied", card_msg("Only super admin can set status to Pending."))

        cur.execute("""
            UPDATE enrollments
            SET status = 'PENDING'
            WHERE id = ?
        """, (id,))

    # Load student details if SMS is requested
    if needs_sms_details:

        cur.execute("""
            SELECT 
                st.id,
                st.full_name,
                st.phone_whatsapp,
                st.pin,
                e.month,
                sub.name AS subject_name,
                sub.grade
            FROM enrollments e
            JOIN students st ON st.id = e.student_id
            JOIN subjects sub ON sub.id = e.subject_id
            WHERE e.id = ?
        """, (id,))

        row = cur.fetchone()

        if row:
            notify_name = row["full_name"]
            notify_phone = row["phone_whatsapp"]
            notify_pin = row["pin"]
            notify_month = row["month"]
            notify_subject = row["subject_name"]
            notify_grade = row["grade"]

            # Generate PIN only when SMS is actually requested
            if not notify_pin:
                pins = set()

                cur.execute("SELECT pin FROM students WHERE pin IS NOT NULL")
                pins |= {x["pin"] for x in cur.fetchall()}

                cur.execute("SELECT pin FROM tutors WHERE pin IS NOT NULL")
                pins |= {x["pin"] for x in cur.fetchall()}

                new_pin = gen_pin(pins)

                cur.execute("""
                    UPDATE students
                    SET pin = ?
                    WHERE id = ?
                """, (new_pin, row["id"]))

                notify_pin = new_pin

    conn.commit()
    conn.close()

    # Send SMS only when admin selected Approve + SMS or SMS Only
    try:
        if needs_sms_details and notify_phone and notify_pin:

            base_url = (request.url_root or "").rstrip("/")
            login_link = base_url + url_for("student_login")

            month_label = pretty_month_label(notify_month) if notify_month else ""
            grade_label_txt = grade_label(notify_grade) if notify_grade else ""
            first_name = notify_name.split()[0] if notify_name else ""

            if action == "approve_sms":
                sms_intro = f"EBTA: Hi {first_name}, your enrollment is APPROVED."
            else:
                sms_intro = f"EBTA: Hi {first_name}, your portal login details are below."

            sms_body_parts = [sms_intro]

            if month_label or grade_label_txt or notify_subject:
                detail = " ".join(
                    x for x in [grade_label_txt, notify_subject, month_label]
                    if x
                )
                sms_body_parts.append(detail + ".")

            sms_body_parts.append(
                f"Login with WhatsApp number {notify_phone} + PIN {notify_pin} at {login_link}."
            )

            sms_body_parts.append(
                "Join ALL subject WhatsApp groups inside your portal."
            )

            sms_body = " ".join(sms_body_parts)

            send_sms_notification(notify_phone, sms_body)

    except Exception:
        # Never break approval flow because of SMS issue
        pass

    return redirect(url_for("admin_enrollments", page=page_num))


@app.post('/admin/set-month')
def set_admin_month():
    r = require_admin()
    if r:
        return r

    month = request.form.get("month")

    if month:
        session['admin_month'] = month

    return redirect(url_for('admin_enrollments'))

# --- Admin: Students (show Guardian & Email + duplicate filter) ---

@app.get('/admin/students')
def admin_students():

    q = request.args.get("q", "").strip()
    selected_month = request.args.get("month", "").strip()
    grade_filter = request.args.get("grade", "").strip()
    duplicates = request.args.get("duplicates", "").strip()
    q_safe = escape(q)

    r = require_admin()
    if r:
        return r

    try:
        page_num = max(1, int(request.args.get("page", 1)))
    except Exception:
        page_num = 1

    limit = 12
    offset = (page_num - 1) * limit

    # Clean phone expression for SQLite:
    # Removes spaces, +, -, brackets, then compares last 9 digits.
    phone_clean_expr = """
        REPLACE(
            REPLACE(
                REPLACE(
                    REPLACE(
                        REPLACE(COALESCE(s.phone_whatsapp,''), ' ', ''),
                    '+', ''),
                '-', ''),
            '(', ''),
        ')', '')
    """

    phone_clean_expr_s2 = """
        REPLACE(
            REPLACE(
                REPLACE(
                    REPLACE(
                        REPLACE(COALESCE(s2.phone_whatsapp,''), ' ', ''),
                    '+', ''),
                '-', ''),
            '(', ''),
        ')', '')
    """

    def build_where():
        params = []
        where_clauses = []

        if selected_month:
            where_clauses.append("e.month = ?")
            params.append(selected_month)

        if grade_filter:
            where_clauses.append("s.grade = ?")
            params.append(grade_filter)

        if q:
            where_clauses.append("""
                (
                    s.full_name LIKE ?
                    OR s.phone_whatsapp LIKE ?
                    OR s.guardian_phone LIKE ?
                    OR s.email LIKE ?
                    OR s.school LIKE ?
                )
            """)
            search_term = f"%{q}%"
            params.extend([search_term] * 5)

        # Duplicate filters
        if duplicates == "name":
            where_clauses.append("""
                LOWER(TRIM(s.full_name)) IN (
                    SELECT LOWER(TRIM(full_name))
                    FROM students
                    WHERE full_name IS NOT NULL
                      AND TRIM(full_name) != ''
                    GROUP BY LOWER(TRIM(full_name))
                    HAVING COUNT(*) >= 2
                )
            """)

        elif duplicates == "phone9":
            where_clauses.append(f"""
                SUBSTR({phone_clean_expr}, -9) IN (
                    SELECT SUBSTR(
                        REPLACE(
                            REPLACE(
                                REPLACE(
                                    REPLACE(
                                        REPLACE(COALESCE(phone_whatsapp,''), ' ', ''),
                                    '+', ''),
                                '-', ''),
                            '(', ''),
                        ')', ''),
                    -9)
                    FROM students
                    WHERE phone_whatsapp IS NOT NULL
                      AND TRIM(phone_whatsapp) != ''
                      AND LENGTH(
                        REPLACE(
                            REPLACE(
                                REPLACE(
                                    REPLACE(
                                        REPLACE(COALESCE(phone_whatsapp,''), ' ', ''),
                                    '+', ''),
                                '-', ''),
                            '(', ''),
                        ')', '')
                      ) >= 9
                    GROUP BY SUBSTR(
                        REPLACE(
                            REPLACE(
                                REPLACE(
                                    REPLACE(
                                        REPLACE(COALESCE(phone_whatsapp,''), ' ', ''),
                                    '+', ''),
                                '-', ''),
                            '(', ''),
                        ')', ''),
                    -9)
                    HAVING COUNT(*) >= 2
                )
                AND LENGTH({phone_clean_expr}) >= 9
            """)

        elif duplicates == "either":
            where_clauses.append(f"""
                (
                    LOWER(TRIM(s.full_name)) IN (
                        SELECT LOWER(TRIM(full_name))
                        FROM students
                        WHERE full_name IS NOT NULL
                          AND TRIM(full_name) != ''
                        GROUP BY LOWER(TRIM(full_name))
                        HAVING COUNT(*) >= 2
                    )
                    OR
                    (
                        SUBSTR({phone_clean_expr}, -9) IN (
                            SELECT SUBSTR(
                                REPLACE(
                                    REPLACE(
                                        REPLACE(
                                            REPLACE(
                                                REPLACE(COALESCE(phone_whatsapp,''), ' ', ''),
                                            '+', ''),
                                        '-', ''),
                                    '(', ''),
                                ')', ''),
                            -9)
                            FROM students
                            WHERE phone_whatsapp IS NOT NULL
                              AND TRIM(phone_whatsapp) != ''
                              AND LENGTH(
                                REPLACE(
                                    REPLACE(
                                        REPLACE(
                                            REPLACE(
                                                REPLACE(COALESCE(phone_whatsapp,''), ' ', ''),
                                            '+', ''),
                                        '-', ''),
                                    '(', ''),
                                ')', '')
                              ) >= 9
                            GROUP BY SUBSTR(
                                REPLACE(
                                    REPLACE(
                                        REPLACE(
                                            REPLACE(
                                                REPLACE(COALESCE(phone_whatsapp,''), ' ', ''),
                                            '+', ''),
                                        '-', ''),
                                    '(', ''),
                                ')', ''),
                            -9)
                            HAVING COUNT(*) >= 2
                        )
                        AND LENGTH({phone_clean_expr}) >= 9
                    )
                )
            """)

        where_sql = "WHERE " + " AND ".join(where_clauses) if where_clauses else ""

        return where_sql, params

    conn = get_db()
    cur = conn.cursor()

    where_sql, params = build_where()

    cur.execute(f"""
        SELECT COUNT(DISTINCT s.id) AS c
        FROM students s
        LEFT JOIN enrollments e ON e.student_id = s.id
        {where_sql}
    """, params)

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + limit - 1) // limit)

    data_params = list(params)
    data_params.extend([limit, offset])

    cur.execute(f"""
        SELECT
            s.id,
            s.full_name,
            s.phone_whatsapp,
            s.guardian_name,
            s.guardian_phone,
            s.email,
            s.grade,
            s.province,
            s.school,
            s.pin,

            strftime('%Y-%m-%d', datetime(MIN(e.created_at), '+2 hours')) AS first_enrolled,

            (
                SELECT COUNT(*)
                FROM enrollments e2
                WHERE e2.student_id = s.id
            ) AS enrollment_count,

            (
                SELECT MAX(month)
                FROM enrollments e3
                WHERE e3.student_id = s.id
            ) AS last_enrollment_month,

            (
                SELECT COUNT(*)
                FROM students s2
                WHERE LOWER(TRIM(s2.full_name)) = LOWER(TRIM(s.full_name))
                  AND TRIM(COALESCE(s2.full_name,'')) != ''
            ) AS duplicate_name_count,

            (
                SELECT COUNT(*)
                FROM students s2
                WHERE SUBSTR({phone_clean_expr_s2}, -9) = SUBSTR({phone_clean_expr}, -9)
                  AND LENGTH({phone_clean_expr_s2}) >= 9
                  AND LENGTH({phone_clean_expr}) >= 9
            ) AS duplicate_phone9_count,

            SUBSTR({phone_clean_expr}, -9) AS phone_last9

        FROM students s
        LEFT JOIN enrollments e ON e.student_id = s.id
        {where_sql}
        GROUP BY s.id
        ORDER BY
            CASE
                WHEN (
                    (
                        SELECT COUNT(*)
                        FROM students s2
                        WHERE LOWER(TRIM(s2.full_name)) = LOWER(TRIM(s.full_name))
                          AND TRIM(COALESCE(s2.full_name,'')) != ''
                    ) >= 2
                    OR
                    (
                        SELECT COUNT(*)
                        FROM students s2
                        WHERE SUBSTR({phone_clean_expr_s2}, -9) = SUBSTR({phone_clean_expr}, -9)
                          AND LENGTH({phone_clean_expr_s2}) >= 9
                          AND LENGTH({phone_clean_expr}) >= 9
                    ) >= 2
                )
                THEN 0 ELSE 1
            END,
            LOWER(TRIM(s.full_name)),
            s.created_at DESC
        LIMIT ? OFFSET ?
    """, data_params)

    students = cur.fetchall()

    ids = [s["id"] for s in students]
    subject_map = {}

    if ids:
        qmarks = ",".join("?" * len(ids))

        if selected_month:
            cur.execute(f"""
                SELECT DISTINCT e.student_id, sub.name
                FROM enrollments e
                JOIN subjects sub ON sub.id = e.subject_id
                WHERE e.student_id IN ({qmarks})
                  AND e.month = ?
            """, ids + [selected_month])
        else:
            cur.execute(f"""
                SELECT DISTINCT e.student_id, sub.name
                FROM enrollments e
                JOIN subjects sub ON sub.id = e.subject_id
                WHERE e.student_id IN ({qmarks})
            """, ids)

        for row in cur.fetchall():
            subject_map.setdefault(row["student_id"], []).append(row["name"])

    conn.close()

    def nz(v):
        return escape(str(v)) if (v and str(v).strip()) else "N/A"

    def build_query(page):
        return urlencode({
            "page": page,
            "q": q,
            "month": selected_month,
            "grade": grade_filter,
            "duplicates": duplicates
        })

    trs = []

    for s in students:
        subjects = ", ".join(subject_map.get(s["id"], [])) or "N/A"

        pin = escape(s["pin"]) if s["pin"] else "<span class='muted'>not set</span>"

        duplicate_name_count = int(s["duplicate_name_count"] or 0)
        duplicate_phone9_count = int(s["duplicate_phone9_count"] or 0)

        duplicate_badges = []

        if duplicate_name_count >= 2:
            duplicate_badges.append(f"<span class='chip pending'>Name matches: {duplicate_name_count}</span>")

        if duplicate_phone9_count >= 2:
            duplicate_badges.append(f"<span class='chip pending'>Phone9 matches: {duplicate_phone9_count}</span>")

        if not duplicate_badges:
            duplicate_badges.append("<span class='chip active'>Unique</span>")

        duplicate_info = f"""
            {' '.join(duplicate_badges)}
            <div class="mini muted">Last 9 digits: {escape(s['phone_last9'] or '—')}</div>
            <div class="mini muted">Enrollments: {s['enrollment_count'] or 0}</div>
            <div class="mini muted">Last enrollment: {escape(s['last_enrollment_month'] or 'N/A')}</div>
        """

        delete_warning = (
            "Delete this student record? Please make sure you are deleting the unused duplicate record, not the active learner profile."
        )

        trs.append(f"""
        <tr>
            <td style="text-align:center">
                {f'<input form="bulkDeleteStudentsForm" type="checkbox" name="student_ids" value="{s["id"]}">' if is_high_admin() else ''}
            </td>

            <td>
                <strong>{escape(s['full_name'] or '')}</strong>
                <div class='muted'>{escape(s['phone_whatsapp'] or '')}</div>
                <div class='mini muted'>ID: {s['id']}</div>
            </td>

            <td>{grade_label(s['grade'])}</td>
            <td>{escape(subjects)}</td>

            <td>
                {nz(s['guardian_name'])}
                <div class='muted'>{nz(s['guardian_phone'])}</div>
            </td>

            <td>{nz(s['province'])}</td>
            <td>{nz(s['school'])}</td>
            <td>{nz(s['email'])}</td>
            <td>{escape(s['first_enrolled'] or 'N/A')}</td>
            <td>{pin}</td>

            <td>
                {duplicate_info}
            </td>

            <td style="white-space:nowrap">

                {f'''
                <a class="btn mini"
                   href="{url_for("admin_student_edit", sid=s["id"])}">
                   Edit
                </a>

                <form method="post"
                      action="{url_for("admin_student_reset_pin", sid=s["id"])}"
                      style="display:inline">
                    <button class="btn success mini">
                        Reset
                    </button>
                </form>

                <form method="post"
                      action="{url_for("admin_student_delete", sid=s["id"])}"
                      style="display:inline"
                      onsubmit="return confirm('{delete_warning}')">
                    <button class="btn danger mini">
                        Delete
                    </button>
                </form>
                ''' if is_high_admin() else ""}

            </td>
        </tr>
        """)

    start = max(1, page_num - 3)
    end = min(total_pages, page_num + 3)

    page_links = []

    if page_num > 1:
        page_links.append(f"<a class='links' href='?{build_query(1)}'>« First</a>")
        page_links.append(f"<a class='links' href='?{build_query(page_num - 1)}'>‹ Prev</a>")

    for p in range(start, end + 1):
        if p == page_num:
            page_links.append(f"<span class='current'>{p}</span>")
        else:
            page_links.append(f"<a class='links' href='?{build_query(p)}'>{p}</a>")

    if page_num < total_pages:
        page_links.append(f"<a class='links' href='?{build_query(page_num + 1)}'>Next ›</a>")
        page_links.append(f"<a class='links' href='?{build_query(total_pages)}'>Last »</a>")

    nav = f"""
    <div class='pager' style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:10px 0">

        <span class="mini muted">
            Page {page_num} of {total_pages} | Showing {total} student record(s)
        </span>

        {"".join(page_links)}

        <form method="get" style="display:inline-flex;align-items:center;gap:6px;margin-left:10px">
            <span class="mini muted">Go to page</span>
            <input type="number"
                   name="page"
                   min="1"
                   max="{total_pages}"
                   value="{page_num}"
                   style="width:70px;padding:4px;border-radius:6px;border:1px solid #ccc">

            <input type="hidden" name="q" value="{q_safe}">
            <input type="hidden" name="month" value="{escape(selected_month)}">
            <input type="hidden" name="grade" value="{escape(grade_filter)}">
            <input type="hidden" name="duplicates" value="{escape(duplicates)}">

            <button class="btn mini">Go</button>
        </form>

    </div>
    """

    grade_options = '<option value="">All Grades</option>'

    for g in ["G8", "G9", "G10", "G11", "G12", "G13"]:
        selected = "selected" if grade_filter == g else ""
        grade_options += f"<option value='{g}' {selected}>{grade_label(g)}</option>"

    duplicate_options = f"""
        <option value="" {'selected' if duplicates == '' else ''}>All Students</option>
        <option value="name" {'selected' if duplicates == 'name' else ''}>Possible duplicates by full name</option>
        <option value="phone9" {'selected' if duplicates == 'phone9' else ''}>Possible duplicates by last 9 phone digits</option>
        <option value="either" {'selected' if duplicates == 'either' else ''}>Possible duplicates by name OR phone</option>
    """

    quick_duplicate_url = url_for("admin_students") + "?" + urlencode({"duplicates": "either"})
    clear_url = url_for("admin_students")

    export_link = ""

    if selected_month:
        export_link = (
            "<a class='btn success mini' href='"
            + url_for("admin_students_export")
            + "?"
            + urlencode({"month": selected_month})
            + "'>Export Excel</a>"
        )

    duplicate_note = ""

    if duplicates:
        duplicate_note = f"""
        <div class="card soft" style="border-left:5px solid #f59e0b;margin:12px 0">
            <h3>Duplicate Review Mode</h3>
            <p class="muted">
                You are currently viewing possible duplicate student records. Check the enrollment count,
                last enrollment month, phone number, and subjects before deleting any record.
            </p>
        </div>
        """

    body = f"""
    {admin_nav()}

    <section class='card'>
        <h1>Students</h1>

        <p class="muted">
            Manage student records. Use the duplicate filter to find learners who may have been captured more than once.
        </p>

        <div class='toolbar'>
            <form method="get" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
                <input type="text"
                       name="q"
                       placeholder="Search name, phone, email, school"
                       value="{q_safe}"
                       style="min-width:220px">

                <input type="month" name="month" value="{escape(selected_month)}">

                <select name="grade" style="min-width:150px">
                    {grade_options}
                </select>

                <select name="duplicates" style="min-width:260px">
                    {duplicate_options}
                </select>

                <button class="btn mini">Search</button>

                <a class="btn mini secondary" href="{clear_url}">
                    Clear
                </a>

                <a class="btn mini warn" href="{quick_duplicate_url}">
                    Show Possible Duplicates
                </a>
            </form>

            {export_link}

            <div style="margin-top:10px">
                <form method="get" action="{url_for('admin_students_compare_export')}"
                      style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">

                    <label>Previous:</label>
                    <input type="month" name="prev" required>

                    <label>Current:</label>
                    <input type="month" name="curr" required>

                    <button class="btn success mini">
                        Compare & Export
                    </button>

                </form>
            </div>
        </div>

        {duplicate_note}

        {nav}

        {f'''
        <div class="card soft" style="border-left:5px solid #dc2626;margin:12px 0">
            <h3>High Admin Duplicate Cleanup</h3>

            <p class="muted">
                Use this carefully. Selected bulk delete will delete every selected student record.
                Auto-delete will delete 0-number duplicate records when a matching +27 record exists using the same last 9 digits.
            </p>

            <form id="bulkDeleteStudentsForm"
                  method="post"
                  action="{url_for('admin_students_bulk_delete_selected')}"
                  style="display:inline"
                  onsubmit="return confirm('Delete all selected student records? This will also remove linked portal data for those students.')">

                <button class="btn danger mini">
                    Delete Selected Records
                </button>
            </form>

            <form method="post"
                  action="{url_for('admin_students_auto_delete_zero_phone_duplicates')}"
                  style="display:inline"
                  onsubmit="return confirm('Auto-delete all 0-number duplicates where a matching +27 record exists?')">

                <button class="btn warn mini">
                    Auto-delete 0-number duplicates
                </button>
            </form>
        </div>
        ''' if is_high_admin() and duplicates else ''}

        <div class="scroll-x">
            <table id='stu_tbl'>
                <thead>
                    <tr>
                        <th>Select</th>
                        <th>Student</th>
                        <th>Grade</th>
                        <th>Subject</th>
                        <th>Guardian</th>
                        <th>Province</th>
                        <th>School</th>
                        <th>Email</th>
                        <th>First Enrolled</th>
                        <th>PIN</th>
                        <th>Duplicate Check</th>
                        <th>Actions</th>
                    </tr>
                </thead>

                <tbody>
                    {''.join(trs) or "<tr><td colspan='12'>No students found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {nav}
    </section>
    """

    return page("Students", body)
    
    
