@app.post('/admin/awards-student-export')
@require_high_admin
def admin_awards_student_export_post():

    r = require_admin()
    if r: return r

    if not is_high_admin():
        return page("Access Denied", card_msg("Only high admin can use the awards export tool."))

    pasted_students = request.form.get("pasted_students", "").strip()

    uploaded = request.files.get("student_file")
    uploaded_text = ""

    if uploaded and uploaded.filename:
        ext = os.path.splitext(uploaded.filename.lower())[1]

        if ext not in [".txt", ".csv"]:
            return page("Invalid File", card_msg("Please upload a TXT or CSV file only."))

        try:
            uploaded_text = uploaded.read().decode("utf-8", errors="ignore")
        except Exception:
            return page("File Error", card_msg("The uploaded file could not be read."))

    raw_text = pasted_students

    if uploaded_text:
        raw_text = raw_text + "\n" + uploaded_text

    award_rows = parse_awards_student_list(raw_text)

    if not award_rows:
        return page(
            "No Students Found",
            card_msg("No valid student rows were detected. Please check that the list includes number, learner name, grade, and award category.")
        )

    conn = get_db()
    cur = conn.cursor()

    matched_rows = []
    not_found_rows = []

    for item in award_rows:
        award_name = item["learner_name"]
        award_grade_raw = item["grade"]
        award_grade = f"G{award_grade_raw}" if not str(award_grade_raw).upper().startswith("G") else str(award_grade_raw).upper()

        # =========================
        # Improved student matching
        # Handles:
        # - extra spaces
        # - surname first
        # - name first
        # - middle names
        # - partial two-word matches
        # =========================

        award_tokens = name_tokens_for_match(award_name)

        student = None
        match_score = 0
        match_note = ""

        # 1. First search students in the same grade.
        # This is safer because two learners can have similar names.
        cur.execute("""
            SELECT *
            FROM students
            WHERE grade = ?
        """, (award_grade,))

        grade_candidates = cur.fetchall()

        best_student = None
        best_score = 0

        for candidate in grade_candidates:
            score = name_match_score(award_name, candidate["full_name"])

            if score > best_score:
                best_score = score
                best_student = candidate

        # Accept same-grade matches from 55 upward.
        # 55 is allowed because sometimes the award list has only one name.
        if best_student and best_score >= 55:
            student = best_student
            match_score = best_score
            match_note = "Matched by name words and grade"

        # 2. If not found in the same grade, search all portal students.
        # This is stricter to avoid wrong matches.
        if not student:
            cur.execute("""
                SELECT *
                FROM students
            """)

            all_candidates = cur.fetchall()

            best_student = None
            best_score = 0

            for candidate in all_candidates:
                score = name_match_score(award_name, candidate["full_name"])

                if score > best_score:
                    best_score = score
                    best_student = candidate

            if best_student and best_score >= 75:
                student = best_student
                match_score = best_score
                match_note = "Matched by name words, grade different or not used"

        # 3. Final fallback for single-name cases.
        # Example: "Luyanda"
        # This only accepts the match if there is exactly one possible learner in that grade.
        if not student and len(award_tokens) == 1:
            one_name = award_tokens[0]

            cur.execute("""
                SELECT *
                FROM students
                WHERE lower(full_name) LIKE ?
                  AND grade = ?
                LIMIT 2
            """, (f"%{one_name}%", award_grade))

            possible = cur.fetchall()

            if len(possible) == 1:
                student = possible[0]
                match_score = 50
                match_note = "Matched by single name and grade"

        

        if not student:
            not_found_rows.append(item)
            continue

        student_id = student["id"]

        # First enrolled
        cur.execute("""
            SELECT MIN(created_at) AS first_enrolled
            FROM enrollments
            WHERE student_id = ?
        """, (student_id,))

        first_enrolled = cur.fetchone()["first_enrolled"]

        first_enrolled_date = ""
        first_enrolled_month = ""

        if first_enrolled:
            first_enrolled_date = first_enrolled[:10]
            first_enrolled_month = first_enrolled[:7]

        # All subjects
        cur.execute("""
            SELECT DISTINCT sub.name, sub.grade
            FROM enrollments e
            JOIN subjects sub ON sub.id = e.subject_id
            WHERE e.student_id = ?
            ORDER BY e.month, sub.grade, sub.name
        """, (student_id,))

        subjects = cur.fetchall()
        subject_text = ", ".join([f"{r['name']} ({grade_label(r['grade'])})" for r in subjects]) or "N/A"

        # All months enrolled
        cur.execute("""
            SELECT DISTINCT month
            FROM enrollments
            WHERE student_id = ?
            ORDER BY month
        """, (student_id,))

        months = [r["month"] for r in cur.fetchall()]
        months_text = ", ".join(months) if months else "N/A"

        # Latest status
        cur.execute("""
            SELECT status, month
            FROM enrollments
            WHERE student_id = ?
            ORDER BY month DESC, created_at DESC
            LIMIT 1
        """, (student_id,))

        latest = cur.fetchone()
        latest_status = latest["status"] if latest else "N/A"
        latest_month = latest["month"] if latest else "N/A"

        matched_rows.append({
            "list_no": item["list_no"],
            "award_name": award_name,
            "award_grade": award_grade_raw,
            "award_category": item["award_category"],
            "match_score": match_score,
            "match_note": match_note,

            "student_id": student["id"],
            "portal_name": student["full_name"],
            "phone": student["phone_whatsapp"],
            "guardian_name": student["guardian_name"],
            "guardian_phone": student["guardian_phone"],
            "email": student["email"],
            "portal_grade": student["grade"],
            "province": student["province"],
            "school": student["school"],
            "pin": student["pin"],

            "first_enrolled": first_enrolled_date,
            "first_enrolled_month": first_enrolled_month,
            "all_subjects": subject_text,
            "all_months": months_text,
            "latest_status": latest_status,
            "latest_month": latest_month
        })

    conn.close()

    # =========================
    # Build Excel
    # =========================

    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
    from openpyxl.utils import get_column_letter

    wb = Workbook()

    header_fill = PatternFill(start_color="1B5E20", end_color="1B5E20", fill_type="solid")
    gold_fill = PatternFill(start_color="FFF3CD", end_color="FFF3CD", fill_type="solid")
    red_fill = PatternFill(start_color="F8D7DA", end_color="F8D7DA", fill_type="solid")

    thin_border = Border(
        left=Side(style="thin", color="DDDDDD"),
        right=Side(style="thin", color="DDDDDD"),
        top=Side(style="thin", color="DDDDDD"),
        bottom=Side(style="thin", color="DDDDDD"),
    )

    def style_header(ws, row_num=1):
        for cell in ws[row_num]:
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = header_fill
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            cell.border = thin_border

    def autofit(ws):
        for col in ws.columns:
            max_length = 0
            col_letter = get_column_letter(col[0].column)

            for cell in col:
                value = "" if cell.value is None else str(cell.value)
                max_length = max(max_length, len(value))
                cell.border = thin_border
                cell.alignment = Alignment(vertical="top", wrap_text=True)

            ws.column_dimensions[col_letter].width = min(max_length + 4, 55)

    # Sheet 1: Matched
    ws = wb.active
    ws.title = "Matched Awards Students"

    matched_headers = [
        "Award List No",
        "Award Learner Name",
        "Award Grade",
        "Award Category",
        "Match Score",
        "Match Note",
        "Portal Student ID",
        "Portal Full Name",
        "Student Phone",
        "Guardian Name",
        "Guardian Phone",
        "Email",
        "Portal Grade",
        "Province",
        "School",
        "PIN",
        "First Enrolled Date",
        "First Enrolled Month",
        "All Enrolled Subjects",
        "All Enrollment Months",
        "Latest Status",
        "Latest Month"
    ]

    ws.append(matched_headers)
    style_header(ws, 1)

    for r0 in matched_rows:
        ws.append([
            r0["list_no"],
            r0["award_name"],
            r0["award_grade"],
            r0["award_category"],
            r0["match_score"],
            r0["match_note"],
            r0["student_id"],
            r0["portal_name"],
            r0["phone"],
            r0["guardian_name"],
            r0["guardian_phone"],
            r0["email"],
            grade_label(r0["portal_grade"]),
            r0["province"],
            r0["school"],
            r0["pin"],
            r0["first_enrolled"],
            r0["first_enrolled_month"],
            r0["all_subjects"],
            r0["all_months"],
            r0["latest_status"],
            r0["latest_month"]
        ])

    autofit(ws)
    ws.freeze_panes = "A2"
    ws.auto_filter.ref = ws.dimensions

    # Sheet 2: Not Found
    ws2 = wb.create_sheet("Not Found")

    ws2.append([
        "Award List No",
        "Learner Name",
        "Grade",
        "Award Category",
        "Reason"
    ])

    style_header(ws2, 1)

    for nf in not_found_rows:
        ws2.append([
            nf["list_no"],
            nf["learner_name"],
            nf["grade"],
            nf["award_category"],
            "No reliable matching student found. Please check spelling, grade, or whether the learner exists in the portal."
        ])

    for row in ws2.iter_rows(min_row=2):
        for cell in row:
            cell.fill = red_fill

    autofit(ws2)
    ws2.freeze_panes = "A2"
    ws2.auto_filter.ref = ws2.dimensions

    # Sheet 3: Summary
    ws3 = wb.create_sheet("Summary")

    ws3["A1"] = "EBTA Awards Student Export Summary"
    ws3["A1"].font = Font(bold=True, size=16, color="1B5E20")

    ws3.append([])
    ws3.append(["Metric", "Count"])
    style_header(ws3, 3)

    ws3.append(["Rows detected from pasted/uploaded list", len(award_rows)])
    ws3.append(["Matched portal students", len(matched_rows)])
    ws3.append(["Not found", len(not_found_rows)])

    autofit(ws3)

    output = io.BytesIO()
    wb.save(output)
    output.seek(0)

    filename = f"EBTA_Awards_Student_Export_{datetime.datetime.now().strftime('%Y%m%d_%H%M')}.xlsx"

    response = make_response(output.read())
    response.headers["Content-Type"] = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    response.headers["Content-Disposition"] = f"attachment; filename={filename}"

    return response

  
@app.post('/admin/awards-schools-export')
@require_high_admin
def admin_awards_schools_export():

    r = require_admin()
    if r: return r

    if not is_high_admin():
        return page("Access Denied", card_msg("Only high admin can export EBTA school data."))

    conn = get_db()
    cur = conn.cursor()

    # =========================
    # 1. STUDENT DETAILS
    # =========================

    cur.execute("""
        SELECT
            s.id,
            s.full_name,
            s.phone_whatsapp,
            s.guardian_name,
            s.guardian_phone,
            s.email,
            s.grade,
            s.province,
            s.school,
            s.pin,
            s.created_at,

            MIN(e.created_at) AS first_enrolled,
            MAX(e.month) AS latest_month,

            (
                SELECT e2.status
                FROM enrollments e2
                WHERE e2.student_id = s.id
                ORDER BY e2.month DESC, e2.created_at DESC
                LIMIT 1
            ) AS latest_status,

            COUNT(e.id) AS total_enrollments,
            COUNT(DISTINCT e.month) AS total_months_enrolled,

            GROUP_CONCAT(DISTINCT e.month) AS enrollment_months,
            GROUP_CONCAT(DISTINCT sub.name) AS subjects

        FROM students s
        LEFT JOIN enrollments e ON e.student_id = s.id
        LEFT JOIN subjects sub ON sub.id = e.subject_id
        GROUP BY s.id
        ORDER BY
            COALESCE(NULLIF(TRIM(s.province), ''), 'Unknown'),
            COALESCE(NULLIF(TRIM(s.school), ''), 'Unknown'),
            CAST(REPLACE(s.grade, 'G', '') AS INTEGER),
            s.full_name
    """)

    student_rows = cur.fetchall()

    # =========================
    # 2. SCHOOL STATS
    # =========================

    cur.execute("""
        SELECT
            COALESCE(NULLIF(TRIM(s.province), ''), 'Unknown / Missing Province') AS province,
            COALESCE(NULLIF(TRIM(s.school), ''), 'Unknown / Missing School') AS school,

            COUNT(DISTINCT s.id) AS total_students,

            COUNT(DISTINCT CASE WHEN s.grade='G8' THEN s.id END) AS grade_8,
            COUNT(DISTINCT CASE WHEN s.grade='G9' THEN s.id END) AS grade_9,
            COUNT(DISTINCT CASE WHEN s.grade='G10' THEN s.id END) AS grade_10,
            COUNT(DISTINCT CASE WHEN s.grade='G11' THEN s.id END) AS grade_11,
            COUNT(DISTINCT CASE WHEN s.grade='G12' THEN s.id END) AS grade_12,
            COUNT(DISTINCT CASE WHEN s.grade='G13' THEN s.id END) AS grade_13,

            COUNT(e.id) AS total_enrollments,
            COUNT(DISTINCT e.month) AS months_active

        FROM students s
        LEFT JOIN enrollments e ON e.student_id = s.id
        GROUP BY province, school
        ORDER BY province, total_students DESC, school
    """)

    school_stats = cur.fetchall()

    # =========================
    # 3. PROVINCE STATS
    # =========================

    cur.execute("""
        SELECT
            COALESCE(NULLIF(TRIM(s.province), ''), 'Unknown / Missing Province') AS province,

            COUNT(DISTINCT s.id) AS total_students,
            COUNT(DISTINCT COALESCE(NULLIF(TRIM(s.school), ''), 'Unknown / Missing School')) AS total_schools,

            COUNT(DISTINCT CASE WHEN s.grade='G8' THEN s.id END) AS grade_8,
            COUNT(DISTINCT CASE WHEN s.grade='G9' THEN s.id END) AS grade_9,
            COUNT(DISTINCT CASE WHEN s.grade='G10' THEN s.id END) AS grade_10,
            COUNT(DISTINCT CASE WHEN s.grade='G11' THEN s.id END) AS grade_11,
            COUNT(DISTINCT CASE WHEN s.grade='G12' THEN s.id END) AS grade_12,
            COUNT(DISTINCT CASE WHEN s.grade='G13' THEN s.id END) AS grade_13,

            COUNT(e.id) AS total_enrollments

        FROM students s
        LEFT JOIN enrollments e ON e.student_id = s.id
        GROUP BY province
        ORDER BY total_students DESC, province
    """)

    province_stats = cur.fetchall()

    # =========================
    # 4. GRADE STATS
    # =========================

    cur.execute("""
        SELECT
            s.grade,
            COUNT(DISTINCT s.id) AS total_students,
            COUNT(DISTINCT COALESCE(NULLIF(TRIM(s.school), ''), 'Unknown / Missing School')) AS total_schools,
            COUNT(DISTINCT COALESCE(NULLIF(TRIM(s.province), ''), 'Unknown / Missing Province')) AS total_provinces,
            COUNT(e.id) AS total_enrollments
        FROM students s
        LEFT JOIN enrollments e ON e.student_id = s.id
        GROUP BY s.grade
        ORDER BY CAST(REPLACE(s.grade, 'G', '') AS INTEGER)
    """)

    grade_stats = cur.fetchall()

    # =========================
    # 5. MISSING SCHOOL / PROVINCE
    # =========================

    cur.execute("""
        SELECT
            s.full_name,
            s.phone_whatsapp,
            s.guardian_name,
            s.guardian_phone,
            s.email,
            s.grade,
            s.province,
            s.school,
            s.pin,
            s.created_at
        FROM students s
        WHERE s.school IS NULL
           OR TRIM(s.school) = ''
           OR s.province IS NULL
           OR TRIM(s.province) = ''
        ORDER BY s.grade, s.full_name
    """)

    missing_rows = cur.fetchall()

    conn.close()

    # =========================
    # BUILD EXCEL
    # =========================

    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
    from openpyxl.utils import get_column_letter

    wb = Workbook()

    # Styles
    header_fill = PatternFill(start_color="1B5E20", end_color="1B5E20", fill_type="solid")
    red_fill = PatternFill(start_color="F8D7DA", end_color="F8D7DA", fill_type="solid")

    thin_border = Border(
        left=Side(style="thin", color="DDDDDD"),
        right=Side(style="thin", color="DDDDDD"),
        top=Side(style="thin", color="DDDDDD"),
        bottom=Side(style="thin", color="DDDDDD"),
    )

    def style_header(ws, row_num=1):
        for cell in ws[row_num]:
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = header_fill
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            cell.border = thin_border

    def style_title(cell):
        cell.font = Font(bold=True, size=16, color="1B5E20")

    def autofit(ws):
        for col in ws.columns:
            max_length = 0
            col_letter = get_column_letter(col[0].column)

            for cell in col:
                value = "" if cell.value is None else str(cell.value)
                max_length = max(max_length, len(value))
                cell.border = thin_border
                cell.alignment = Alignment(vertical="top", wrap_text=True)

            ws.column_dimensions[col_letter].width = min(max_length + 4, 55)

    def nz(v):
        return v if v and str(v).strip() else "N/A"

    # =========================
    # SHEET 1: SUMMARY
    # =========================

    ws = wb.active
    ws.title = "Summary"

    total_students = len(student_rows)
    total_schools = len(school_stats)
    total_provinces = len(province_stats)
    missing_count = len(missing_rows)

    ws["A1"] = "EBTA Schools & Student Details Export"
    style_title(ws["A1"])
    ws.merge_cells("A1:E1")

    ws.append([])
    ws.append(["Metric", "Count", "Notes"])
    style_header(ws, 3)

    ws.append(["Total Students", total_students, "All students captured on the EBTA portal"])
    ws.append(["Total Schools", total_schools, "Unique schools based on student records"])
    ws.append(["Total Provinces", total_provinces, "Unique provinces based on student records"])
    ws.append(["Students Missing School or Province", missing_count, "These records should be cleaned later"])

    ws.append([])
    ws.append(["Generated At", now_utc_iso(), "Africa/Johannesburg time"])

    autofit(ws)

    # =========================
    # SHEET 2: STUDENT DETAILS
    # =========================

    ws2 = wb.create_sheet("Student Details")

    ws2.append([
        "Student ID",
        "Full Name",
        "Phone",
        "Guardian Name",
        "Guardian Phone",
        "Email",
        "Grade",
        "Province",
        "School",
        "PIN",
        "Created At",
        "First Enrolled Date",
        "First Enrolled Month",
        "Latest Enrollment Month",
        "Latest Status",
        "Total Enrollments",
        "Total Months Enrolled",
        "Enrollment Months",
        "Subjects"
    ])

    style_header(ws2, 1)

    for s in student_rows:
        first_enrolled = s["first_enrolled"] or ""
        first_enrolled_date = first_enrolled[:10] if first_enrolled else ""
        first_enrolled_month = first_enrolled[:7] if first_enrolled else ""

        ws2.append([
            s["id"],
            nz(s["full_name"]),
            nz(s["phone_whatsapp"]),
            nz(s["guardian_name"]),
            nz(s["guardian_phone"]),
            nz(s["email"]),
            grade_label(s["grade"]) if s["grade"] else "N/A",
            nz(s["province"]),
            nz(s["school"]),
            nz(s["pin"]),
            nz((s["created_at"] or "")[:10]),
            nz(first_enrolled_date),
            nz(first_enrolled_month),
            nz(s["latest_month"]),
            nz(s["latest_status"]),
            s["total_enrollments"] or 0,
            s["total_months_enrolled"] or 0,
            nz(s["enrollment_months"]),
            nz(s["subjects"])
        ])

    ws2.freeze_panes = "A2"
    ws2.auto_filter.ref = ws2.dimensions
    autofit(ws2)

    # =========================
    # SHEET 3: SCHOOLS BY PROVINCE
    # =========================

    ws3 = wb.create_sheet("Schools by Province")

    ws3.append([
        "Province",
        "School",
        "Total Students",
        "Grade 8",
        "Grade 9",
        "Grade 10",
        "Grade 11",
        "Grade 12",
        "Grade 13",
        "Total Enrollments",
        "Months Active"
    ])

    style_header(ws3, 1)

    for row in school_stats:
        ws3.append([
            row["province"],
            row["school"],
            row["total_students"] or 0,
            row["grade_8"] or 0,
            row["grade_9"] or 0,
            row["grade_10"] or 0,
            row["grade_11"] or 0,
            row["grade_12"] or 0,
            row["grade_13"] or 0,
            row["total_enrollments"] or 0,
            row["months_active"] or 0
        ])

    ws3.freeze_panes = "A2"
    ws3.auto_filter.ref = ws3.dimensions
    autofit(ws3)

    # =========================
    # SHEET 4: PROVINCE SUMMARY
    # =========================

    ws4 = wb.create_sheet("Province Summary")

    ws4.append([
        "Province",
        "Total Students",
        "Total Schools",
        "Grade 8",
        "Grade 9",
        "Grade 10",
        "Grade 11",
        "Grade 12",
        "Grade 13",
        "Total Enrollments"
    ])

    style_header(ws4, 1)

    for row in province_stats:
        ws4.append([
            row["province"],
            row["total_students"] or 0,
            row["total_schools"] or 0,
            row["grade_8"] or 0,
            row["grade_9"] or 0,
            row["grade_10"] or 0,
            row["grade_11"] or 0,
            row["grade_12"] or 0,
            row["grade_13"] or 0,
            row["total_enrollments"] or 0
        ])

    ws4.freeze_panes = "A2"
    ws4.auto_filter.ref = ws4.dimensions
    autofit(ws4)

    # =========================
    # SHEET 5: GRADE SUMMARY
    # =========================

    ws5 = wb.create_sheet("Grade Summary")

    ws5.append([
        "Grade",
        "Total Students",
        "Total Schools",
        "Total Provinces",
        "Total Enrollments"
    ])

    style_header(ws5, 1)

    for row in grade_stats:
        ws5.append([
            grade_label(row["grade"]) if row["grade"] else "N/A",
            row["total_students"] or 0,
            row["total_schools"] or 0,
            row["total_provinces"] or 0,
            row["total_enrollments"] or 0
        ])

    ws5.freeze_panes = "A2"
    ws5.auto_filter.ref = ws5.dimensions
    autofit(ws5)

    # =========================
    # SHEET 6: MISSING SCHOOL OR PROVINCE
    # =========================

    ws6 = wb.create_sheet("Missing School or Province")

    ws6.append([
        "Full Name",
        "Phone",
        "Guardian Name",
        "Guardian Phone",
        "Email",
        "Grade",
        "Province",
        "School",
        "PIN",
        "Created At",
        "Missing Field"
    ])

    style_header(ws6, 1)

    for s in missing_rows:
        missing = []

        if not s["province"] or not str(s["province"]).strip():
            missing.append("Province")

        if not s["school"] or not str(s["school"]).strip():
            missing.append("School")

        ws6.append([
            nz(s["full_name"]),
            nz(s["phone_whatsapp"]),
            nz(s["guardian_name"]),
            nz(s["guardian_phone"]),
            nz(s["email"]),
            grade_label(s["grade"]) if s["grade"] else "N/A",
            nz(s["province"]),
            nz(s["school"]),
            nz(s["pin"]),
            nz((s["created_at"] or "")[:10]),
            ", ".join(missing)
        ])

    for row in ws6.iter_rows(min_row=2):
        for cell in row:
            cell.fill = red_fill

    ws6.freeze_panes = "A2"
    ws6.auto_filter.ref = ws6.dimensions
    autofit(ws6)

    # =========================
    # OUTPUT FILE
    # =========================

    output = io.BytesIO()
    wb.save(output)
    output.seek(0)

    filename = f"EBTA_Schools_Student_Details_{datetime.datetime.now().strftime('%Y%m%d_%H%M')}.xlsx"

    response = make_response(output.read())
    response.headers["Content-Type"] = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    response.headers["Content-Disposition"] = f"attachment; filename={filename}"

    return response  
  
@app.get('/admin/students/export')
def admin_students_export():
    r = require_admin()
    if r:
        return r

    month = request.args.get("month")
    if not month:
        return redirect(url_for('admin_students'))

    conn = get_db()
    cur = conn.cursor()

    # =========================
    # 1. SUMMARY STATS
    # =========================

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM enrollments
        WHERE month = ?
    """, (month,))
    total_enrollments = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(DISTINCT student_id) AS c
        FROM enrollments
        WHERE month = ?
    """, (month,))
    total_students = cur.fetchone()["c"] or 0

    status_stats = {}

    for st in ["ACTIVE", "PENDING", "LAPSED"]:
        cur.execute("""
            SELECT COUNT(*) AS c
            FROM enrollments
            WHERE month = ?
              AND status = ?
        """, (month, st))
        enrollment_count = cur.fetchone()["c"] or 0

        cur.execute("""
            SELECT COUNT(DISTINCT student_id) AS c
            FROM enrollments
            WHERE month = ?
              AND status = ?
        """, (month, st))
        student_count = cur.fetchone()["c"] or 0

        status_stats[st] = {
            "enrollments": enrollment_count,
            "students": student_count
        }

    # =========================
    # 2. GRADE STATS
    # =========================

    cur.execute("""
        SELECT
            s.grade,
            COUNT(e.id) AS total_enrollments,
            COUNT(DISTINCT s.id) AS total_students,

            COUNT(CASE WHEN e.status='ACTIVE' THEN 1 END) AS active_enrollments,
            COUNT(DISTINCT CASE WHEN e.status='ACTIVE' THEN s.id END) AS active_students,

            COUNT(CASE WHEN e.status='PENDING' THEN 1 END) AS pending_enrollments,
            COUNT(DISTINCT CASE WHEN e.status='PENDING' THEN s.id END) AS pending_students,

            COUNT(CASE WHEN e.status='LAPSED' THEN 1 END) AS lapsed_enrollments,
            COUNT(DISTINCT CASE WHEN e.status='LAPSED' THEN s.id END) AS lapsed_students

        FROM enrollments e
        JOIN students s ON s.id = e.student_id
        WHERE e.month = ?
        GROUP BY s.grade
        ORDER BY CAST(REPLACE(s.grade,'G','') AS INTEGER)
    """, (month,))

    grade_stats = cur.fetchall()

    # =========================
    # 3. STUDENT SUMMARY
    # One row per student
    # =========================

    cur.execute("""
        SELECT
            s.id,
            s.full_name,
            s.phone_whatsapp,
            s.guardian_name,
            s.guardian_phone,
            s.email,
            s.grade,
            s.province,
            s.school,

            COUNT(e.id) AS total_enrollments,
            COUNT(CASE WHEN e.status='ACTIVE' THEN 1 END) AS active_enrollments,
            COUNT(CASE WHEN e.status='PENDING' THEN 1 END) AS pending_enrollments,
            COUNT(CASE WHEN e.status='LAPSED' THEN 1 END) AS lapsed_enrollments,

            GROUP_CONCAT(DISTINCT sub.name) AS subjects,
            GROUP_CONCAT(DISTINCT e.status) AS statuses

        FROM students s
        JOIN enrollments e ON e.student_id = s.id
        JOIN subjects sub ON sub.id = e.subject_id
        WHERE e.month = ?
        GROUP BY s.id
        ORDER BY s.full_name ASC
    """, (month,))

    student_rows = cur.fetchall()

    # =========================
    # 4. ENROLLMENT DETAILS
    # One row per enrollment/subject
    # =========================

    cur.execute("""
        SELECT
            e.id AS enrollment_id,
            s.full_name,
            s.phone_whatsapp,
            s.guardian_name,
            s.guardian_phone,
            s.email,
            s.grade,
            s.province,
            s.school,
            sub.name AS subject_name,
            e.status,
            e.payment_method,
            e.amount_paid,
            e.payment_ref,
            e.created_at
        FROM enrollments e
        JOIN students s ON s.id = e.student_id
        JOIN subjects sub ON sub.id = e.subject_id
        WHERE e.month = ?
        ORDER BY s.full_name ASC, sub.name ASC
    """, (month,))

    enrollment_rows = cur.fetchall()

    conn.close()

    # =========================
    # 5. BUILD EXCEL FILE
    # =========================

    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
    from openpyxl.utils import get_column_letter

    wb = Workbook()

    # Styles
    header_fill = PatternFill(start_color="1B5E20", end_color="1B5E20", fill_type="solid")
    light_fill = PatternFill(start_color="E8F5E9", end_color="E8F5E9", fill_type="solid")
    yellow_fill = PatternFill(start_color="FFF3CD", end_color="FFF3CD", fill_type="solid")
    red_fill = PatternFill(start_color="F8D7DA", end_color="F8D7DA", fill_type="solid")
    thin_border = Border(
        left=Side(style="thin", color="DDDDDD"),
        right=Side(style="thin", color="DDDDDD"),
        top=Side(style="thin", color="DDDDDD"),
        bottom=Side(style="thin", color="DDDDDD"),
    )

    def style_header(row):
        for cell in row:
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = header_fill
            cell.alignment = Alignment(horizontal="center")
            cell.border = thin_border

    def autofit(ws):
        for col in ws.columns:
            max_length = 0
            col_letter = get_column_letter(col[0].column)
            for cell in col:
                value = "" if cell.value is None else str(cell.value)
                max_length = max(max_length, len(value))
                cell.border = thin_border
                cell.alignment = Alignment(vertical="top", wrap_text=True)
            ws.column_dimensions[col_letter].width = min(max_length + 4, 45)

    # =========================
    # SHEET 1: SUMMARY
    # =========================

    ws = wb.active
    ws.title = "Summary"

    ws["A1"] = f"EBTA Enrollment Export Summary - {month}"
    ws["A1"].font = Font(bold=True, size=16, color="1B5E20")
    ws.merge_cells("A1:D1")

    ws.append([])
    ws.append(["Metric", "Students", "Enrollments", "Notes"])
    style_header(ws[3])

    ws.append(["Total", total_students, total_enrollments, "Students are counted once. Enrollments count each subject registration."])
    ws.append(["Active", status_stats["ACTIVE"]["students"], status_stats["ACTIVE"]["enrollments"], "Approved/active students and subject enrollments."])
    ws.append(["Pending", status_stats["PENDING"]["students"], status_stats["PENDING"]["enrollments"], "Pending students and subject enrollments."])
    ws.append(["Lapsed", status_stats["LAPSED"]["students"], status_stats["LAPSED"]["enrollments"], "Lapsed students and subject enrollments."])

    ws.append([])
    ws.append(["Breakdown by Grade"])
    ws[9][0].font = Font(bold=True, color="1B5E20")

    ws.append([
        "Grade",
        "Total Students",
        "Total Enrollments",
        "Active Students",
        "Active Enrollments",
        "Pending Students",
        "Pending Enrollments",
        "Lapsed Students",
        "Lapsed Enrollments"
    ])
    style_header(ws[10])

    for g in grade_stats:
        ws.append([
            grade_label(g["grade"]),
            g["total_students"],
            g["total_enrollments"],
            g["active_students"],
            g["active_enrollments"],
            g["pending_students"],
            g["pending_enrollments"],
            g["lapsed_students"],
            g["lapsed_enrollments"]
        ])

    autofit(ws)

    # =========================
    # SHEET 2: STUDENT SUMMARY
    # =========================

    ws2 = wb.create_sheet("Student Summary")

    headers = [
        "Full Name",
        "Phone",
        "Guardian Name",
        "Guardian Phone",
        "Email",
        "Grade",
        "Province",
        "School",
        "Subjects",
        "Statuses",
        "Total Enrollments",
        "Active Enrollments",
        "Pending Enrollments",
        "Lapsed Enrollments"
    ]

    ws2.append(headers)
    style_header(ws2[1])

    for r in student_rows:
        ws2.append([
            r["full_name"],
            r["phone_whatsapp"],
            r["guardian_name"],
            r["guardian_phone"],
            r["email"],
            grade_label(r["grade"]),
            r["province"],
            r["school"],
            r["subjects"],
            r["statuses"],
            r["total_enrollments"],
            r["active_enrollments"],
            r["pending_enrollments"],
            r["lapsed_enrollments"]
        ])

    autofit(ws2)

    # =========================
    # SHEET 3: ENROLLMENT DETAILS
    # =========================

    ws3 = wb.create_sheet("Enrollment Details")

    headers = [
        "Enrollment ID",
        "Full Name",
        "Phone",
        "Guardian Name",
        "Guardian Phone",
        "Email",
        "Grade",
        "Province",
        "School",
        "Subject",
        "Status",
        "Payment Method",
        "Amount Paid",
        "Payment Ref",
        "Created At"
    ]

    ws3.append(headers)
    style_header(ws3[1])

    for r in enrollment_rows:
        ws3.append([
            r["enrollment_id"],
            r["full_name"],
            r["phone_whatsapp"],
            r["guardian_name"],
            r["guardian_phone"],
            r["email"],
            grade_label(r["grade"]),
            r["province"],
            r["school"],
            r["subject_name"],
            r["status"],
            r["payment_method"],
            r["amount_paid"],
            r["payment_ref"],
            r["created_at"]
        ])

    autofit(ws3)

    # Freeze top rows
    ws.freeze_panes = "A4"
    ws2.freeze_panes = "A2"
    ws3.freeze_panes = "A2"

    file_name = f"enrollment_students_{month}.xlsx"
    file_path = f"/tmp/{file_name}"
    wb.save(file_path)

    return send_from_directory("/tmp", file_name, as_attachment=True)


@app.get('/admin/students/compare')
def admin_students_compare_export():
    r = require_admin()
    if r:
        return r

    prev_month = request.args.get("prev")
    curr_month = request.args.get("curr")

    if not prev_month or not curr_month:
        return redirect(url_for('admin_students'))

    conn = get_db()
    cur = conn.cursor()

    # ACTIVE students only
    cur.execute("""
        SELECT DISTINCT s.id, s.full_name, s.phone_whatsapp, s.grade, s.guardian_name, s.guardian_phone, s.email
        FROM students s
        JOIN enrollments e ON e.student_id = s.id
        WHERE e.month = ?
          AND e.status = 'ACTIVE'
    """, (prev_month,))
    prev_rows = cur.fetchall()

    cur.execute("""
        SELECT DISTINCT s.id, s.full_name, s.phone_whatsapp, s.grade, s.guardian_name, s.guardian_phone, s.email
        FROM students s
        JOIN enrollments e ON e.student_id = s.id
        WHERE e.month = ?
          AND e.status IN ('ACTIVE','PENDING')
    """, (curr_month,))
    curr_rows = cur.fetchall()

    conn.close()

    prev_dict = {r["id"]: r for r in prev_rows}
    curr_dict = {r["id"]: r for r in curr_rows}

    all_ids = set(prev_dict.keys()) | set(curr_dict.keys())

    continued = []
    lost = []
    new = []

    for sid in all_ids:
        in_prev = sid in prev_dict
        in_curr = sid in curr_dict
        base = prev_dict.get(sid) or curr_dict.get(sid)

        row = [
            base["full_name"],
            base["phone_whatsapp"],
            grade_label(base["grade"]),
            base["guardian_name"] or "",
            base["guardian_phone"] or "",
            base["email"] or "",
            "YES" if in_prev else "NO",
            "YES" if in_curr else "NO",
        ]

        if in_prev and in_curr:
            continued.append(row)
        elif in_prev and not in_curr:
            lost.append(row)
        elif not in_prev and in_curr:
            new.append(row)

    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment

    wb = Workbook()

    # ---------- SUMMARY SHEET ----------
    ws = wb.active
    ws.title = "Summary"

    headers = [
        "Learner Full Name",
        "Learner Phone",
        "Grade",
        "Parent/Guardian Name",
        "Parent/Guardian Phone",
        "Parent/Guardian Email",
        f"Enrolled {prev_month}",
        f"Enrolled {curr_month}",
        "Status"
    ]

    ws.append([f"Comparison: {prev_month} vs {curr_month}"])
    ws.append([])

    total_prev = len(prev_dict)
    total_curr = len(curr_dict)
    total_cont = len(continued)

    retention_pct = round((total_cont / total_prev) * 100, 2) if total_prev else 0

    ws.append(["Previous Month Students", total_prev])
    ws.append(["Current Month Students", total_curr])
    ws.append(["Continued Students", total_cont])
    ws.append(["Lost Students", len(lost)])
    ws.append(["New Students", len(new)])
    ws.append(["Retention %", f"{retention_pct}%"])
    ws.append([])

    ws.append(headers)

    for col in ws[ws.max_row]:
        col.font = Font(bold=True)
        col.alignment = Alignment(horizontal="center")

    green = PatternFill(start_color="C6EFCE", end_color="C6EFCE", fill_type="solid")
    red = PatternFill(start_color="FFC7CE", end_color="FFC7CE", fill_type="solid")
    yellow = PatternFill(start_color="FFEB9C", end_color="FFEB9C", fill_type="solid")

    # Add all students to summary
    for row in continued:
        ws.append(row + ["CONTINUED"])
        for c in ws[ws.max_row]:
            c.fill = green

    for row in lost:
        ws.append(row + ["LOST"])
        for c in ws[ws.max_row]:
            c.fill = red

    for row in new:
        ws.append(row + ["NEW"])
        for c in ws[ws.max_row]:
            c.fill = yellow

    # Auto column width
    for col in ws.columns:
        max_length = max(len(str(cell.value)) if cell.value else 0 for cell in col)
        ws.column_dimensions[col[0].column_letter].width = max_length + 4

    # ---------- CONTINUED SHEET ----------
    ws_cont = wb.create_sheet("Continued")
    ws_cont.append(headers[:-1])
    for col in ws_cont[1]:
        col.font = Font(bold=True)

    for row in continued:
        ws_cont.append(row)

    # ---------- LOST SHEET ----------
    ws_lost = wb.create_sheet("Lost")
    ws_lost.append(headers[:-1])
    for col in ws_lost[1]:
        col.font = Font(bold=True)

    for row in lost:
        ws_lost.append(row)

    # ---------- NEW SHEET ----------
    ws_new = wb.create_sheet("New")
    ws_new.append(headers[:-1])
    for col in ws_new[1]:
        col.font = Font(bold=True)

    for row in new:
        ws_new.append(row)

    file_name = f"compare_{prev_month}_vs_{curr_month}.xlsx"
    file_path = f"/tmp/{file_name}"
    wb.save(file_path)

    return send_from_directory("/tmp", file_name, as_attachment=True)
    
