@app.post('/admin/followups/update/<int:fid>')
def admin_followup_update(fid):

    r = require_admin()
    if r:
        return r

    conn = get_db()
    cur = conn.cursor()

    updated_by = request.form.get("updated_by") or "Admin"
    new_note = request.form.get("new_note", "").strip()

    # Get existing notes and subjects first so they are not overwritten accidentally
    cur.execute("""
        SELECT notes, subjects
        FROM followups
        WHERE id=?
        LIMIT 1
    """, (fid,))

    existing = cur.fetchone()

    existing_notes = ""
    if existing and existing["notes"]:
        existing_notes = existing["notes"].strip()

    final_notes = existing_notes

    # Append the new note only if something was typed
    if new_note:
        timestamp = now_utc_iso()[:16].replace("T", " ")
        note_entry = f"[{timestamp}] {updated_by}: {new_note}"

        if final_notes:
            final_notes = final_notes + "\n\n" + note_entry
        else:
            final_notes = note_entry

    existing_subjects = ""
    if existing and existing["subjects"]:
        existing_subjects = existing["subjects"].strip()

    posted_subjects = [s.strip() for s in request.form.getlist("subjects") if s.strip()]

    # Remove duplicates while keeping the same order
    clean_subjects = []
    seen_subjects = set()

    for sub in posted_subjects:
        key = sub.lower()

        if key not in seen_subjects:
            clean_subjects.append(sub)
            seen_subjects.add(key)

    if clean_subjects:
        final_subjects = ", ".join(clean_subjects)
    else:
        final_subjects = existing_subjects

    cur.execute("""
    UPDATE followups SET
        full_name=?,
        phone=?,
        grade=?,
        subjects=?,
        issue_type=?,
        followup_status=?,
        payment_date=?,
        date_communicated=?,
        notes=?,
        captured_by=?,
        updated_by=?,
        updated_at=?
    WHERE id=?
    """, (
        request.form.get("full_name"),
        request.form.get("phone"),
        request.form.get("grade"),
        final_subjects,
        request.form.get("issue_type"),
        request.form.get("followup_status"),
        request.form.get("payment_date"),
        request.form.get("date_communicated"),
        final_notes,
        request.form.get("captured_by"),
        updated_by,
        now_utc_iso(),
        fid
    ))

    conn.commit()
    conn.close()

    return redirect(request.referrer or url_for('admin_followups'))
   

@app.get("/admin/followups/export")
def export_followups():
    r = require_admin()
    if r: return r

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT * FROM followups ORDER BY created_at DESC")
    rows = cur.fetchall()
    conn.close()

    import csv
    from io import StringIO

    si = StringIO()
    writer = csv.writer(si)

    writer.writerow([
        "Name","Phone","Grade","Subjects",
        "Issue Type","Status",
        "Payment Date","Communicated",
        "Captured By","Updated By","Notes"
    ])

    for row in rows:
        writer.writerow([
            row["full_name"],
            row["phone"],
            row["grade"],
            row["subjects"],
            row["issue_type"],
            row["followup_status"],
            row["payment_date"],
            row["date_communicated"],
            row["captured_by"],
            row["updated_by"],
            row["notes"]
        ])

    output = make_response(si.getvalue())
    output.headers["Content-Disposition"] = "attachment; filename=followups.csv"
    output.headers["Content-type"] = "text/csv"
    return output

