@app.get('/manager/tracker/edit')
def manager_tracker_edit():

    r = require_manager()
    if r:
        return r

    tutor_id = request.args.get("tutor_id")
    date = request.args.get("date") or datetime.date.today().strftime("%Y-%m-%d")

    conn = get_db()
    cur = conn.cursor()
    
    cur.execute("""
    SELECT *
    FROM tutor_weekly_tracker
    WHERE tutor_id=? AND session_date=?
    """, (tutor_id, date))

    s = cur.fetchone()

    cur.execute("""
    SELECT t.full_name
    FROM tutors t
    JOIN manager_tutors mt ON mt.tutor_id = t.id
    WHERE t.id=? AND mt.manager_id=?
    """,(tutor_id, session["manager_id"]))

    tutor = cur.fetchone()

    if not tutor:
        conn.close()
