@app.get('/manager/tutor/<int:tid>')
def manager_view_tutor(tid):

    r = require_manager()
    if r: return r
    
    if not manager_check_tutor_access(tid):
        return page("Access Denied", card_msg("You are not allowed to view this tutor."))

    conn = get_db()
    cur = conn.cursor()

    # Tutor info
    cur.execute("SELECT full_name FROM tutors WHERE id=?", (tid,))
    tutor = cur.fetchone()

    if not tutor:
        conn.close()
        return page("Error", card_msg("Tutor not found"))

    # Subjects
    cur.execute("""
        SELECT s.name, s.grade
        FROM tutor_subjects ts
        JOIN subjects s ON s.id = ts.subject_id
        WHERE ts.tutor_id=?
    """, (tid,))
    subjects = cur.fetchall()

    subjects_html = ", ".join([
        f"{grade_label(s['grade'])} — {s['name']}"
        for s in subjects
    ]) or "No subjects"

    # ===================== Uploads (Improved) =====================

    # Get selected month (from URL) or fallback to current
    month = request.args.get("month")

    if not month:
        month = get_active_month('manager')
        
    # ===================== MONTH SELECTOR =====================

    system_month = get_setting('current_month')
    year = int(system_month.split('-')[0])

    all_months = all_months_for_year(year)

    month_selector = f"""
    <form method="get" action="/manager/tutor/{tid}" style="margin-top:10px">

        <select name="month"
                onchange="this.form.submit()"
                style="
                    padding:10px;
                    border-radius:8px;
                    border:1px solid #ccc;
                    cursor:pointer;
                ">

            {''.join(
                f"<option value='{m}' {'selected' if m == month else ''}>"
                f"{pretty_month_label(m)}"
                f"</option>"
                for m in all_months
            )}

        </select>

    </form>
    """

    cur.execute("""
        SELECT m.*, s.name AS subject_name, s.grade
        FROM materials m
        JOIN subjects s ON s.id = m.subject_id
        WHERE m.tutor_id=?
          AND substr(m.month,1,7)=?
        ORDER BY m.created_at DESC
        LIMIT 50
    """, (tid, month))

    uploads = cur.fetchall()

    recordings = []
    documents = []
    assignments = []

    for m in uploads:

        when = m['created_at'][:16].replace('T', ' ')

        is_assignment = (m['is_assignment'] == 1 or m['kind'] == 'assignment')
        is_recording = bool(m['youtube_url'])

        # action button
        if m['file_path']:
            action = f"<a class='btn mini' target='_blank' href='{m['file_path']}'>Download</a>"
        elif m['youtube_url']:
            action = f"<a class='btn success mini' target='_blank' href='{m['youtube_url']}'>Watch</a>"
        else:
            action = "<span class='muted'>No file</span>"

        row = f"""
        <tr>
            <td>{grade_label(m['grade'])} — {m['subject_name']}</td>
            <td>{m['title']}</td>
            <td>{action}</td>
            <td>{when}</td>
        </tr>
        """

        if is_assignment:
            assignments.append(row)
        elif is_recording:
            recordings.append(row)
        else:
            documents.append(row)


    uploads_html = ""

    if assignments:
        uploads_html += f"""
        <h3 style="margin-top:10px">📝 Assignments</h3>
        <div class="scroll-x">
        <table>
            <thead>
                <tr>
                    <th>Subject</th>
                    <th>Title</th>
                    <th>File</th>
                    <th>Uploaded</th>
                </tr>
            </thead>
            <tbody>
                {''.join(assignments)}
            </tbody>
        </table>
        </div>
        """

    if recordings:
        uploads_html += f"""
        <h3 style="margin-top:20px;color:#2563eb">🎥 Recordings</h3>
        <div class="scroll-x">
        <table>
            <thead>
                <tr>
                    <th>Subject</th>
                    <th>Recording</th>
                    <th>Watch</th>
                    <th>Uploaded</th>
                </tr>
            </thead>
            <tbody>
                {''.join(recordings)}
            </tbody>
        </table>
        </div>
        """

    if documents:
        uploads_html += f"""
        <h3 style="margin-top:20px;color:#16a34a">📄 Documents</h3>
        <div class="scroll-x">
        <table>
            <thead>
                <tr>
                    <th>Subject</th>
                    <th>Document</th>
                    <th>File</th>
                    <th>Uploaded</th>
                </tr>
            </thead>
            <tbody>
                {''.join(documents)}
            </tbody>
        </table>
        </div>
        """

    if not uploads_html:
        uploads_html = "<div class='empty'>No uploads for this month</div>"

    # Sessions
    cur.execute("""
        SELECT day_of_week, start_time
        FROM sessions
        WHERE tutor_id=? AND active=1
    """, (tid,))
    sessions = cur.fetchall()

    sessions_html = "".join([
        f"<li>{DOW[s['day_of_week']]} at {s['start_time']}</li>"
        for s in sessions
    ]) or "<li>No sessions</li>"

    conn.close()

    progress = tutor_work_progress_data(tid, month)
    active_learners = manager_count_active_learners_for_tutor(tid, month)
    status_class, status_label = tutor_work_band(progress["overall_rate"])
    followups = manager_get_tutor_followups(progress, active_learners)

    progress_todos_html = "".join([
        f"<li>{escape(item)}</li>"
        for item in followups
    ])

    progress_html = f"""
    <div class="card soft" style="border-left:5px solid #1b5e20">

        <div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap">
            <div>
                <h3>Work Progress — {pretty_month_label(month)}</h3>
                <div class="mini muted">
                    Progress combines materials, recordings, assignments, attendance logs,
                    marking, tracker logs, and learner engagement.
                </div>
            </div>

            <span class="chip {status_class}">
                {status_label} · {progress["overall_rate"]}%
            </span>
        </div>

        <div class="stats" style="margin-top:12px">

            <div class="stat">
                <div class="k">{active_learners}</div>
                <div class="t">Active Learners</div>
            </div>

            <div class="stat">
                <div class="k">{progress["total_uploads"]}</div>
                <div class="t">Materials</div>
            </div>

            <div class="stat">
                <div class="k">{progress["recordings_uploaded"]}</div>
                <div class="t">Recordings</div>
            </div>

            <div class="stat">
                <div class="k">{progress["assignments_uploaded"]}</div>
                <div class="t">Assignments</div>
            </div>

            <div class="stat">
                <div class="k">{progress["material_views"]}</div>
                <div class="t">Learner Views</div>
            </div>

            <div class="stat">
                <div class="k">{progress["attendance_log_rate"]}%</div>
                <div class="t">Attendance Logs</div>
            </div>

            <div class="stat">
                <div class="k">{progress["unmarked_submissions"]}</div>
                <div class="t">Unmarked</div>
            </div>

        </div>

        <div class="card" style="margin-top:12px;background:#f8fafc;border:1px solid #e2e8f0">
            <strong>Manager follow-up</strong>
            <ul style="margin-bottom:0">
                {progress_todos_html}
            </ul>
        </div>

    </div>
    """

    body = f"""
    {manager_nav()}
    <section class="grid">

        <div class="card">
            <a href="/manager/tutors" class="btn mini secondary">← Back</a>

            <h1 style="margin-top:10px">{tutor['full_name']}</h1>
            {month_selector}
            <div class="mini muted">Tutor overview</div>
        </div>

        <div class="card soft" style="border-left:5px solid #3b82f6">
            <h3>Subjects</h3>
            <div>{subjects_html}</div>
        </div>


        {progress_html}

        <div class="card soft" style="border-left:5px solid #22c55e">
            <h3>Uploads — {pretty_month_label(month)}</h3>
            {uploads_html}
        </div>

        <div class="card soft" style="border-left:5px solid #f59e0b">
            <h3>Sessions</h3>
            <ul>{sessions_html}</ul>
        </div>

    </section>
    """

    return page("Tutor View", body)  
    
    
    
