@app.route('/aqm/login', methods=['GET', 'POST'])
def aqm_login():

    if request.method == 'POST':
        phone = request.form.get("phone")
        pin = request.form.get("pin")

        conn = get_db()
        cur = conn.cursor()

        cur.execute("""
            SELECT *
            FROM academic_quality_managers
            WHERE phone=? AND pin=?
        """, (phone, pin))

        aqm = cur.fetchone()
        conn.close()

        if aqm:
            session.clear()
            session["aqm_id"] = aqm["id"]
            session["aqm_name"] = aqm["full_name"]
            return redirect(url_for("aqm_dashboard"))

        return page("Login failed", card_msg("Invalid login details."))

    body = """
    <section class="card auth-card">
        <h1>Academic Quality Manager Login</h1>

        <form method="post" class="grid">
            <div>
                <label>Phone</label>
                <input name="phone" required>
            </div>

            <div>
                <label>PIN</label>
                <input name="pin" required>
            </div>

            <button class="btn success">Login</button>
        </form>
    </section>
    """

    return page("AQM Login", body)

    
@app.get('/aqm/logout')
def aqm_logout():
    session.clear()
    return redirect(url_for("aqm_login"))
    
    
    
def rating_stars(value):
    """
    Returns a simple star display for ratings.
    Example: ★★★★☆ (4/5)
    """
    try:
        value = int(value)
    except Exception:
        value = 0

    if value < 0:
        value = 0

    if value > 5:
        value = 5

    return "★" * value + "☆" * (5 - value) + f" ({value}/5)"


def aqm_rating_snapshot(month):
    """
    Summary of student ratings for the selected month.
    Used on the AQM dashboard.
    """
    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            COUNT(*) AS total_ratings,
            ROUND(AVG(rating), 1) AS avg_rating,
            SUM(CASE WHEN rating <= 2 THEN 1 ELSE 0 END) AS low_ratings,
            SUM(CASE WHEN comment IS NOT NULL AND TRIM(comment) <> '' THEN 1 ELSE 0 END) AS comments_count
        FROM lesson_ratings
        WHERE month=?
    """, (month,))

    row = cur.fetchone()
    conn.close()

    return {
        "total_ratings": row["total_ratings"] or 0,
        "avg_rating": row["avg_rating"] or 0,
        "low_ratings": row["low_ratings"] or 0,
        "comments_count": row["comments_count"] or 0
    }
    
    
