def short_file_name(file_name, max_len=24):
    """
    Shortens long file names for display only.
    It does not rename or change the actual uploaded file.
    """
    if not file_name:
        return "—"

    file_name = str(file_name).strip()

    if len(file_name) <= max_len:
        return file_name

    if "." in file_name:
        name_part, ext = file_name.rsplit(".", 1)
        ext = "." + ext
    else:
        name_part = file_name
        ext = ""

    allowed_name_len = max_len - len(ext) - 3

    if allowed_name_len < 8:
        allowed_name_len = 8

    return name_part[:allowed_name_len] + "..." + ext    
    
    
    
@app.get('/aqm/reports')
def aqm_reports():
    r = require_aqm()
    if r: return r

    month = request.args.get("month") or get_setting("current_month")
    grade_filter = request.args.get("grade", "").strip()
    search = request.args.get("search", "").strip()
    term_filter = request.args.get("term", "").strip()

    try:
        page_num = int(request.args.get("page", 1))
    except:
        page_num = 1

    if page_num < 1:
        page_num = 1

    per_page = 10

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT DISTINCT grade
        FROM students
        ORDER BY grade
    """)
    grades = cur.fetchall()

    params = [month]
    filter_sql = ""

    if grade_filter:
        filter_sql += " AND st.grade = ?"
        params.append(grade_filter)

    if search:
        filter_sql += " AND st.full_name LIKE ?"
        params.append(f"%{search}%")
        
    if term_filter:
        filter_sql += " AND sr.term = ?"
        params.append(term_filter)

    cur.execute(f"""
        SELECT sr.*, 
               st.full_name, 
               st.grade, 
               st.school,
               st.phone_whatsapp,
               st.guardian_phone,
               st.profile_picture_path
        FROM student_reports sr
        JOIN students st ON st.id = sr.student_id
        WHERE substr(sr.upload_date,1,7)=?
        {filter_sql}
        ORDER BY sr.upload_date DESC
    """, params)

    all_reports = cur.fetchall()
    conn.close()

    total_reports = len(all_reports)
    total_pages = (total_reports + per_page - 1) // per_page

    if total_pages == 0:
        total_pages = 1

    if page_num > total_pages:
        page_num = total_pages

    start_index = (page_num - 1) * per_page
    end_index = start_index + per_page
    reports = all_reports[start_index:end_index]

    grade_options = '<option value="">All Grades</option>'

