@app.post('/apply')
def tutor_application_submit():
    applications_open = get_setting("applications_open", "1")
    closed_message = get_setting(
        "applications_closed_message",
        "Applications are currently closed while we review the submissions already received. Please check this page again soon for the next EBTA tutor recruitment intake. Thank you for your interest in joining the EBTA team."
    )

    if applications_open != "1":
        body = f"""
        <section class="wrap">
            <div class="card soft" style="
                max-width:1100px;
                margin:30px auto;
                border-left:5px solid #ef4444;
                text-align:center;
                padding:48px 32px;
            ">
                <h1 style="
                    margin:0 0 22px 0;
                    font-size:26px;
                    text-align:center;
                ">
                    Applications Closed
                </h1>

                <p class="muted" style="
                    max-width:820px;
                    margin:0 auto 32px auto;
                    font-size:18px;
                    line-height:1.8;
                    text-align:center;
                    white-space:pre-wrap;
                ">
                    {escape(closed_message)}
                </p>

                <div style="display:flex;justify-content:center">
                    <a class="btn secondary" href="/" style="
                        min-width:180px;
                        justify-content:center;
                    ">
                        Back to Home
                    </a>
                </div>
            </div>
        </section>
        """
        return page("Applications Closed", body)
    # Honeypot anti-spam check
    if request.form.get("website", "").strip():
        return redirect(url_for("home"))

    full_name = request.form.get("full_name", "").strip()
    phone = request.form.get("phone", "").strip()
    email = request.form.get("email", "").strip()
    province = request.form.get("province", "").strip()
    city = request.form.get("city", "").strip()

    highest_qualification = request.form.get("highest_qualification", "").strip()
    institution = request.form.get("institution", "").strip()
    experience_summary = request.form.get("experience_summary", "").strip()
    availability = request.form.get("availability", "").strip()

    grades = request.form.getlist("grades")
    subjects = request.form.getlist("subjects")

    reliable_internet = 1 if request.form.get("reliable_internet") == "1" else 0
    device_access = 1 if request.form.get("device_access") == "1" else 0
    consent = 1 if request.form.get("consent") == "1" else 0

    if (
        not full_name
        or not phone
        or not grades
        or not subjects
        or reliable_internet != 1
        or device_access != 1
        or consent != 1
    ):
        return page(
            "Application incomplete",
            card_msg("Please complete your name, phone number, grades, subjects, internet/device confirmations, and consent checkbox.")
        )

    cv = request.files.get("cv")
    certificate = request.files.get("certificate")

    if not cv or not cv.filename:
        return page("CV required", card_msg("Please upload your CV before submitting."))

    if not is_valid_application_file(cv.filename):
        return page("Invalid CV", card_msg("Please upload your CV as PDF, DOC, or DOCX."))

    cv_path, cv_name = save_application_file(cv, full_name, "CV")

    if not cv_path:
        return page("Upload failed", card_msg("Your CV could not be uploaded. Please try again."))

    cert_path, cert_name = None, None

    if certificate and certificate.filename:
        if not is_valid_application_file(certificate.filename):
            return page("Invalid document", card_msg("Certificate must be PDF, DOC, DOCX, PNG, JPG, or JPEG."))

        cert_path, cert_name = save_application_file(certificate, full_name, "Certificate")

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        INSERT INTO tutor_applications(
            full_name,
            phone,
            email,
            province,
            city,
            highest_qualification,
            institution,
            experience_summary,
            availability,
            grades,
            subjects,
            cv_file_path,
            cv_file_name,
            certificate_file_path,
            certificate_file_name,
            status,
            reliable_internet,
            device_access,
            consent,
            ip_address,
            user_agent,
            created_at,
            updated_at
        )
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
    """, (
        full_name,
        phone,
        email,
        province,
        city,
        highest_qualification,
        institution,
        experience_summary,
        availability,
        json.dumps(grades),
        json.dumps(subjects),
        cv_path,
        cv_name,
        cert_path,
        cert_name,
        "NEW",
        reliable_internet,
        device_access,
        consent,
        request.remote_addr,
        request.headers.get("User-Agent", "")[:300],
        now_utc_iso(),
        now_utc_iso()
    ))

    conn.commit()
    conn.close()

    body = """
    <section class="wrap small">
        <div class="card soft" style="border-left:5px solid #1b5e20">
            <h1>Application Submitted</h1>
            <p class="muted">
                Thank you for applying to EBTA. Your application has been received successfully.
            </p>
            <a class="btn success" href="/">Back to Home</a>
        </div>
    </section>
    """

    return page("Application Submitted", body)
    
@app.get('/admin/applications')
@require_high_admin
def admin_applications():

    r = require_admin()
    if r: return r

    q = request.args.get("q", "").strip()
    grade_filter = request.args.get("grade", "").strip()
    subject_filter = request.args.get("subject", "").strip()
    status_filter = request.args.get("status", "").strip()

    try:
        page_num = int(request.args.get("page", 1))
    except:
        page_num = 1

    if page_num < 1:
        page_num = 1

    limit = 20
    offset = (page_num - 1) * limit

    where_parts = []
    params = []

    if q:
        where_parts.append("""
            (
                full_name LIKE ?
                OR phone LIKE ?
                OR email LIKE ?
                OR province LIKE ?
                OR city LIKE ?
                OR highest_qualification LIKE ?
            )
        """)
        term = f"%{q}%"
        params.extend([term, term, term, term, term, term])

    if grade_filter:
        where_parts.append("grades LIKE ?")
        params.append(f"%{grade_filter}%")

    if subject_filter:
        where_parts.append("subjects LIKE ?")
        params.append(f"%{subject_filter}%")

    if status_filter:
        where_parts.append("status = ?")
        params.append(status_filter)

    where_sql = ""
    if where_parts:
        where_sql = "WHERE " + " AND ".join(where_parts)

    conn = get_db()
    cur = conn.cursor()

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM tutor_applications
        {where_sql}
    """, params)

    total = cur.fetchone()["c"]
    total_pages = (total + limit - 1) // limit

    if total_pages == 0:
        total_pages = 1

    if page_num > total_pages:
        page_num = total_pages

    offset = (page_num - 1) * limit

    cur.execute(f"""
        SELECT *
        FROM tutor_applications
        {where_sql}
        ORDER BY created_at DESC
        LIMIT ? OFFSET ?
    """, (*params, limit, offset))

    applications = cur.fetchall()

    cur.execute("""
        SELECT DISTINCT name
        FROM subjects
        ORDER BY name
    """)
    subject_rows = cur.fetchall()

    conn.close()

    grade_options = '<option value="">All Grades</option>'
    for g in ["G8", "G9", "G10", "G11", "G12", "G13"]:
        selected = "selected" if grade_filter == g else ""
        grade_options += f"<option value='{g}' {selected}>{grade_label(g)}</option>"

    subject_options = '<option value="">All Subjects</option>'
    for s in subject_rows:
        name = s["name"]
        selected = "selected" if subject_filter == name else ""
        subject_options += f"<option value='{escape(name)}' {selected}>{escape(name)}</option>"

    status_options = ""
    for st in ["NEW", "SHORTLISTED", "INTERVIEWED", "ACCEPTED", "REJECTED"]:
        selected = "selected" if status_filter == st else ""
        status_options += f"<option value='{st}' {selected}>{st}</option>"

    rows = ""
    
    return_params = {
        "q": q,
        "grade": grade_filter,
        "subject": subject_filter,
        "status": status_filter,
        "page": page_num
    }

    return_params = {
        k: v for k, v in return_params.items()
        if v not in ["", None]
    }

    return_url = url_for("admin_applications") + "?" + urlencode(return_params)
    encoded_return_url = quote_from_bytes(return_url.encode())

    for a in applications:
        try:
            grades = ", ".join([grade_label(g) for g in json.loads(a["grades"] or "[]")])
        except:
            grades = a["grades"] or "—"

        try:
            subjects = ", ".join(json.loads(a["subjects"] or "[]"))
        except:
            subjects = a["subjects"] or "—"

        rows += f"""
        <tr>
            <td>
                {escape(a['full_name'])}
                <div class="mini muted">{escape(a['phone'] or '')}</div>
            </td>
            <td>{escape(grades)}</td>
            <td>{escape(subjects)}</td>
            <td>{escape(a['highest_qualification'] or '—')}</td>
            <td><span class="chip">{escape(a['status'])}</span></td>
            <td>{a['created_at'][:16].replace('T',' ')}</td>
            <td style="white-space:nowrap">
                <a class="btn mini"
                   href="/admin/application/{a['id']}?return_url={encoded_return_url}">
                    View
                </a>

                {f'''
                <form method="post"
                      action="/admin/application/{a['id']}/delete"
                      onsubmit="return confirm('Delete this application?');"
                      style="display:inline">

                    <input type="hidden"
                           name="return_url"
                           value="{escape(return_url)}">

                    <button class="btn mini danger">
                        Delete
                    </button>
                </form>
                ''' if is_high_admin() else ''}
            </td>
        </tr>
        """

    query_params = {
        "q": q,
        "grade": grade_filter,
        "subject": subject_filter,
        "status": status_filter
    }

    query_params = {
        k: v for k, v in query_params.items()
        if v not in ["", None]
    }

    query_base = urlencode(query_params)

    page_links = []

    if page_num > 1:
        page_links.append(f"<a class='links' href='/admin/applications?{query_base}&page=1'>« First</a>")
        page_links.append(f"<a class='links' href='/admin/applications?{query_base}&page={page_num-1}'>‹ Prev</a>")

    page_links.append(f"<span class='chip'>Page {page_num} of {total_pages}</span>")

    if page_num < total_pages:
        page_links.append(f"<a class='links' href='/admin/applications?{query_base}&page={page_num+1}'>Next ›</a>")
        page_links.append(f"<a class='links' href='/admin/applications?{query_base}&page={total_pages}'>Last »</a>")

    pagination = f"""
    <div class="toolbar" style="margin-top:12px">
        {''.join(page_links)}
    </div>
    """

    body = f"""
    {admin_nav()}

    <section class="card">
        <h1>Tutor Applications</h1>

        <form method="get"
              class="toolbar"
              style="align-items:end">

            <div>
                <label>Search</label>
                <input name="q"
                       value="{escape(q)}"
                       placeholder="Name, phone, email, city, qualification"
                       style="min-width:260px">
            </div>

            <div>
                <label>Grade</label>
                <select name="grade">
                    {grade_options}
                </select>
            </div>

            <div>
                <label>Subject</label>
                <select name="subject">
                    {subject_options}
                </select>
            </div>

            <div>
                <label>Status</label>
                <select name="status">
                    <option value="">All Statuses</option>
                    {status_options}
                </select>
            </div>

            <button class="btn mini success">Apply</button>
            <a class="btn mini secondary" href="/admin/applications">Reset</a>
        </form>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(applications)} of {total} application(s).
        </div>

        {pagination}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Applicant</th>
                        <th>Grades</th>
                        <th>Subjects</th>
                        <th>Qualification</th>
                        <th>Status</th>
                        <th>Applied</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    {rows or "<tr><td colspan='7'>No applications found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination}
    </section>
    """

