@app.get('/admin/application/<int:app_id>')
@require_high_admin
def admin_application_detail(app_id):

    r = require_admin()
    if r: return r
    
    return_url = request.args.get("return_url", "").strip()

    if not return_url.startswith("/admin/applications"):
        return_url = url_for("admin_applications")

    encoded_return_url = quote_from_bytes(return_url.encode())

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT * FROM tutor_applications WHERE id=?", (app_id,))
    a = cur.fetchone()

    conn.close()

    if not a:
        return page("Not found", card_msg("Application not found."))

    try:
        grades = ", ".join([grade_label(g) for g in json.loads(a["grades"] or "[]")])
    except:
        grades = a["grades"] or "—"

