@app.get('/secretary/action-items')
def secretary_action_items():

    r = require_secretary()
    if r:
        return r

    sid = is_secretary()

    try:
        page_num = int(request.args.get("page", 1))
    except:
        page_num = 1

    if page_num < 1:
        page_num = 1

    per_page = 10
    offset = (page_num - 1) * per_page

    conn = get_db()
    cur = conn.cursor()

    cur.execute("""
        SELECT COUNT(*) AS c
        FROM secretary_action_items
        WHERE secretary_id=?
    """, (sid,))

    total_records = cur.fetchone()["c"] or 0
    total_pages = max(1, (total_records + per_page - 1) // per_page)

    if page_num > total_pages:
        page_num = total_pages
        offset = (page_num - 1) * per_page

    cur.execute("""
        SELECT *
        FROM secretary_action_items
        WHERE secretary_id=?
        ORDER BY 
            CASE status
                WHEN 'PENDING' THEN 1
                WHEN 'OVERDUE' THEN 2
                WHEN 'DONE' THEN 3
                ELSE 4
            END,
            deadline ASC
        LIMIT ? OFFSET ?
    """, (sid, per_page, offset))

    rows = cur.fetchall()
    conn.close()

    trs = ""

    today = datetime.datetime.now(ZoneInfo("Africa/Johannesburg")).date().isoformat()

    for a in rows:
        current_status = a["status"]

        if current_status == "PENDING" and a["deadline"] and a["deadline"] < today:
            current_status = "OVERDUE"

        done_button = f"""
        <a class="btn mini secondary" href="/secretary/action/{a['id']}/edit">
            Edit
        </a>
        """

        if current_status != "DONE":
            done_button += f"""
            <form method="post"
                  action="/secretary/action/{a['id']}/done"
                  style="display:inline">
                <button class="btn mini success">
                    Mark Done
                </button>
            </form>
            """
        else:
            done_button += """
            <span class='mini muted' style="margin-left:6px">
                Completed
            </span>
            """

        trs += f"""
        <tr>
            <td>{escape(a['task'])}</td>
            <td>{escape(a['responsible_person'] or '—')}</td>
            <td>{escape(a['deadline'] or '—')}</td>
            <td>{escape(a['followup_date'] or '—')}</td>
            <td><span class="chip">{escape(current_status)}</span></td>
            <td>{done_button}</td>
        </tr>
        """

    body = f"""
    {secretary_nav()}

    <section class="card">
        <h1>Action Items</h1>

        <div class="mini muted" style="margin:10px 0">
            Showing {len(rows)} of {total_records} action item(s).
        </div>

        {pagination_controls("/secretary/action-items", page_num, total_pages)}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Task</th>
                        <th>Responsible</th>
                        <th>Deadline</th>
                        <th>Follow-Up</th>
                        <th>Status</th>
                        <th>Action</th>
                    </tr>
                </thead>

                <tbody>
                    {trs or "<tr><td colspan='6'>No action items yet.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/secretary/action-items", page_num, total_pages)}
    </section>
    """

    return page("Action Items", body)


