@app.post('/admin/duty-admin/<int:did>/toggle')
def admin_duty_admin_toggle(did):

    r = require_admin()
    if r: return r

    if not is_high_admin():
        return page("Access Denied", card_msg("Only high admin can update Duty Admin accounts."))

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT is_active FROM duty_admins WHERE id=?", (did,))
    row = cur.fetchone()

    if row:
        new_status = 0 if row["is_active"] == 1 else 1

        cur.execute("""
            UPDATE duty_admins
            SET is_active=?,
                updated_at=?
            WHERE id=?
        """, (new_status, now_utc_iso(), did))

        conn.commit()

    conn.close()

    return redirect(url_for("admin_duty_admins"))
    
    
@app.get('/duty-admin')
def duty_admin_home():

    r = require_duty_admin()
    if r: return r

    month = get_admin_active_month()

    conn = get_db()
    cur = conn.cursor()

    cur.execute("SELECT COUNT(*) AS c FROM enrollments WHERE month=?", (month,))
    total_enrollments = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM enrollments WHERE month=? AND status='PENDING'", (month,))
    pending = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM enrollments WHERE month=? AND status='ACTIVE'", (month,))
    active = cur.fetchone()["c"] or 0

    cur.execute("""
        SELECT COUNT(DISTINCT student_id) AS c
        FROM enrollments
        WHERE month=?
    """, (month,))
    students = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM messages WHERE resolved=0")
    inbox_count = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM direct_messages WHERE to_role='admin' AND is_read=0")
    dm_unread = cur.fetchone()["c"] or 0

    cur.execute("SELECT COUNT(*) AS c FROM followups WHERE followup_status!='RESOLVED'")
    open_followups = cur.fetchone()["c"] or 0

    conn.close()

    body = f"""
    {duty_admin_nav()}

    <section class="card">
        <h1>Duty Admin Dashboard</h1>

        <p class="muted">
            Welcome, {escape(session.get("duty_admin_name", "Duty Admin"))}.
            This portal is for daily admin operations and follow-ups.
        </p>

        <div class="stats">
            {stat("Current Month", month)}
            {stat("Students", str(students))}
            {stat("Enrollments", str(total_enrollments))}
            {stat("Pending", str(pending))}
            {stat("Active", str(active))}
            {stat("Inbox", str(inbox_count))}
            {stat("Direct Msgs", str(dm_unread))}
            {stat("Open Follow-Ups", str(open_followups))}
        </div>
    </section>
    """

    return page("Duty Admin", body)
    
@app.get('/duty-admin/enrollments')
def duty_admin_enrollments():

    r = require_duty_admin()
    if r: return r

    month = request.args.get("month", "").strip() or get_admin_active_month()

    q = request.args.get("q", "").strip()
    status = request.args.get("status", "").strip()
    grade = request.args.get("grade", "").strip()
    
    page_num = max(1, int(request.args.get("page", 1)))
    limit = 15
    offset = (page_num - 1) * limit

    conn = get_db()
    cur = conn.cursor()

    where = ["e.month = ?"]
    params = [month]

    if q:
        search = f"%{q}%"
        where.append("""
            (
                s.full_name LIKE ?
                OR s.phone_whatsapp LIKE ?
                OR s.guardian_phone LIKE ?
                OR s.email LIKE ?
                OR sub.name LIKE ?
            )
        """)
        params += [search, search, search, search, search]

    if status:
        where.append("e.status = ?")
        params.append(status)

    if grade:
        where.append("s.grade = ?")
        params.append(grade)

    where_sql = " AND ".join(where)
    
    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM enrollments e
        JOIN students s ON s.id = e.student_id
        JOIN subjects sub ON sub.id = e.subject_id
        WHERE {where_sql}
    """, params)

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + limit - 1) // limit)

    data_params = list(params)
    data_params.extend([limit, offset])

    cur.execute(f"""
        SELECT
            e.id,
            e.month,
            e.status,
            e.payment_method,
            e.payment_ref,
            e.pop_url,
            e.amount_paid,
            e.created_at,

            s.full_name,
            s.phone_whatsapp,
            s.guardian_name,
            s.guardian_phone,
            s.email,
            s.grade,

            sub.name AS subject_name,
            sub.grade AS subject_grade

        FROM enrollments e
        JOIN students s ON s.id = e.student_id
        JOIN subjects sub ON sub.id = e.subject_id
        WHERE {where_sql}
        ORDER BY e.created_at DESC
        LIMIT ? OFFSET ?
    """, data_params)

    rows = cur.fetchall()
    conn.close()

    trs = ""

    for r0 in rows:
        pop_link = "—"

        if r0["pop_url"]:
            pop_link = f"<a target='_blank' href='{escape(r0['pop_url'])}'>PoP</a>"

        amount = r0["amount_paid"] if r0["amount_paid"] not in [None, ""] else "—"

        status_class = "pending"
        if r0["status"] == "ACTIVE":
            status_class = "active"
        elif r0["status"] == "LAPSED":
            status_class = "lapsed"

        trs += f"""
        <tr>
            <td>
                <strong>{escape(r0['full_name'])}</strong>
                <div class="mini muted">{escape(r0['phone_whatsapp'] or '')}</div>
            </td>

            <td>{grade_label(r0['grade'])}</td>

            <td>
                {escape(r0['subject_name'])}
                <div class="mini muted">{grade_label(r0['subject_grade'])}</div>
            </td>

            <td><span class="chip {status_class}">{escape(r0['status'])}</span></td>

            <td>{pop_link}</td>

            <td>R{escape(str(amount))}</td>

            <td>
                <div class="mini muted">
                    Guardian: {escape(r0['guardian_name'] or '—')}<br>
                    Guardian Phone: {escape(r0['guardian_phone'] or '—')}<br>
                    Email: {escape(r0['email'] or '—')}
                </div>
            </td>

            <td>{escape((r0['created_at'] or '')[:16].replace('T',' '))}</td>
        </tr>
        """

    body = f"""
    {duty_admin_nav()}

    <section class="card">
        <h1>Enrollments View</h1>

        <p class="muted">
            View enrollment information for the selected month.
            This page does not allow approval, SMS sending, lapsing, or pending changes.
        </p>

        <form method="get" class="toolbar">

            <input type="month"
                   name="month"
                   value="{escape(month)}"
                   title="Filter by enrollment month">

            <input name="q"
                   value="{escape(q)}"
                   placeholder="Search student, phone, subject or email">

            <select name="grade">
                <option value="">All Grades</option>
                {''.join(
                    f"<option value='{g}' {'selected' if grade==g else ''}>{grade_label(g)}</option>"
                    for g in ["G8","G9","G10","G11","G12","G13"]
                )}
            </select>

            <select name="status">
                <option value="">All Statuses</option>
                <option value="PENDING" {'selected' if status=="PENDING" else ""}>PENDING</option>
                <option value="ACTIVE" {'selected' if status=="ACTIVE" else ""}>ACTIVE</option>
                <option value="LAPSED" {'selected' if status=="LAPSED" else ""}>LAPSED</option>
            </select>

            <button class="btn mini">Filter</button>
        </form>
        
        
        <div class="mini muted" style="margin:10px 0">
            Showing enrollments for: <b>{pretty_month_label(month)}</b>
        </div>
        
        {pagination_controls("/duty-admin/enrollments", page_num, total_pages, {"month": month, "q": q, "grade": grade, "status": status})}
        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Student</th>
                        <th>Grade</th>
                        <th>Subject</th>
                        <th>Status</th>
                        <th>PoP</th>
                        <th>Amount</th>
                        <th>Contact Details</th>
                        <th>Timestamp</th>
                    </tr>
                </thead>

                <tbody>
                    {trs or "<tr><td colspan='8'>No enrollments found.</td></tr>"}
                </tbody>
            </table>
        </div>
        {pagination_controls("/duty-admin/enrollments", page_num, total_pages, {"month": month, "q": q, "grade": grade, "status": status})}
    </section>
    """

    return page("Duty Admin Enrollments", body)
    

@app.get('/duty-admin/students')
def duty_admin_students():

    r = require_duty_admin()
    if r: return r

    q = request.args.get("q", "").strip()
    grade = request.args.get("grade", "").strip()
    month = request.args.get("month", "").strip() or get_admin_active_month()
    
    page_num = max(1, int(request.args.get("page", 1)))
    limit = 15
    offset = (page_num - 1) * limit

    conn = get_db()
    cur = conn.cursor()

    where = ["e.month = ?"]
    params = [month]

    if q:
        search = f"%{q}%"
        where.append("""
            (
                s.full_name LIKE ?
                OR s.phone_whatsapp LIKE ?
                OR s.guardian_phone LIKE ?
                OR IFNULL(s.guardian_name, '') LIKE ?
                OR IFNULL(s.email, '') LIKE ?
                OR IFNULL(s.school, '') LIKE ?
                OR IFNULL(s.province, '') LIKE ?
                OR sub.name LIKE ?
                OR e.status LIKE ?
            )
        """)
        params += [
            search, search, search, search, search,
            search, search, search, search
        ]

    if grade:
        where.append("s.grade = ?")
        params.append(grade)

    where_sql = "WHERE " + " AND ".join(where)

    cur.execute(f"""
        SELECT COUNT(DISTINCT s.id) AS c
        FROM students s
        JOIN enrollments e ON e.student_id = s.id
        JOIN subjects sub ON sub.id = e.subject_id
        {where_sql}
    """, params)

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + limit - 1) // limit)

    data_params = list(params)
    data_params.extend([limit, offset])

    cur.execute(f"""
        SELECT
            s.*,
            GROUP_CONCAT(DISTINCT sub.name) AS enrolled_subjects,
            GROUP_CONCAT(DISTINCT e.status) AS enrollment_statuses
        FROM students s
        JOIN enrollments e ON e.student_id = s.id
        JOIN subjects sub ON sub.id = e.subject_id
        {where_sql}
        GROUP BY s.id
        ORDER BY CAST(REPLACE(s.grade,'G','') AS INTEGER), s.full_name
        LIMIT ? OFFSET ?
    """, data_params)

    rows = cur.fetchall()
    conn.close()

    trs = ""

    for s in rows:
        trs += f"""
        <tr>
            <td>
                <strong>{escape(s['full_name'])}</strong>
                <div class="mini muted">PIN: {escape(s['pin'] or '—')}</div>
            </td>
            <td>{grade_label(s['grade'])}</td>
            <td>{escape(s['phone_whatsapp'] or '—')}</td>
            <td>
                {escape(s['guardian_name'] or '—')}
                <div class="mini muted">{escape(s['guardian_phone'] or '—')}</div>
            </td>
            <td>{escape(s['email'] or '—')}</td>
            <td>
                {escape(s['school'] or '—')}
                <div class="mini muted">{escape(s['province'] or '—')}</div>
            </td>

            <td>
                {escape(s['enrolled_subjects'] or '—')}
                <div class="mini muted">
                    Status: {escape(s['enrollment_statuses'] or '—')}
                </div>
            </td>

            <td>{escape((s['created_at'] or '')[:16].replace('T',' '))}</td>
        </tr>
        """

    body = f"""
    {duty_admin_nav()}

    <section class="card">
        <h1>Students</h1>

        <p class="muted">
            View learner details captured on the portal. Editing and deletion are restricted.
        </p>

        <form method="get" class="toolbar">
            <input name="q"
                   value="{escape(q)}"
                   placeholder="Search name, phone, guardian, email, school or province">

            <select name="grade">
                <option value="">All Grades</option>
                {''.join(
                    f"<option value='{g}' {'selected' if grade==g else ''}>{grade_label(g)}</option>"
                    for g in ["G8","G9","G10","G11","G12","G13"]
                )}
            </select>

            <button class="btn mini">Search</button>
        </form>
        
        {pagination_controls("/duty-admin/students", page_num, total_pages, {"q": q, "grade": grade})}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Student</th>
                        <th>Grade</th>
                        <th>Phone</th>
                        <th>Guardian</th>
                        <th>Email</th>
                        <th>School / Province</th>
                        <th>Subjects This Month</th>
                        <th>Created</th>
                    </tr>
                </thead>
                <tbody>
                    {trs or "<tr><td colspan='8'>No students found.</td></tr>"}
                </tbody>
            </table>
        </div>
        
        {pagination_controls("/duty-admin/students", page_num, total_pages, {"q": q, "grade": grade})}
    </section>
    """

    return page("Duty Admin Students", body)
    
    
@app.get('/duty-admin/groups')
def duty_admin_groups():

    r = require_duty_admin()
    if r:
        return r

    month = get_admin_active_month()

    page_num = max(1, int(request.args.get("page", 1)))
    limit = 15
    offset = (page_num - 1) * limit

    conn = get_db()
    cur = conn.cursor()

    # Count both current-month groups and permanent ALL groups
    cur.execute("""
        SELECT COUNT(*) AS c
        FROM groups g
        JOIN subjects sub ON sub.id = g.subject_id
        WHERE (g.month = ? OR g.month = 'ALL')
          AND g.is_visible = 1
    """, (month,))

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + limit - 1) // limit)

    cur.execute("""
        SELECT
            g.*,
            sub.name AS subject_name,
            sub.grade AS subject_grade
        FROM groups g
        JOIN subjects sub ON sub.id = g.subject_id
        WHERE (g.month = ? OR g.month = 'ALL')
          AND g.is_visible = 1
        ORDER BY
            CASE WHEN g.month = 'ALL' THEN 0 ELSE 1 END,
            CAST(REPLACE(sub.grade,'G','') AS INTEGER),
            sub.name
        LIMIT ? OFFSET ?
    """, (month, limit, offset))

    rows = cur.fetchall()
    conn.close()

    trs = ""

    for g in rows:
        visible = "Visible" if g["is_visible"] == 1 else "Hidden"

        if g["month"] == "ALL":
            group_type = "Permanent"
        else:
            group_type = pretty_month_label(g["month"])

        invite = "—"

        if g["invite_link"]:
            invite = f"<a target='_blank' href='{escape(g['invite_link'])}'>Open Group</a>"

        trs += f"""
        <tr>
            <td>{grade_label(g['subject_grade'])}</td>
            <td>{escape(g['subject_name'])}</td>
            <td>{escape(group_type)}</td>
            <td>{invite}</td>
            <td><span class="chip">{visible}</span></td>
            <td>{escape((g['created_at'] or '')[:16].replace('T',' '))}</td>
        </tr>
        """

    body = f"""
    {duty_admin_nav()}

    <section class="card">
        <h1>Group Links</h1>

        <p class="muted">
            View visible group links. This includes permanent group links and current-month group links.
            Creating, editing and deleting groups are restricted.
        </p>

        {pagination_controls("/duty-admin/groups", page_num, total_pages)}

        <div class="scroll-x">
            <table>
                <thead>
                    <tr>
                        <th>Grade</th>
                        <th>Subject</th>
                        <th>Group Type / Month</th>
                        <th>Group Link</th>
                        <th>Visibility</th>
                        <th>Created</th>
                    </tr>
                </thead>

                <tbody>
                    {trs or "<tr><td colspan='6'>No visible group links found.</td></tr>"}
                </tbody>
            </table>
        </div>

        {pagination_controls("/duty-admin/groups", page_num, total_pages)}
    </section>
    """

    return page("Duty Admin Groups", body)
    
  
