    cur = conn.cursor()

    # Get all subjects for checkbox list
    cur.execute("""
        SELECT DISTINCT name
        FROM subjects
        ORDER BY name
    """)
    subject_rows = [x["name"] for x in cur.fetchall()]

    where = []
    params = []

    if q:
        search = f"%{q}%"
        where.append("""
            (
                full_name LIKE ?
                OR phone LIKE ?
                OR subjects LIKE ?
                OR notes LIKE ?
                OR issue_type LIKE ?
            )
        """)
        params += [search, search, search, search, search]

