@app.post('/admission/enrollment/<int:id>/<action>')
def admission_enrollment_action(id, action):

    r = require_admission_coordinator()
    if r:
        return r

    allowed_actions = ["approve", "approve_sms", "sms", "lapse"]

    if action not in allowed_actions:
        return page("Invalid Action", card_msg("Invalid enrollment action."))
        
    status_changing_actions = ["approve", "approve_sms", "lapse"]

    if action in status_changing_actions and enrollment_status_actions_locked():
        return page(
            "Approvals Locked",
            card_msg(
                "Enrollment approvals and rejections are currently locked by High Admin. "
                "Please contact High Admin if this enrollment needs to be approved or lapsed."
            )
        )

    conn = get_db()
    cur = conn.cursor()

    notify_phone = None
    notify_name = None
    notify_pin = None
    notify_subject = None
    notify_grade = None
    notify_month = None

    needs_sms_details = action in ["approve_sms", "sms"]
    should_approve = action in ["approve", "approve_sms"]

    if should_approve:
        cur.execute("""
            UPDATE enrollments
            SET status='ACTIVE'
            WHERE id=?
        """, (id,))

    elif action == "lapse":
        cur.execute("""
            UPDATE enrollments
            SET status='LAPSED'
            WHERE id=?
        """, (id,))

    if needs_sms_details:
        cur.execute("""
            SELECT
                st.id,
                st.full_name,
                st.phone_whatsapp,
                st.pin,
                e.month,
                sub.name AS subject_name,
                sub.grade
            FROM enrollments e
            JOIN students st ON st.id = e.student_id
            JOIN subjects sub ON sub.id = e.subject_id
            WHERE e.id=?
        """, (id,))

        row = cur.fetchone()

        if row:
            notify_name = row["full_name"]
            notify_phone = row["phone_whatsapp"]
            notify_pin = row["pin"]
            notify_month = row["month"]
            notify_subject = row["subject_name"]
            notify_grade = row["grade"]

            if not notify_pin:
                pins = set()

                cur.execute("SELECT pin FROM students WHERE pin IS NOT NULL")
                pins |= {x["pin"] for x in cur.fetchall()}

                cur.execute("SELECT pin FROM tutors WHERE pin IS NOT NULL")
                pins |= {x["pin"] for x in cur.fetchall()}

                new_pin = gen_pin(pins)

                cur.execute("""
                    UPDATE students
                    SET pin=?
                    WHERE id=?
                """, (new_pin, row["id"]))

                notify_pin = new_pin

    conn.commit()
    conn.close()

    try:
        if needs_sms_details and notify_phone and notify_pin:

            base_url = (request.url_root or "").rstrip("/")
            login_link = base_url + url_for("student_login")

            month_label = pretty_month_label(notify_month) if notify_month else ""
            grade_label_txt = grade_label(notify_grade) if notify_grade else ""
            first_name = notify_name.split()[0] if notify_name else ""

            if action == "approve_sms":
                sms_intro = f"EBTA: Hi {first_name}, your enrollment is APPROVED."
            else:
                sms_intro = f"EBTA: Hi {first_name}, your portal login details are below."

            sms_body_parts = [sms_intro]

            if notify_subject:
                sms_body_parts.append(f"Subject: {grade_label_txt} {notify_subject}")

            if month_label:
                sms_body_parts.append(f"Month: {month_label}")

            sms_body_parts.append(f"Login: {login_link}")
            sms_body_parts.append(f"PIN: {notify_pin}")

            sms_body = "\n".join(sms_body_parts)

            send_sms_notification(notify_phone, sms_body)

    except Exception as e:
        print("Admission SMS error:", e)

    return redirect(request.referrer or url_for("admission_enrollments"))
    
    
@app.get('/admission/enrollments')
def admission_enrollments():

    r = require_admission_coordinator()
    if r:
        return r

    month = request.args.get("month", "").strip() or get_admin_active_month()

    q = request.args.get("q", "").strip()
    status = request.args.get("status", "").strip()
    grade = request.args.get("grade", "").strip()

    page_num = max(1, int(request.args.get("page", 1)))
    limit = 15
    offset = (page_num - 1) * limit

    conn = get_db()
    cur = conn.cursor()

    where = ["e.month = ?"]
    params = [month]

    if q:
        search = f"%{q}%"
        where.append("""
            (
                s.full_name LIKE ?
                OR s.phone_whatsapp LIKE ?
                OR s.guardian_phone LIKE ?
                OR s.email LIKE ?
                OR sub.name LIKE ?
            )
        """)
        params += [search, search, search, search, search]

    if status:
        where.append("e.status = ?")
        params.append(status)

    if grade:
        where.append("s.grade = ?")
        params.append(grade)

    where_sql = " AND ".join(where)

    cur.execute(f"""
        SELECT COUNT(*) AS c
        FROM enrollments e
        JOIN students s ON s.id = e.student_id
        JOIN subjects sub ON sub.id = e.subject_id
        WHERE {where_sql}
    """, params)

    total = cur.fetchone()["c"] or 0
    total_pages = max(1, (total + limit - 1) // limit)

    data_params = list(params)
    data_params.extend([limit, offset])

    cur.execute(f"""
        SELECT
            e.id,
            e.month,
            e.status,
            e.payment_method,
            e.payment_ref,
            e.pop_url,
            e.amount_paid,
            e.created_at,
            
            e.coupon_code,
            e.coupon_discount_amount,
            e.coupon_type,
            e.referral_code_used,

            s.full_name,
            s.phone_whatsapp,
            s.guardian_name,
            s.guardian_phone,
            s.email,
            s.grade,

            sub.name AS subject_name,
            sub.grade AS subject_grade,

            (
                SELECT COUNT(DISTINCT e2.month)
                FROM enrollments e2
                WHERE e2.student_id = s.id
                  AND e2.month < e.month
            ) AS previous_month_count,

            (
                SELECT MIN(e3.month)
                FROM enrollments e3
                WHERE e3.student_id = s.id
            ) AS first_enrolled_month

        FROM enrollments e
        JOIN students s ON s.id = e.student_id
        JOIN subjects sub ON sub.id = e.subject_id
        WHERE {where_sql}
        ORDER BY e.created_at DESC
        LIMIT ? OFFSET ?
    """, data_params)

    rows = cur.fetchall()
    conn.close()

    trs = ""

    for row in rows:
        pop_link = "—"
        
        history_label = "First month"

        if row["previous_month_count"] and int(row["previous_month_count"]) > 0:
            history_label = "Returning student"

        history_html = f"""
        <span class="chip {'active' if history_label == 'First month' else 'pending'}">
            {history_label}
        </span>
        <div class="mini muted">
            First enrolled: {escape(row['first_enrolled_month'] or '—')}
        </div>
        """


        if row["pop_url"]:
            pop_link = f"<a target='_blank' href='{escape(row['pop_url'])}'>PoP</a>"

        amount = row["amount_paid"] if row["amount_paid"] not in [None, ""] else "—"
        
        
